    override fun onCreate() {
        super.onCreate()

        isRunning = false
        shuttingDown = false

        createNotificationChannel()

        promoteToForeground(
            "AYANA запускает локальное распознавание"
        )

        // IMPORTANT: onCreate() may be called for ACTION_STOP or another
        // service intent. Never create the overlay here. The single Orb is
        // created only after a real ACTION_START / active text command.
        ayanaPreferences.miniOrbEnabled = true

        currentStatusText =
            "AYANA запускается"

        currentStatusState =
            STATE_THINKING

        try {
            durableGoalStore
                .markInterruptedGoals(
                    "service_recreated"
                )
        } catch (_: Exception) {
        }

        prefetchReadyVoice()

        thread(
            start = true,
            name = "AyanaModelInit"
        ) {
            try {

                initSherpaModel()

                modelReady = true
                capabilityRegistry
                    .recordRecognitionReady(
                        true
                    )

                mainHandler.post {
                    if (
                        !shuttingDown &&
                        isRunning
                    ) {
                        startWakeListening()
                    }
                }

            } catch (_: Exception) {

                modelReady = false
                capabilityRegistry
                    .recordRecognitionReady(
                        false
                    )

                mainHandler.post {
                    broadcastStatus(
                        "Не удалось загрузить локальную модель",
                        STATE_ERROR
                    )

                    updateNotification(
                        "Ошибка локального распознавания"
                    )
                }
            }
        }

        // The worker waits until AYANA is fully active + wake-idle, so starting
        // the scheduler here does not compete with model initialization.
        backgroundImageIndexer.start()
    }

    override fun onStartCommand(
        intent: Intent?,
        flags: Int,
        startId: Int
    ): Int {

        when (intent?.action) {

            ACTION_STOP -> {
                shutdownAyana()
                return START_NOT_STICKY
            }

            ACTION_CANCEL_COMMAND -> {
                cancelCurrentCommand(
                    source = "button"
                )
                return START_STICKY
            }

            ACTION_RESUME_GOAL -> {

                isRunning =
                    true

                ensureOrbForActiveService()

                mainHandler.post {
                    resumeDurableGoal(
                        silent = true,
                        explicitConfirmation = false,
                        allowAutoResume = false
                    )
                }

                return START_STICKY
            }

            ACTION_CONFIRM_GOAL -> {

                isRunning =
                    true

                ensureOrbForActiveService()

                mainHandler.post {
                    resumeDurableGoal(
                        silent = true,
                        explicitConfirmation = true,
                        allowAutoResume = false
                    )
                }

                return START_STICKY
            }

            ACTION_CANCEL_GOAL -> {

                isRunning =
                    true

                ensureOrbForActiveService()
mainHandler.post {
                    cancelDurableGoalFromControl(
                        silent = true
                    )
                }

                return START_STICKY
            }

            ACTION_START -> {

                isRunning =
                    true

                ayanaPreferences.miniOrbEnabled =
                    true

                miniOrbController.refresh(
                    enabled = true,
                    state =
                        if (
                            currentStatusState ==
                            STATE_STOPPED
                        ) {
                            STATE_LISTENING
                        } else {
                            currentStatusState
                        }
                )

                if (
                    !shuttingDown &&
                    modelReady &&
                    !isRecording &&
                    listenMode != ListenMode.BUSY &&
                    listenMode != ListenMode.CANCEL
                ) {
                    startWakeListening()
                }

                maybeAutoResumeDurableGoal()
            }

            ACTION_REFRESH_OVERLAY -> {

                if (
                    isRunning &&
                    !shuttingDown &&
                    currentStatusState !=
                    STATE_STOPPED
                ) {

                    ayanaPreferences.miniOrbEnabled =
                        true

                    miniOrbController.refresh(
                        enabled = true,
                        state =
                            currentStatusState
                    )
                }
            }

            ACTION_MULTIMODAL_COMMAND -> {

                val command =
                    intent.getStringExtra(
                        EXTRA_TEXT_COMMAND
                    )
                        ?.trim()
                        .orEmpty()

                val manifest =
                    intent.getStringExtra(
                        EXTRA_MULTIMODAL_MANIFEST
                    )
                        ?.trim()
                        .orEmpty()

                if (
                    command.isNotBlank() &&
                    manifest.isNotBlank()
                ) {
                    isRunning = true
                    ayanaPreferences.miniOrbEnabled = true
                    miniOrbController.refresh(
                        enabled = true,
                        state = currentStatusState
                    )
                    stopSherpaListening()
                    mainHandler.post {
                        if (!shuttingDown) {
                            executeMultimodalCommand(
                                command,
                                manifest
                            )
                        }
                    }
                }
            }

            ACTION_TEXT_COMMAND -> {

                val command =
                    intent.getStringExtra(
                        EXTRA_TEXT_COMMAND
                    )
                        ?.trim()
                        .orEmpty()

                if (command.isNotBlank()) {

                    isRunning =
                        true

                    ayanaPreferences.miniOrbEnabled =
                        true

                    miniOrbController.refresh(
                        enabled = true,
                        state =
                            currentStatusState
                    )

                    stopSherpaListening()

                    // INSTANT TEXT v2.7.4.4
                    // Text input is already final; unlike voice it does not need an
                    // endpoint/grace delay. Queue it on the main handler immediately.
                    mainHandler.post {
                        if (!shuttingDown) {
                            executeCommand(
                                command,
                                silent = true
                            )
                        }
                    }
                }
            }

            null -> {
                // START_STICKY process recreation. Unlike BOOT_COMPLETED, this
                // is a service lifecycle recovery. Restore only a recent,
                // explicitly low-risk goal and keep the recovery bounded.
                isRunning =
                    true

                ensureOrbForActiveService()

                if (
                    !shuttingDown &&
                    modelReady &&
                    !isRecording
                ) {
                    startWakeListening()
                }

                maybeAutoResumeDurableGoal()
            }
        }

        return START_STICKY
    }

