    private fun openMapSearch(
        query: String,
        silent: Boolean
    ) {

        val uri =
            Uri.parse(
                "geo:0,0?q=" +
                    Uri.encode(query)
            )

        try {

            startActivity(
                Intent(
                    Intent.ACTION_VIEW,
                    uri
                ).apply {

                    setPackage(
                        "com.google.android.apps.maps"
                    )

                    addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK
                    )
                }
            )

            finishLocalCommand(
                "Ищу на карте: $query",
                silent
            )

        } catch (
            _: ActivityNotFoundException
        ) {

            try {

                startActivity(
                    Intent(
                        Intent.ACTION_VIEW,
                        uri
                    ).apply {

                        addFlags(
                            Intent.FLAG_ACTIVITY_NEW_TASK
                        )
                    }
                )

                finishLocalCommand(
                    "Ищу на карте: $query",
                    silent
                )

            } catch (
                _: ActivityNotFoundException
            ) {

                respondAndResume(
                    "Не удалось открыть карты.",
                    silent,
                    success = false
                )
            }
        }
    }

    /**
     * v11.1.2 ROUTING ENVELOPE SANITIZER.
     *
     * Text-mode copy/paste and some keyboards can wrap a complete command in
     * typographic quotes or brackets. Those characters must not change the route
     * (for example «открой Gmail» must remain a local app-launch command).
     *
     * Only leading/trailing envelope punctuation is removed. Internal punctuation
     * is preserved so search queries and user text are not rewritten globally.
     */
    private fun sanitizeRoutingEnvelope(
        value: String
    ): String {

        var result =
            value
                .trim()

        val wrapperPairs =
            listOf(
                '«' to '»',
                '“' to '”',
                '„' to '“',
                '"' to '"',
                '\'' to '\'',
                '`' to '`',
                '(' to ')',
                '[' to ']',
                '{' to '}'
            )

        var changed: Boolean

        do {
            changed = false

            for ((opening, closing) in wrapperPairs) {
                if (
                    result.length >= 2 &&
                    result.first() == opening &&
                    result.last() == closing
                ) {
                    result =
                        result
                            .substring(
                                1,
                                result.length - 1
                            )
                            .trim()

                    changed = true
                    break
                }
            }
        } while (changed)

        return result
            .replace(
                Regex("\\s+"),
                " "
            )
            .trim()
    }

    private fun repairCommonRecognitionForRouting(
        value: String
    ): String {

        var repaired =
            value
                .lowercase(
                    Locale.ROOT
                )
                .replace('ё', 'е')
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        // Conservative, device-observed substitutions only. These repairs are
        // intentionally NOT used as the text sent to Agent Core.
        repaired =
            repaired
                .replace(
                    Regex("(?<!\\p{L})(?:плютус|блютус|блютузс)(?!\\p{L})"),
                    "блютуз"
                )
                .replace(
                    Regex("^то будет\\s+"),
                    "сколько будет "
                )
                .replace(
                    Regex("^(?:тон|то)\\s+на\\s+экране(?:\\s+сейчас)?$"),
                    "что на экране"
                )

        // LOCAL ROUTING v9.1:
        // Sherpa can lose the first syllable of «открой» (observed: «трой ютуб»).
        // Never rewrite an arbitrary phrase globally. Repair the truncated verb
        // only when the rest of the utterance is an exact known local launch target.
        val truncatedLaunch =
            Regex(
                """^(?:трой|ткрой|крой|рой|откро|аткрой)\s+(.+)$"""
            )
                .matchEntire(
                    repaired
                )

        if (
            truncatedLaunch !=
            null
        ) {
            val target =
                truncatedLaunch
                    .groupValues[1]
                    .trim()

            if (
                target in
                KNOWN_LOCAL_LAUNCH_ALIASES
            ) {
                repaired =
                    "открой $target"
            }
        }

        return repaired
    }

    private fun localAcknowledgementReply(
        command: String
    ): String? {

        return when (
            command
                .lowercase(
                    Locale.ROOT
                )
                .trim()
        ) {
            "спасибо",
            "спасибо тебе",
            "благодарю",
            "благодарю тебя" ->
                "Пожалуйста."

            "ок",
            "окей",
            "хорошо",
            "понял",
            "поняла",
            "ясно" ->
                "Хорошо."

            else ->
                null
        }
    }

    private fun isExplicitSelfDiagnosticsRequest(
        command: String
    ): Boolean {

        val normalized =
            command
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        val questionLike =
            normalized.startsWith("ты ") ||
                normalized.startsWith("как ") ||
                normalized.startsWith("что ") ||
                normalized.startsWith("почему ") ||
                normalized.startsWith("когда ") ||
                normalized.startsWith("где ") ||
                normalized.startsWith("можешь ") ||
                normalized.startsWith("умеешь ") ||
                normalized.contains("диагностируешь") ||
                normalized.contains("проводишь диагности")

        if (questionLike) {
            return false
        }

        val selfScope =
            normalized.contains("себ") ||
                normalized.contains("аяна") ||
                normalized.contains("систем")

        val explicitDiagnosticVerb =
            normalized.contains("продиагност") ||
                normalized.contains("продиганост") ||
                normalized.contains("диагностируй") ||
                normalized.contains("запусти диагност") ||
                normalized.contains("выполни диагност") ||
                normalized.contains("самодиагност")

        val explicitCheckSelf =
            (
                normalized.contains("проверь") ||
                    normalized.contains("проверить")
                ) &&
                selfScope

        return (
            explicitDiagnosticVerb &&
                selfScope
            ) ||
            explicitCheckSelf
    }

    private fun runLocalSelfDiagnosticsCommand(
        silent: Boolean
    ) {

        broadcastStatus(
            "Проверяю своё состояние…",
            STATE_EXECUTING
        )

        val rawResult =
            try {
                selfDiagnostics.run(
                    focus = "all",
                    appName = ""
                )
            } catch (error: Exception) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "local_self_diagnostics_error",
                    message = "Локальная самодиагностика завершилась исключением",
                    details =
                        error.message
                            .orEmpty()
                            .take(
                                500
                            )
                )

                respondAndResume(
                    text = "Не удалось выполнить локальную самодиагностику.",
                    silent = silent,
                    success = false,
                    technical =
                        "local_self_diagnostics_exception"
                )
                return
            }

        // R9.0: presentation freshness is resolved against real recent History.
        // Stale Agent Core/TTS evidence stays UNKNOWN; an old command ERROR may
        // become recovered only after newer successful device evidence exists.
        val result =
            diagnosticClosure
                .normalizeSelfDiagnostics(
                    raw = rawResult,
                    recentHistory =
                        commandHistoryStore
                            .recent(
                                24
                            )
                )

        val report =
            diagnosticClosure
                .reportFromNormalized(
                    result
                )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_self_diagnostics",
            message = "Самодиагностика выполнена локально без Agent Core",
            details =
                (
                    "closure=${AyanaDiagnosticClosure.VERSION}; " +
                        "overall=${result.optString("overall_status")}; " +
                        "passed=${result.optInt("passed")}; " +
                        "warnings=${result.optInt("warnings")}; " +
                        "unknown=${result.optInt("unknown")}; " +
                        "failed=${result.optInt("failed")}; " +
                        "successes_after_last_error=${result.optInt("successes_after_last_error", 0)}"
                    )
                    .take(
                        900
                    )
        )

        // A diagnostic command succeeded when the diagnostic transaction itself
        // completed. Detected component WARN/FAIL states are reported in content and
        // must not rewrite the command execution into ERROR.
        respondAndResume(
            text = report,
            silent = silent,
            success = true
        )
    }

    private data class LocalTextInputRequest(
        val text: String,
        val target: String
    )

    private fun extractLocalTextInputRequest(
        originalCommand: String
    ): LocalTextInputRequest? {
        val clean =
            originalCommand
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        val match =
            Regex(
                """^(?:введи|впиши|напечатай)\s+(?:текст\s+)?(.+?)\s+в\s+(поле\s+.+)$""",
                RegexOption.IGNORE_CASE
            )
                .matchEntire(
                    clean
                )
                ?: return null

        val text =
            match
                .groupValues[1]
                .trim()

        val target =
            match
                .groupValues[2]
                .trim()

        if (
            text.isBlank() ||
            target.isBlank()
        ) {
            return null
        }

        return LocalTextInputRequest(
            text = text.take(
                4000
            ),
            target = target.take(
                300
            )
        )
    }

    private fun runLocalTextInputCommand(
        request: LocalTextInputRequest,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_semantic_input",
            executor = "screen_input_executor"
        )

        val result =
            try {
                screenIntelligence
                    .inputText(
                        target =
                            request.target,
                        text =
                            request.text
                    )
            } catch (error: Exception) {
                respondAndResume(
                    text = "Не удалось выполнить локальный ввод текста.",
                    silent = silent,
                    success = false,
                    technical =
                        "local_semantic_input_exception:" +
                            error.javaClass.simpleName
                )
                return
            }

        val verified =
            result.optBoolean(
                "verified",
                result.optBoolean(
                    "success",
                    false
                )
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (verified) {
                    "local_semantic_input_verified"
                } else {
                    "local_semantic_input_unverified"
                },
            message =
                if (verified) {
                    "Текст введён и подтверждён локально"
                } else {
                    "Локальный ввод не подтверждён"
                },
            details =
                (
                    "target=${request.target.take(180)}; " +
                        "status=${result.optString("status")}; " +
                        "reason=${result.optString("reason")}; " +
                        "verified=$verified"
                    )
                    .take(
                        900
                    )
        )

        if (verified) {
            finishLocalCommand(
                "Текст ${request.text.take(120)} введён в ${request.target}.",
                silent
            )
        } else {
            val terminal =
                when (
                    result
                        .optString(
                            "terminal_status"
                        )
                        .uppercase(
                            Locale.ROOT
                        )
                ) {
                    "BLOCKED" ->
                        AyanaCommandHistoryStore.STATUS_BLOCKED

                    "UNSUPPORTED" ->
                        AyanaCommandHistoryStore.STATUS_UNSUPPORTED

                    else ->
                        null
                }

            respondAndResume(
                text =
                    result
                        .optString(
                            "message",
                            "Не удалось подтвердить ввод текста в указанное поле."
                        ),
                silent = silent,
                success = false,
                terminalStatus = terminal,
                technical =
                    "local_semantic_input_unverified:" +
                        result.optString(
                            "reason",
                            result.optString(
                                "status"
                            )
                        )
            )
        }
    }


    private fun extractSearchResultOpenIndex(
        command: String
    ): Int? {
        val normalized =
            normalizeRecognitionText(
                command
            )
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val patterns =
            listOf(
                Regex("^(?:открой|открыть|покажи|перейди к|перейди на) (?:результат|результат поиска) ?№? ?(\\d{1,2})$"),
                Regex("^(?:открой|открыть|покажи) (?:файл|фото|документ) (?:из )?результат(?:а|ов)? ?№? ?(\\d{1,2})$"),
                Regex("^(?:открой|открыть|покажи) ?№? ?(\\d{1,2}) (?:результат|результат поиска)$")
            )

        for (pattern in patterns) {
            val match = pattern.matchEntire(normalized) ?: continue
            val number =
                match.groupValues
                    .getOrNull(1)
                    ?.toIntOrNull()
                    ?: continue

            if (number in 1..20) {
                return number
            }
        }

        return null
    }

    private fun runOpenSearchResult(
        resultNumber: Int,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_search_result_open",
            executor = "search_result_action_executor"
        )

        val item =
            searchResultStore.get(
                resultNumber
            )

        if (item == null) {
            respondAndResume(
                text =
                    "Результат $resultNumber уже недоступен. Выполни поиск ещё раз и открой результат из новой выдачи.",
                silent = silent,
                success = false,
                technical =
                    "search_result_action_missing; result_number=$resultNumber; stale_or_non_openable=true"
            )
            return
        }

        val uri =
            try {
                Uri.parse(item.uri)
            } catch (_: Exception) {
                null
            }

        if (
            uri == null ||
            uri.scheme != "content"
        ) {
            respondAndResume(
                text = "Не удалось безопасно открыть результат $resultNumber.",
                silent = silent,
                success = false,
                technical =
                    "search_result_action_invalid_uri; result_number=$resultNumber"
            )
            return
        }

        val commandToken =
            activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaSearchResultOpen"
            ) {
                var readable = false
                try {
                    contentResolver
                        .openAssetFileDescriptor(
                            uri,
                            "r"
                        )
                        ?.use {
                            readable = true
                        }
                } catch (_: Exception) {
                    readable = false
                }

                if (
                    isCommandCancelled(commandToken) ||
                    commandToken != activeCommandToken
                ) {
                    return@thread
                }

                if (!readable) {
                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text =
                                    "Файл из результата $resultNumber больше не читается. Выполни поиск заново.",
                                silent = silent,
                                success = false,
                                technical =
                                    "search_result_action_preflight_failed; result_number=$resultNumber"
                            )
                        }
                    }
                    return@thread
                }

                val viewIntent =
                    Intent(
                        Intent.ACTION_VIEW
                    ).apply {
                        if (item.mimeType.isNotBlank()) {
                            setDataAndType(
                                uri,
                                item.mimeType
                            )
                        } else {
                            data = uri
                        }

                        clipData =
                            ClipData.newRawUri(
                                "AYANA search result",
                                uri
                            )

                        addFlags(
                            Intent.FLAG_ACTIVITY_NEW_TASK or
                                Intent.FLAG_GRANT_READ_URI_PERMISSION
                        )
                    }

                val dispatched =
                    try {
                        startActivity(viewIntent)
                        true
                    } catch (_: ActivityNotFoundException) {
                        false
                    } catch (_: SecurityException) {
                        false
                    } catch (_: Exception) {
                        false
                    }

                if (!dispatched) {
                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text =
                                    "Для результата $resultNumber не найдено приложение, которое может его открыть.",
                                silent = silent,
                                success = false,
                                technical =
                                    "search_result_action_dispatch_failed; result_number=$resultNumber; mime=${item.mimeType.take(100)}"
                            )
                        }
                    }
                    return@thread
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "search_result_open_dispatched",
                    message = "Результат поиска передан Android для открытия",
                    details =
                        "result_number=$resultNumber; source=${item.source}; kind=${item.kind}; mime=${item.mimeType.take(100)}; uri_scheme=content"
                )

                try {
                    Thread.sleep(700L)
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                }

                val screen =
                    try {
                        screenIntelligence.getScreenState()
                    } catch (_: Exception) {
                        JSONObject()
                    }

                val effectivePackage =
                    screen.optString(
                        "effective_foreground_package",
                        screen.optString(
                            "interaction_package",
                            screen.optString("package")
                        )
                    )
                        .trim()

                val handoffVerified =
                    screen.optBoolean("success", false) &&
                        effectivePackage.isNotBlank() &&
                        effectivePackage != packageName

                mainHandler.post {
                    if (
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken
                    ) {
                        return@post
                    }

                    if (handoffVerified) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "search_result_open_verified",
                            message = "Переход к найденному файлу подтверждён по внешнему foreground owner",
                            details =
                                "result_number=$resultNumber; foreground_package=${effectivePackage.take(140)}"
                        )

                        respondAndResume(
                            text =
                                "Открыт результат $resultNumber: ${item.title.ifBlank { "файл" }}.",
                            silent = silent,
                            success = true,
                            technical =
                                "search_result_open_verified; result_number=$resultNumber; foreground_package=${effectivePackage.take(140)}"
                        )
                    } else {
                        respondAndResume(
                            text =
                                "Запрос на открытие результата $resultNumber передан Android, но AYANA не смогла подтвердить переход к файлу.",
                            silent = silent,
                            success = false,
                            technical =
                                "search_result_open_unverified; result_number=$resultNumber; dispatched=true; foreground_package=${effectivePackage.take(140)}"
                        )
                    }
                }
            }

        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isImageIndexProgressCommand(
        value: String
    ): Boolean {
        val normalized =
            value
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        if (
            !normalized.contains("индекс") ||
            !(normalized.contains("фото") || normalized.contains("изображен"))
        ) {
            return false
        }

        return listOf(
            "прогресс",
            "статус",
            "сколько",
            "покажи",
            "проверь",
            "состояние"
        ).any(normalized::contains)
    }

    private fun runLocalImageIndexProgress(
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_image_index_status",
            executor = "background_image_indexer"
        )

        val commandToken =
            activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaImageIndexStatus"
            ) {
                try {
                    val snapshot =
                    try {
                        imageContentIndexEngine.statusSnapshot()
                    } catch (error: Exception) {
                        mainHandler.post {
                            if (
                                !isCommandCancelled(commandToken) &&
                                commandToken == activeCommandToken
                            ) {
                                respondAndResume(
                                    text = "Не удалось прочитать состояние локального индекса фото.",
                                    silent = silent,
                                    success = false,
                                    technical =
                                        "image_index_status_exception=${error.javaClass.simpleName}"
                                )
                            }
                        }
                        return@thread
                    }

                val runtime =
                    backgroundImageIndexer.runtimeStatus()

                val scheduleText =
                    when (runtime.state) {
                        AyanaBackgroundImageIndexer.STATE_INDEXING -> "индексирует сейчас"
                        AyanaBackgroundImageIndexer.STATE_WAITING -> "активна, ожидает следующий пакет"
                        AyanaBackgroundImageIndexer.STATE_PAUSED ->
                            if (!isBackgroundImageIndexBatteryAllowed()) {
                                "приостановлена из-за низкого заряда"
                            } else {
                                "приостановлена на время активной работы AYANA"
                            }
                        AyanaBackgroundImageIndexer.STATE_COMPLETE -> "индекс актуален; отслеживаются новые фото"
                        AyanaBackgroundImageIndexer.STATE_ERROR -> "временная ошибка; будет повтор"
                        AyanaBackgroundImageIndexer.STATE_STOPPING -> "останавливается"
                        else -> "остановлена"
                    }

                val resultText =
                    buildString {
                        append("Индекс содержимого фото: ")
                        append(snapshot.indexedImages)
                        append("/")
                        append(snapshot.candidateImages)
                        append(". Осталось: ")
                        append(snapshot.pendingImages)
                        append("; ошибок: ")
                        append(snapshot.failedImages)
                        append(". OCR: ")
                        append(snapshot.ocrIndexedImages)
                        append("; visual labels: ")
                        append(snapshot.labeledImages)
                        append(". Фоновая индексация: ")
                        append(scheduleText)
                        append(".")
                    }

                val technical =
                    buildString {
                        append("image_background_index_status")
                        append("; indexed=")
                        append(snapshot.indexedImages)
                        append("; candidates=")
                        append(snapshot.candidateImages)
                        append("; pending=")
                        append(snapshot.pendingImages)
                        append("; failed=")
                        append(snapshot.failedImages)
                        append("; ocr=")
                        append(snapshot.ocrIndexedImages)
                        append("; labeled=")
                        append(snapshot.labeledImages)
                        append("; scheduler_state=")
                        append(runtime.state)
                        append("; last_batch_updated=")
                        append(runtime.lastBatchUpdatedImages)
                        append("; last_batch_at_ms=")
                        append(runtime.lastBatchAtMs)
                        if (runtime.lastError.isNotBlank()) {
                            append("; last_error=")
                            append(runtime.lastError.take(160))
                        }
                    }

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "image_background_index_status",
                            message = "Состояние фонового визуального индекса прочитано локально",
                            details = technical
                        )

                        respondAndResume(
                            text = resultText,
                            silent = silent,
                            success = true,
                            technical = technical
                        )
                    }
                } finally {
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun runLocalPersonalSearchFollowUp(
        followUp: AyanaPersonalSearchEngine.FollowUpRequest,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_personal_search_followup",
            executor = "personal_search_engine"
        )

        when (followUp.kind) {
            AyanaPersonalSearchEngine.FollowUpKind.NEXT_PAGE,
            AyanaPersonalSearchEngine.FollowUpKind.PREVIOUS_PAGE -> {
                val delta =
                    if (
                        followUp.kind ==
                        AyanaPersonalSearchEngine.FollowUpKind.NEXT_PAGE
                    ) {
                        1
                    } else {
                        -1
                    }

                val page =
                    personalSearchEngine
                        .renderLatestPage(
                            delta
                        )

                if (page == null) {
                    respondAndResume(
                        text =
                            "Нет сохранённой выдачи личного поиска. Сначала выполни поиск, например «найди всё про AYANA».",
                        silent = silent,
                        success = false,
                        technical =
                            "personal_search_followup_no_session; kind=${followUp.kind.name.lowercase(Locale.ROOT)}"
                    )
                    return
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "personal_search_followup",
                    message =
                        if (page.boundary) {
                            "Граница сохранённой выдачи личного поиска достигнута"
                        } else {
                            "Показана другая страница сохранённой выдачи личного поиска"
                        },
                    details = page.technical
                )

                respondAndResume(
                    text = page.text,
                    silent = silent,
                    success = true,
                    technical = page.technical
                )
            }

            AyanaPersonalSearchEngine.FollowUpKind.FILTER_SOURCES -> {
                val request =
                    personalSearchEngine
                        .latestRequestForSources(
                            followUp.sources
                        )

                if (request == null) {
                    respondAndResume(
                        text =
                            "Нет предыдущего личного поиска, который можно отфильтровать. Сначала выполни новый поиск.",
                        silent = silent,
                        success = false,
                        technical =
                            "personal_search_followup_no_session; kind=filter_sources"
                    )
                    return
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "personal_search_followup",
                    message =
                        "Последний личный поиск повторяется только по выбранным источникам",
                    details =
                        "kind=filter_sources; query=${request.query.take(140)}; " +
                            "sources=${request.sources.joinToString(",") { it.wireName }}"
                )

                runLocalPersonalGlobalSearch(
                    request = request,
                    silent = silent
                )
            }
        }
    }


    private fun runLocalPersonalGlobalSearch(
        request: AyanaPersonalSearchEngine.Request,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_personal_global_search",
            executor = "personal_search_engine"
        )

        // R8.4 DEVICE CONTENT SEARCH + UNIFIED SEARCH SESSION PERFORMANCE/TRUTH.
        // MediaStore, first-run document extraction and bounded local image ML indexing
        // may touch many rows/files. Never execute these operations on the main looper.
        // Keep the local search bounded in its own execution thread and publish the final
        // state on mainHandler only if this command is still current.
        val commandToken =
            activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaPersonalGlobalSearch"
            ) {
                try {
                    val report =
                        try {
                            personalSearchEngine.search(
                                request = request
                            )
                        } catch (error: Exception) {
                            mainHandler.post {
                                if (
                                    !isCommandCancelled(commandToken) &&
                                    commandToken == activeCommandToken
                                ) {
                                    respondAndResume(
                                        "Личный поиск AYANA не удалось выполнить: ${error.message ?: "ошибка локального поиска"}.",
                                        silent,
                                        success = false,
                                        technical =
                                            "personal_search_exception=${error.javaClass.simpleName}"
                                    )
                                }
                            }
                            return@thread
                        }

                    if (isCommandCancelled(commandToken)) {
                        return@thread
                    }

                    val result =
                        personalSearchEngine
                            .renderRussian(
                                report
                            )

                    val technical =
                        personalSearchEngine
                            .technicalSummary(
                                report
                            )

                    val everyRequestedSourceUnavailable =
                        request.sources.isNotEmpty() &&
                            request.sources.all { source ->
                                source in report.sourceErrors.keys
                            }

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "personal_global_search",
                            message =
                                if (everyRequestedSourceUnavailable) {
                                    "Личный поиск не получил доступ ни к одному запрошенному источнику"
                                } else {
                                    "Личный поиск выполнен локально по доступным источникам AYANA"
                                },
                            details = technical
                        )

                        if (everyRequestedSourceUnavailable) {
                            // Requested-only inaccessible scope is not a successful search.
                            // Example: «найди в фото ...» while Android photo access is denied.
                            respondAndResume(
                                text = result,
                                silent = silent,
                                success = false,
                                terminalStatus =
                                    AyanaCommandHistoryStore.STATUS_BLOCKED,
                                technical =
                                    "$technical; requested_sources_unavailable=true"
                            )
                        } else {
                            // Text-mode commands must publish STATE_TEXT so MainActivity replaces
                            // the temporary “AYANA думает…” placeholder with the actual result.
                            respondAndResume(
                                text = result,
                                silent = silent,
                                success = true,
                                technical = technical
                            )
                        }
                    }
                } finally {
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun runStructuredLocalCommand(
        intent: AyanaStructuredLocalCommandRouter.Intent,
        silent: Boolean
    ): Boolean {
        return when (intent) {

            is AyanaStructuredLocalCommandRouter.Intent.NotificationRead -> {
                runLocalRecentNotificationsCommand(
                    silent = silent,
                    limit = intent.limit ?: 8,
                    appFilter = intent.appFilter,
                    projection = intent.projection.wireValue
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.RelativeMediaVolume -> {
                runLocalRelativeMediaVolumeCommand(
                    delta = intent.delta,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.DeviceMetric -> {
                runLocalDeviceMetricCommand(
                    metric = intent.metric,
                    silent = silent
                )
                true
            }

            AyanaStructuredLocalCommandRouter.Intent.DeviceDiagnostics -> {
                runLocalDetailedDeviceDiagnosticsCommand(
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.AppVersion -> {
                runLocalAppVersionCommand(
                    appName = intent.appName,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.History -> {
                runLocalCommandHistoryQuery(
                    limit = intent.limit,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.MemoryList -> {
                runLocalMemoryQuery(
                    query = intent.query,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.MemoryRecall -> {
                runLocalMemoryQuery(
                    query = intent.query,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.MemoryRemember -> {
                runLocalMemoryRemember(
                    text = intent.text,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.MemoryForget -> {
                runLocalMemoryForget(
                    query = intent.query,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.ReminderList -> {
                runLocalReminderList(
                    query = intent.query,
silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.ReminderCreate -> {
                runLocalReminderCreate(
                    request = intent,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.ReminderDelete -> {
                runLocalReminderDelete(
                    query = intent.query,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.ClipboardCopy -> {
                runLocalClipboardCopy(
                    text = intent.text,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.InternalPage -> {
                runLocalInternalPageNavigation(
                    page = intent.page,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.BrightnessSet -> {
                runLocalBrightnessSet(
                    percent = intent.percent,
                    silent = silent
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.SystemToggle -> {
                val label =
                    when (intent.kind) {
                        AyanaStructuredLocalCommandRouter.ToggleKind.WIFI -> "Wi‑Fi"
                        AyanaStructuredLocalCommandRouter.ToggleKind.BLUETOOTH -> "Bluetooth"
                    }

                respondUnsupportedAndResume(
                    text =
                        "AYANA не может надёжно ${if (intent.enable) "включить" else "выключить"} $label напрямую на этой версии Android. " +
                            "Я не буду подменять эту цель открытием настроек и отмечать её как выполненную.",
                    silent = silent,
                    technical = "system_toggle_not_available:${intent.kind.name.lowercase(Locale.ROOT)}"
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.UnknownCapability -> {
                respondUnsupportedAndResume(
                    text =
                        "Функция «${intent.label}» не зарегистрирована как доступная capability AYANA.",
                    silent = silent,
                    technical = "unknown_capability"
                )
                true
            }

            is AyanaStructuredLocalCommandRouter.Intent.CompositeVolumeAndState -> {
                runLocalCompositeVolumeAndState(
                    level = intent.level,
                    scale = intent.scale,
                    silent = silent
                )
                true
            }
        }
    }

    // =========================================================
    // PRE-EXECUTION GOAL INTEGRITY v12.11.2
    // =========================================================

    private enum class PreExecutionCommitState {
        COMMITTED,
        NOT_COMMITTED,
        UNKNOWN
    }

    private sealed class PreExecutionStep {
        abstract val label: String

        data class Brightness(
            val percent: Int
        ) : PreExecutionStep() {
            override val label: String = "яркость $percent%"
        }

        data class RelativeVolume(
            val delta: Int
        ) : PreExecutionStep() {
            override val label: String =
                if (delta >= 0) {
                    "громкость +$delta"
                } else {
                    "громкость $delta"
                }
        }

        data class ExactVolume(
            val requestedLevel: Int,
            val requestedScaleMax: Int?,
            val percent: Boolean
        ) : PreExecutionStep() {
            override val label: String =
                if (requestedScaleMax != null) {
                    if (percent) {
                        "громкость $requestedLevel%"
                    } else {
                        "громкость $requestedLevel из $requestedScaleMax"
                    }
                } else {
                    "громкость $requestedLevel"
                }
        }

        data class OpenApp(
            val requestedName: String,
            val packageName: String,
            val appLabel: String
        ) : PreExecutionStep() {
            override val label: String = "открыть $appLabel"
        }
    }

    private data class PreExecutionPlan(
        val steps: List<PreExecutionStep>,
        val constraints: AyanaCompositeIntentGate.Constraints
    )

    private data class PreExecutionPlanResult(
        val plan: PreExecutionPlan? = null,
        val terminalStatus: String? = null,
        val message: String = "",
        val technical: String = ""
    )

    private data class PreExecutionStepOutcome(
        val success: Boolean,
        val commitState: PreExecutionCommitState,
        val message: String,
        val technical: String = ""
    )

    private fun handlePendingPreExecutionConfirmationInput(
        originalCommand: String,
        silent: Boolean
    ): Boolean {
        val pending =
            pendingPreExecutionConfirmation
                ?: return false

        val expired =
            SystemClock.elapsedRealtime() >
                pending.expiresAtMs

        if (expired) {
            pendingPreExecutionConfirmation =
                null

            if (
                AyanaCompositeIntentGate.isPositiveConfirmation(
                    originalCommand
                ) ||
                AyanaCompositeIntentGate.isNegativeConfirmation(
                    originalCommand
                )
            ) {
                beginPreExecutionControlHistory(
                    originalCommand = originalCommand,
                    silent = silent
                )
                finishLocalCommand(
                    "Срок подтверждения истёк. Действие не выполнялось.",
                    silent
                )
                return true
            }

            return false
        }

        if (
            AyanaCompositeIntentGate.isPositiveConfirmation(
                originalCommand
            )
        ) {
            pendingPreExecutionConfirmation =
                null
            confirmedPreExecutionConstraints =
                pending.constraints
            confirmedPreExecutionOriginal =
                pending.originalCommand

            executeCommand(
                originalCommand = pending.executableCommand,
                silent = silent
            )
            return true
        }

        if (
            AyanaCompositeIntentGate.isNegativeConfirmation(
                originalCommand
            )
        ) {
            pendingPreExecutionConfirmation =
                null

            beginPreExecutionControlHistory(
                originalCommand = originalCommand,
                silent = silent
            )

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "confirmation_declined",
                message = "Ожидающее действие отменено до dispatch",
                details = pending.originalCommand.take(500)
            )

            finishLocalCommand(
                "Подтверждение отклонено. Действие не выполнялось.",
                silent
            )
            return true
        }

        // Any unrelated complete command supersedes the old confirmation.
        pendingPreExecutionConfirmation =
            null
        return false
    }

    private fun beginPreExecutionControlHistory(
        originalCommand: String,
        silent: Boolean
    ) {
        cancelRequested =
            false

        activeCommandToken =
            ++commandGeneration

        activeCommandHistoryId =
            commandHistoryStore.begin(
                command = originalCommand,
                source = if (silent) "text" else "voice"
            )

        beginExecutionSession(
            objective = originalCommand,
            source = if (silent) "text" else "voice",
            lane = "pre_execution_confirmation",
            executor = "composite_intent_gate"
        )
    }

    private fun handlePreExecutionDecision(
        decision: AyanaCompositeIntentGate.Decision,
        silent: Boolean
    ): Boolean {
        return when (decision.type) {
            AyanaCompositeIntentGate.DecisionType.PASS_THROUGH ->
                false

            AyanaCompositeIntentGate.DecisionType.DATA_ONLY -> {
                // DATA_ONLY is handled before Safety so quoted commands cannot
                // accidentally reach any executor.
                true
            }

            AyanaCompositeIntentGate.DecisionType.INVALID -> {
                respondAndResume(
                    "Команда не содержит исполнимой цели.",
                    silent,
                    success = false,
                    technical = "pre_execution_invalid"
                )
                true
            }

            AyanaCompositeIntentGate.DecisionType.REQUIRE_CONFIRMATION -> {
                val executable =
                    decision.executableCommand
                        ?.trim()
                        .orEmpty()

                if (executable.isBlank()) {
                    respondUnsupportedAndResume(
                        text = "Не удалось однозначно выделить действие, которое нужно подтвердить.",
                        silent = silent,
                        technical = "confirmation_payload_unresolved"
                    )
                    return true
                }

                val preflight =
                    preparePreExecutionGoal(
                        command = executable,
                        inheritedConstraints = decision.constraints
                    )

                if (preflight.plan == null) {
                    finishPreExecutionPreflightFailure(
                        preflight,
                        silent
                    )
                    return true
                }

                pendingPreExecutionConfirmation =
                    PendingPreExecutionConfirmation(
                        originalCommand = decision.original,
                        executableCommand = executable,
                        constraints = decision.constraints,
                        expiresAtMs =
                            SystemClock.elapsedRealtime() +
                                PRE_EXECUTION_CONFIRMATION_TTL_MS
                    )

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "confirmation_required",
                    message = "Действие отложено до явного Да/Нет",
                    details =
                        "payload=${executable.take(500)}; " +
                            "forbid_settings=${decision.constraints.forbidSettings}; " +
                            "forbid_network=${decision.constraints.forbidNetwork}"
                )

                respondBlockedAndResume(
                    text =
                        "Нужно подтверждение. Выполнить: «${executable.take(260)}»? Ответьте «Да» или «Нет».",
                    silent = silent,
                    technical = "confirmation_required_pending"
                )
                true
            }

            AyanaCompositeIntentGate.DecisionType.CONDITIONAL -> {
                val condition =
                    decision.condition

                val executable =
                    decision.executableCommand
                        ?.trim()
                        .orEmpty()

                if (condition == null || executable.isBlank()) {
                    respondUnsupportedAndResume(
                        text =
                            "Условие нельзя надёжно проверить локально, поэтому действие не выполнялось.",
                        silent = silent,
                        technical = "conditional_predicate_unsupported"
                    )
                    return true
                }

                val snapshot =
                    capturePreExecutionSnapshot()

                val evaluation =
                    AyanaCompositeIntentGate.evaluate(
                        condition,
                        snapshot
                    )

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "condition_evaluated",
                    message = evaluation.name,
                    details =
                        "metric=${condition.metric}; comparator=${condition.comparator}; " +
                            "value=${condition.value}; scale=${condition.scale ?: -1}; " +
                            "battery=${snapshot.batteryPercent ?: -1}; " +
                            "volume=${snapshot.mediaVolumeLevel ?: -1}/${snapshot.mediaVolumeScale ?: -1}; " +
                            "brightness=${snapshot.brightnessPercent ?: -1}"
                )

                when (evaluation) {
                    AyanaCompositeIntentGate.ConditionResult.FALSE -> {
                        finishLocalCommand(
                            "Условие не выполнено. Действие не требовалось и не выполнялось.",
                            silent
                        )
                    }

                    AyanaCompositeIntentGate.ConditionResult.UNKNOWN -> {
                        respondBlockedAndResume(
                            text =
                                "Не удалось получить фактическое значение для проверки условия. Действие не выполнялось.",
                            silent = silent,
                            technical = "conditional_metric_unavailable"
                        )
                    }

                    AyanaCompositeIntentGate.ConditionResult.TRUE -> {
                        val preflight =
                            preparePreExecutionGoal(
                                command = executable,
                                inheritedConstraints = decision.constraints
                            )

                        if (preflight.plan == null) {
                            finishPreExecutionPreflightFailure(
                                preflight,
                                silent
                            )
                        } else {
                            executePreExecutionPlan(
                                plan = preflight.plan,
                                silent = silent,
                                successPrefix = "Условие выполнено. "
                            )
                        }
                    }
                }
                true
            }

            AyanaCompositeIntentGate.DecisionType.COMPOSITE,
            AyanaCompositeIntentGate.DecisionType.ENVIRONMENT_CONSTRAINED -> {
                val command =
                    decision.executableCommand
                        ?.takeIf { it.isNotBlank() }
                        ?: decision.original

                val preflight =
                    preparePreExecutionGoal(
                        command = command,
                        inheritedConstraints = decision.constraints,
                        explicitClauses =
                            if (
                                decision.type ==
                                AyanaCompositeIntentGate.DecisionType.COMPOSITE
                            ) {
                                decision.clauses
                            } else {
                                emptyList()
                            }
                    )

                if (preflight.plan == null) {
                    finishPreExecutionPreflightFailure(
                        preflight,
                        silent
                    )
                } else {
                    executePreExecutionPlan(
                        plan = preflight.plan,
                        silent = silent,
                        successPrefix =
                            if (preflight.plan.steps.size > 1) {
                                "Составная команда выполнена полностью. "
                            } else {
                                ""
                            }
                    )
                }
                true
            }
        }
    }

    private fun preparePreExecutionGoal(
        command: String,
        inheritedConstraints: AyanaCompositeIntentGate.Constraints,
        explicitClauses: List<String> = emptyList()
    ): PreExecutionPlanResult {
        val nested =
            AyanaCompositeIntentGate.analyze(
                command
            )

        val combinedConstraints =
            AyanaCompositeIntentGate.Constraints(
                forbidSettings =
                    inheritedConstraints.forbidSettings ||
                        nested.constraints.forbidSettings,
                forbidNetwork =
                    inheritedConstraints.forbidNetwork ||
                        nested.constraints.forbidNetwork
            )

        val clauses =
            when {
                explicitClauses.isNotEmpty() ->
                    explicitClauses

                nested.type ==
                    AyanaCompositeIntentGate.DecisionType.COMPOSITE ->
                    nested.clauses

                nested.type ==
                    AyanaCompositeIntentGate.DecisionType.PASS_THROUGH ->
                    listOf(command)

                nested.type ==
                    AyanaCompositeIntentGate.DecisionType.ENVIRONMENT_CONSTRAINED ->
                    listOf(
                        nested.executableCommand
                            ?.takeIf { it.isNotBlank() }
                            ?: command
                    )

                else ->
                    return PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                        message =
                            "Вложенная условная/подтверждаемая цель не может быть выполнена как один локальный шаг.",
                        technical =
                            "nested_pre_execution_type=${nested.type.name}"
                    )
            }

        if (
            clauses.isEmpty() ||
            clauses.size > MAX_PRE_EXECUTION_STEPS
        ) {
            return PreExecutionPlanResult(
                terminalStatus =
                    AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                message =
                    "Составная команда содержит неподдерживаемое количество шагов.",
                technical = "pre_execution_steps=${clauses.size}"
            )
        }

        val steps =
            ArrayList<PreExecutionStep>()

        for (clause in clauses) {
            val safety =
                try {
                    safetyPolicy.evaluateUserCommand(
                        clause
                    )
                } catch (_: Exception) {
                    AyanaSafetyPolicy.Decision(
                        allowed = false,
                        requiresConfirmation = false,
                        riskLevel = AyanaSafetyPolicy.RISK_PROHIBITED,
                        riskName = "policy_error",
                        reason = "Локальный Safety Engine не смог проверить шаг составной команды."
                    )
                }

            if (!safety.allowed) {
                return PreExecutionPlanResult(
                    terminalStatus =
                        AyanaCommandHistoryStore.STATUS_BLOCKED,
                    message =
                        safety.reason.ifBlank {
                            "Шаг составной команды заблокирован Safety Engine."
                        },
                    technical =
                        "composite_step_safety:${safety.riskName}"
                )
            }

            val prepared =
                prepareAtomicPreExecutionStep(
                    clause = clause,
                    constraints = combinedConstraints
                )

            if (prepared.first == null) {
                return prepared.second
            }

            steps.add(
                prepared.first!!
            )
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "composite_preflight_passed",
            message = "Все обязательные шаги проверены до первого dispatch",
            details =
                "steps=${steps.joinToString(" | ") { it.label }.take(1000)}; " +
                    "forbid_settings=${combinedConstraints.forbidSettings}; " +
                    "forbid_network=${combinedConstraints.forbidNetwork}"
        )

        return PreExecutionPlanResult(
            plan =
                PreExecutionPlan(
                    steps = steps,
                    constraints = combinedConstraints
                )
        )
    }

    private fun prepareAtomicPreExecutionStep(
        clause: String,
        constraints: AyanaCompositeIntentGate.Constraints
    ): Pair<PreExecutionStep?, PreExecutionPlanResult> {
        val normalized =
            sanitizeRoutingEnvelope(
                repairCommonRecognitionForRouting(
                    normalizeRecognitionText(
                        clause
                    )
                )
            )

        extractExactMediaVolumeRequest(
            normalized
        )
            ?.let { request ->
                val scale =
                    request.requestedScaleMax

                if (
                    request.requestedLevel < 0 ||
                    (scale != null &&
                        (scale <= 0 || request.requestedLevel > scale))
                ) {
                    return null to
                        PreExecutionPlanResult(
                            message = "Некорректный точный уровень громкости в составной команде.",
                            technical = "composite_exact_volume_invalid"
                        )
                }

                return PreExecutionStep.ExactVolume(
                    requestedLevel = request.requestedLevel,
                    requestedScaleMax = request.requestedScaleMax,
                    percent = request.percent
                ) to PreExecutionPlanResult()
            }

        val structured =
            AyanaStructuredLocalCommandRouter
                .parseAtomic(
                    clause
                )

        when (structured) {
            is AyanaStructuredLocalCommandRouter.Intent.BrightnessSet -> {
                if (structured.percent !in 0..100) {
                    return null to
                        PreExecutionPlanResult(
                            message = "Некорректная яркость: ${structured.percent}%.",
                            technical = "composite_brightness_invalid"
                        )
                }

                if (
                    Build.VERSION.SDK_INT >=
                    Build.VERSION_CODES.M &&
                    !Settings.System.canWrite(
                        this
                    )
                ) {
                    return null to
                        PreExecutionPlanResult(
                            terminalStatus =
                                AyanaCommandHistoryStore.STATUS_BLOCKED,
                            message =
                                if (constraints.forbidSettings) {
                                    "Для яркости нет разрешения WRITE_SETTINGS, а команда запрещает открывать настройки. Ничего не изменено."
                                } else {
                                    "Для точной установки яркости требуется разрешение «Изменение системных настроек». Ничего не изменено."
                                },
                            technical = "composite_write_settings_required"
                        )
                }

                return PreExecutionStep.Brightness(
                    structured.percent
                ) to PreExecutionPlanResult()
            }

            is AyanaStructuredLocalCommandRouter.Intent.RelativeMediaVolume ->
                return PreExecutionStep.RelativeVolume(
                    structured.delta
                ) to PreExecutionPlanResult()

            is AyanaStructuredLocalCommandRouter.Intent.SystemToggle ->
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                        message =
                            "Шаг ${structured.kind.name} нельзя надёжно выполнить напрямую; составная команда не запускалась.",
                        technical = "composite_system_toggle_unsupported"
                    )

            is AyanaStructuredLocalCommandRouter.Intent.UnknownCapability ->
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                        message =
                            "Шаг «${structured.label}» не поддерживается транзакционным локальным исполнителем.",
                        technical = "composite_unknown_capability"
                    )

            null -> Unit

            else ->
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                        message =
                            "Шаг «${clause.take(180)}» нельзя безопасно объединить с другими изменениями устройства.",
                        technical =
                            "composite_structured_step_unsupported:${structured.javaClass.simpleName}"
                    )
        }

        val lifecycleNormalized =
            stripLifecycleForegroundVerificationSuffix(
                normalized
            )

        val lifecycle =
            extractLocalAppLifecycleRequest(
                lifecycleNormalized
            )

        if (lifecycle != null) {
            if (lifecycle.first != "open") {
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                        message =
                            "Закрытие/сворачивание приложения пока не объединяется с другими side-effect шагами.",
                        technical = "composite_lifecycle_destructive_unsupported"
                    )
            }

            if (constraints.forbidNetwork) {
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_BLOCKED,
                        message =
                            "Команда запрещает интернет. AYANA не может гарантировать, что запускаемое приложение не создаст сетевой трафик, поэтому приложение не открывалось.",
                        technical = "composite_network_constraint_app_open"
                    )
            }

            val target =
                lifecycle.second

            if (
                target == FOREGROUND_APP_SENTINEL
            ) {
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                        message = "Не удалось однозначно определить приложение для составной команды.",
                        technical = "composite_app_target_missing"
                    )
            }

            val resolution =
                try {
                    appResolver.resolve(
                        target
                    )
                } catch (_: Exception) {
                    null
                }

            if (
                resolution == null ||
                !resolution.success ||
                resolution.packageName.isBlank()
            ) {
                return null to
                    PreExecutionPlanResult(
                        message = "Приложение $target не найдено. Ни один шаг составной команды не запускался.",
                        technical = "composite_app_resolution_failed"
                    )
            }

            if (
                constraints.forbidSettings &&
                resolution.packageName ==
                    "com.android.settings"
            ) {
                return null to
                    PreExecutionPlanResult(
                        terminalStatus =
                            AyanaCommandHistoryStore.STATUS_BLOCKED,
                        message = "Команда запрещает открывать настройки. Ни один шаг не выполнялся.",
                        technical = "composite_settings_constraint"
                    )
            }

            return PreExecutionStep.OpenApp(
                requestedName = target,
                packageName = resolution.packageName,
                appLabel =
                    resolution.label.ifBlank {
                        target
                    }
            ) to PreExecutionPlanResult()
        }

        return null to
            PreExecutionPlanResult(
                terminalStatus =
                    AyanaCommandHistoryStore.STATUS_UNSUPPORTED,
                message =
                    "Шаг «${clause.take(180)}» пока не поддерживается локальным составным исполнителем. Ни один шаг не выполнялся.",
                technical = "composite_atomic_step_unresolved"
            )
    }

    /**
     * Removes only a terminal verification extension that is already guaranteed by
     * executeCompositeOpenAppStep(). Any other second action remains untouched and
     * therefore still fails closed during preflight.
     */
    private fun stripLifecycleForegroundVerificationSuffix(
        clause: String
    ): String {
        val c =
            normalizeLifecycleRoutingText(
                clause
            )

        val request =
            extractVerifiedAppOpenRequest(
                c
            )
                ?: return c

        val verifyTarget =
            request.second
                ?.trim()
                .orEmpty()

        // A suffix without a separate named target (for example "проверь, что
        // приложение на переднем плане") is verification of the launched app.
        if (verifyTarget.isBlank()) {
            return "открой ${request.first}"
        }

        val launchResolution =
            try {
                appResolver.resolve(request.first)
            } catch (_: Exception) {
                null
            }

        val verifyResolution =
            try {
                appResolver.resolve(verifyTarget)
            } catch (_: Exception) {
                null
            }

        val samePackage =
            launchResolution != null &&
                verifyResolution != null &&
                launchResolution.success &&
                verifyResolution.success &&
                launchResolution.packageName.isNotBlank() &&
                launchResolution.packageName ==
                    verifyResolution.packageName

        return if (samePackage) {
            "открой ${request.first}"
        } else {
            // Keep the clause untouched so preflight fails closed instead of
            // silently discarding a different terminal verification target.
            c
        }
    }

    private fun finishPreExecutionPreflightFailure(
        result: PreExecutionPlanResult,
        silent: Boolean
    ) {
        val text =
            result.message.ifBlank {
                "Составная команда не прошла предварительную проверку. Ничего не выполнялось."
            }

        when (result.terminalStatus) {
            AyanaCommandHistoryStore.STATUS_BLOCKED ->
                respondBlockedAndResume(
                    text = text,
                    silent = silent,
                    technical = result.technical
                )

            AyanaCommandHistoryStore.STATUS_UNSUPPORTED ->
                respondUnsupportedAndResume(
                    text = text,
                    silent = silent,
                    technical = result.technical
                )

            else ->
                respondAndResume(
                    text = text,
                    silent = silent,
                    success = false,
                    technical = result.technical
                )
        }
    }

    private fun capturePreExecutionSnapshot():
        AyanaCompositeIntentGate.Snapshot {
        val battery =
            try {
                val manager =
                    getSystemService(
                        Context.BATTERY_SERVICE
                    ) as BatteryManager

                manager.getIntProperty(
                    BatteryManager.BATTERY_PROPERTY_CAPACITY
                )
                    .takeIf { it in 0..100 }
            } catch (_: Exception) {
                null
            }

        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        val volume =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                null
            }

        val volumeMax =
            try {
                audioManager.getStreamMaxVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                null
            }

        val brightnessRaw =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS
                )
            } catch (_: Exception) {
                null
            }

        val brightnessPercent =
            brightnessRaw
                ?.takeIf { it >= 0 }
                ?.let {
                    kotlin.math.round(
                        it * 100.0 / 255.0
                    ).toInt()
                }
                ?.coerceIn(
                    0,
                    100
                )

        return AyanaCompositeIntentGate.Snapshot(
            batteryPercent = battery,
            mediaVolumeLevel = volume,
            mediaVolumeScale = volumeMax,
            brightnessPercent = brightnessPercent
        )
    }
private fun executePreExecutionPlan(
        plan: PreExecutionPlan,
        silent: Boolean,
        successPrefix: String
    ) {
        executionPhase(
            phase = "pre_execution_composite",
            executor = "composite_local_executor"
        )

        var boundaryOpened =
            false
        var dispatchAccepted =
            false
        var anyCommitted =
            false
        var anyUnknown =
            false

        fun beginDispatch(detail: String): Boolean {
            if (boundaryOpened) {
                return !executionKernel.isCancelled() &&
                    !cancelRequested &&
                    !shuttingDown
            }

            val opened =
                executionKernel.tryBeginIrreversibleDispatch(
                    kind =
                        if (plan.steps.size > 1) {
                            "composite_goal"
                        } else {
                            "pre_execution_goal"
                        },
                    detail = detail.take(600)
                )

            if (opened) {
                boundaryOpened =
                    true
            }

            return opened
        }

        fun acceptDispatch(detail: String) {
            if (!dispatchAccepted) {
                executionKernel.markIrreversibleDispatchAccepted(
                    detail.take(600)
                )
                dispatchAccepted =
                    true
            } else {
                executionKernel.addEvidence(
                    type = "composite_additional_dispatch",
                    source = "composite_local_executor",
                    detail = detail.take(1200),
                    confidence = 100
                )
            }
        }

        val messages =
            ArrayList<String>()

        plan.steps.forEachIndexed { index, step ->
            if (
                cancelRequested ||
                executionKernel.isCancelled() ||
                shuttingDown
            ) {
                if (!boundaryOpened) {
                    finishDeferredCancellationFromExecutor(
                        source = pendingCancelSource.ifBlank { "button" }
                    )
                    return
                }

                finalizeCompositeSideEffectTruth(
                    boundaryOpened = boundaryOpened,
                    dispatchAccepted = dispatchAccepted,
                    anyCommitted = anyCommitted,
                    anyUnknown = anyUnknown
                )

                if (anyCommitted || anyUnknown) {
                    cancelRequested =
                        false
                    respondAndResume(
                        text =
                            "Команда остановлена после начала выполнения. Часть изменений могла уже примениться; общий SUCCESS не выставлен.",
                        silent = silent,
                        success = false,
                        technical = "composite_cancel_after_dispatch"
                    )
                } else {
                    finishDeferredCancellationFromExecutor(
                        source = pendingCancelSource.ifBlank { "button" }
                    )
                }
                return
            }

            val outcome =
                executePreExecutionStep(
                    step = step,
                    beginDispatch = ::beginDispatch,
                    acceptDispatch = ::acceptDispatch
                )

            when (outcome.commitState) {
                PreExecutionCommitState.COMMITTED ->
                    anyCommitted = true

                PreExecutionCommitState.UNKNOWN ->
                    anyUnknown = true

                PreExecutionCommitState.NOT_COMMITTED ->
                    Unit
            }

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (outcome.success) {
                        "composite_step_verified"
                    } else {
                        "composite_step_failed"
                    },
                message =
                    "${index + 1}/${plan.steps.size}: ${step.label}",
                details =
                    "success=${outcome.success}; commit=${outcome.commitState}; " +
                        "message=${outcome.message.take(500)}; technical=${outcome.technical.take(700)}"
            )

            if (!outcome.success) {
                finalizeCompositeSideEffectTruth(
                    boundaryOpened = boundaryOpened,
                    dispatchAccepted = dispatchAccepted,
                    anyCommitted = anyCommitted,
                    anyUnknown = anyUnknown
                )

                respondAndResume(
                    text =
                        if (anyCommitted) {
                            "Составная команда выполнена только частично: ${outcome.message} Общий SUCCESS не выставлен."
                        } else if (anyUnknown) {
                            "Составная команда не завершена: ${outcome.message} Фактический результат одного из dispatch не подтверждён."
                        } else {
                            "Составная команда не выполнена: ${outcome.message}"
                        },
                    silent = silent,
                    success = false,
                    technical =
                        "composite_step_failed:index=$index; ${outcome.technical}"
                )
                return
            }

            messages.add(
                outcome.message
            )
        }

        finalizeCompositeSideEffectTruth(
            boundaryOpened = boundaryOpened,
            dispatchAccepted = dispatchAccepted,
            anyCommitted = anyCommitted,
            anyUnknown = anyUnknown
        )

        if (anyUnknown) {
            respondAndResume(
                text =
                    "Все шаги были отправлены, но один из результатов не удалось доказать. Общий SUCCESS не выставлен.",
                silent = silent,
                success = false,
                technical = "composite_unknown_terminal"
            )
            return
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "composite_goal_verified",
            message = "Все обязательные шаги составной цели подтверждены",
            details =
                "steps=${plan.steps.size}; committed=$anyCommitted; boundary=$boundaryOpened"
        )

        finishLocalCommand(
            successPrefix +
                messages.joinToString(" "),
            silent
        )
    }

    private fun finalizeCompositeSideEffectTruth(
        boundaryOpened: Boolean,
        dispatchAccepted: Boolean,
        anyCommitted: Boolean,
        anyUnknown: Boolean
    ) {
        if (!boundaryOpened) {
            return
        }

        executionKernel.markSideEffectReconciliationStarted(
            "composite_final_reconciliation"
        )

        when {
            anyCommitted ->
                executionKernel.markSideEffectReconciled(
                    committed = true,
                    detail = "composite_any_committed=true"
                )

            !anyUnknown ->
                executionKernel.markSideEffectReconciled(
                    committed = false,
                    detail =
                        "composite_no_commit; dispatch_accepted=$dispatchAccepted"
                )

            else -> {
                // Unknown post-dispatch outcome intentionally stays RECONCILING.
                // ExecutionKernel v1.3 will allow only fail-closed ERROR here.
            }
        }
    }

    private fun executePreExecutionStep(
        step: PreExecutionStep,
        beginDispatch: (String) -> Boolean,
        acceptDispatch: (String) -> Unit
    ): PreExecutionStepOutcome {
        return when (step) {
            is PreExecutionStep.Brightness ->
                executeCompositeBrightnessStep(
                    step,
                    beginDispatch,
                    acceptDispatch
                )

            is PreExecutionStep.RelativeVolume ->
                executeCompositeRelativeVolumeStep(
                    step,
                    beginDispatch,
                    acceptDispatch
                )

            is PreExecutionStep.ExactVolume ->
                executeCompositeExactVolumeStep(
                    step,
                    beginDispatch,
                    acceptDispatch
                )

            is PreExecutionStep.OpenApp ->
                executeCompositeOpenAppStep(
                    step,
                    beginDispatch,
                    acceptDispatch
                )
        }
    }

    private fun executeCompositeBrightnessStep(
        step: PreExecutionStep.Brightness,
        beginDispatch: (String) -> Boolean,
        acceptDispatch: (String) -> Unit
    ): PreExecutionStepOutcome {
        val target =
            ((step.percent / 100.0) * 255.0)
                .toInt()
                .coerceIn(0, 255)

        val before =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS
                )
            } catch (_: Exception) {
                -1
            }

        val beforeMode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        if (
            abs(before - target) <= 2 &&
            beforeMode ==
                Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
        ) {
            return PreExecutionStepOutcome(
                success = true,
                commitState =
                    PreExecutionCommitState.NOT_COMMITTED,
                message = "Яркость уже установлена на ${step.percent}%."
            )
        }

        if (
            !beginDispatch(
                "brightness=${step.percent}%"
            )
        ) {
            return PreExecutionStepOutcome(
                success = false,
                commitState =
                    PreExecutionCommitState.NOT_COMMITTED,
                message = "Изменение яркости отменено до dispatch.",
                technical = "brightness_dispatch_rejected"
            )
        }

        var dispatched =
            false

        val wroteMode =
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
                )
            } catch (_: Exception) {
                false
            }

        if (wroteMode) {
            dispatched = true
            acceptDispatch(
                "brightness_mode_manual"
            )
        }

        val wroteBrightness =
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    target
                )
            } catch (_: Exception) {
                false
            }

        if (wroteBrightness) {
            dispatched = true
            acceptDispatch(
                "brightness_raw=$target"
            )
        }

        val actual =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS
                )
            } catch (_: Exception) {
                -1
            }

        val mode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val verified =
            abs(actual - target) <= 2 &&
                mode ==
                    Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL

        val changed =
            (actual >= 0 && actual != before) ||
                (mode >= 0 && mode != beforeMode)

        return PreExecutionStepOutcome(
            success = verified,
            commitState =
                when {
                    verified || changed ->
                        PreExecutionCommitState.COMMITTED

                    !dispatched ->
                        PreExecutionCommitState.NOT_COMMITTED

                    else ->
                        PreExecutionCommitState.UNKNOWN
                },
            message =
                if (verified) {
                    "Яркость установлена на ${step.percent}%."
                } else {
                    "Яркость ${step.percent}% не подтверждена."
                },
            technical =
                "before=$before; target=$target; actual=$actual; " +
                    "mode_before=$beforeMode; mode=$mode; wrote_mode=$wroteMode; wrote_value=$wroteBrightness"
        )
    }

    private fun executeCompositeRelativeVolumeStep(
        step: PreExecutionStep.RelativeVolume,
        beginDispatch: (String) -> Boolean,
        acceptDispatch: (String) -> Unit
    ): PreExecutionStepOutcome {
        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        val before =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val max =
            try {
                audioManager.getStreamMaxVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val min =
            if (
                Build.VERSION.SDK_INT >=
                Build.VERSION_CODES.P
            ) {
                try {
                    audioManager.getStreamMinVolume(
                        AudioManager.STREAM_MUSIC
                    )
                } catch (_: Exception) {
                    0
                }
            } else {
                0
            }

        if (before < 0 || max < 0) {
            return PreExecutionStepOutcome(
                success = false,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Диапазон громкости недоступен.",
                technical = "volume_range_unavailable"
            )
        }

        val target =
            (before + step.delta)
                .coerceIn(min, max)

        if (target == before) {
            return PreExecutionStepOutcome(
                success = true,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Громкость уже на границе: $before из $max."
            )
        }

        if (
            !beginDispatch(
                "relative_volume:$before->$target"
            )
        ) {
            return PreExecutionStepOutcome(
                success = false,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Изменение громкости отменено до dispatch.",
                technical = "relative_volume_dispatch_rejected"
            )
        }

        val dispatched =
            try {
                audioManager.setStreamVolume(
                    AudioManager.STREAM_MUSIC,
                    target,
                    AudioManager.FLAG_SHOW_UI
                )
                acceptDispatch(
                    "relative_volume_target=$target"
                )
                true
            } catch (_: Exception) {
                false
            }

        val actual =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val verified =
            actual == target

        return PreExecutionStepOutcome(
            success = verified,
            commitState =
                when {
                    verified || (actual >= 0 && actual != before) ->
                        PreExecutionCommitState.COMMITTED

                    !dispatched ->
                        PreExecutionCommitState.NOT_COMMITTED

                    else ->
                        PreExecutionCommitState.UNKNOWN
                },
            message =
                if (verified) {
                    "Громкость изменена: $before → $actual из $max."
                } else {
                    "Требуемая громкость $target из $max не подтверждена."
                },
            technical =
                "before=$before; target=$target; actual=$actual; max=$max"
        )
    }

    private fun executeCompositeExactVolumeStep(
        step: PreExecutionStep.ExactVolume,
        beginDispatch: (String) -> Boolean,
        acceptDispatch: (String) -> Unit
    ): PreExecutionStepOutcome {
        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        val max =
            try {
                audioManager.getStreamMaxVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val min =
            if (
                Build.VERSION.SDK_INT >=
                Build.VERSION_CODES.P
            ) {
                try {
                    audioManager.getStreamMinVolume(
                        AudioManager.STREAM_MUSIC
                    )
                } catch (_: Exception) {
                    0
                }
            } else {
                0
            }

        val before =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        if (max <= min || before < 0) {
            return PreExecutionStepOutcome(
                success = false,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Точный диапазон громкости недоступен.",
                technical = "exact_volume_range_unavailable"
            )
        }

        val target =
            if (step.requestedScaleMax != null) {
                val scale = step.requestedScaleMax
                if (
                    scale <= 0 ||
                    step.requestedLevel !in 0..scale
                ) {
                    return PreExecutionStepOutcome(
                        success = false,
                        commitState = PreExecutionCommitState.NOT_COMMITTED,
                        message = "Некорректный точный уровень громкости.",
                        technical = "exact_volume_invalid"
                    )
                }

                (
                    (
                        step.requestedLevel.toLong() *
                            (max - min).toLong() +
                            scale / 2L
                        ) /
                        scale.toLong()
                    ).toInt() + min
            } else {
                if (
                    step.requestedLevel < min ||
                    step.requestedLevel > max
                ) {
                    return PreExecutionStepOutcome(
                        success = false,
                        commitState = PreExecutionCommitState.NOT_COMMITTED,
                        message = "Уровень ${step.requestedLevel} вне диапазона $min–$max.",
                        technical = "exact_volume_native_range_invalid"
                    )
                }
                step.requestedLevel
            }

        if (target == before) {
            return PreExecutionStepOutcome(
                success = true,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Громкость уже установлена: $before из $max."
            )
        }

        if (
            !beginDispatch(
                "exact_volume:$before->$target"
            )
        ) {
            return PreExecutionStepOutcome(
                success = false,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Установка громкости отменена до dispatch.",
                technical = "exact_volume_dispatch_rejected"
            )
        }

        val dispatched =
            try {
                audioManager.setStreamVolume(
                    AudioManager.STREAM_MUSIC,
                    target,
                    AudioManager.FLAG_SHOW_UI
                )
                acceptDispatch(
                    "exact_volume_target=$target"
                )
                true
            } catch (_: Exception) {
                false
            }

        val actual =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val verified =
            actual == target

        return PreExecutionStepOutcome(
            success = verified,
            commitState =
                when {
                    verified || (actual >= 0 && actual != before) ->
                        PreExecutionCommitState.COMMITTED

                    !dispatched ->
                        PreExecutionCommitState.NOT_COMMITTED

                    else ->
                        PreExecutionCommitState.UNKNOWN
                },
            message =
                if (verified) {
                    "Громкость установлена: $actual из $max."
                } else {
                    "Точная громкость $target из $max не подтверждена."
                },
            technical =
                "before=$before; target=$target; actual=$actual; max=$max"
        )
    }

    private fun executeCompositeOpenAppStep(
        step: PreExecutionStep.OpenApp,
        beginDispatch: (String) -> Boolean,
        acceptDispatch: (String) -> Unit
    ): PreExecutionStepOutcome {
        val before =
            currentForegroundPackage()

        if (before == step.packageName) {
            return PreExecutionStepOutcome(
                success = true,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "${step.appLabel} уже открыт."
            )
        }

        if (
            !beginDispatch(
                "open_app:${step.packageName}"
            )
        ) {
            return PreExecutionStepOutcome(
                success = false,
                commitState = PreExecutionCommitState.NOT_COMMITTED,
                message = "Открытие ${step.appLabel} отменено до dispatch.",
                technical = "open_app_dispatch_rejected"
            )
        }

        val launch =
            try {
                appResolver.launchExactPackage(
                    step.packageName
                )
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put(
                        "message",
                        error.message ?: "launch_exception"
                    )
            }

        val dispatched =
            launch.optBoolean(
                "success",
                false
            )

        if (dispatched) {
            acceptDispatch(
                "open_app:${step.packageName}"
            )
        }

        val after =
            if (dispatched) {
                waitForForegroundPackage(
                    step.packageName
                )
            } else {
                currentForegroundPackage()
            }

        val verified =
            dispatched &&
                after == step.packageName

        return PreExecutionStepOutcome(
            success = verified,
            commitState =
                when {
                    verified ->
                        PreExecutionCommitState.COMMITTED

                    !dispatched ->
                        PreExecutionCommitState.NOT_COMMITTED

                    else ->
                        PreExecutionCommitState.UNKNOWN
                },
            message =
                if (verified) {
                    "Открыто приложение ${step.appLabel}."
                } else {
                    "Открытие ${step.appLabel} не удалось подтвердить."
                },
            technical =
                "package=${step.packageName}; before=$before; after=$after; " +
                    "launch_success=$dispatched"
        )
    }

    private fun beginLocalVerifiedSideEffect(
        kind: String,
        detail: String
    ): Boolean =
        executionKernel
            .tryBeginIrreversibleDispatch(
                kind = kind,
                detail = detail
            )

    private fun markLocalSideEffectCommitted(
        detail: String
    ) {
        executionKernel
            .markIrreversibleDispatchAccepted(
                detail
            )

        executionKernel
            .markSideEffectReconciliationStarted(
                detail
            )

        executionKernel
            .markSideEffectReconciled(
                committed = true,
                detail = detail
            )
    }

    private fun markLocalSideEffectNotCommitted(
        detail: String
    ) {
        executionKernel
            .markIrreversibleDispatchAccepted(
                detail
            )

        executionKernel
            .markSideEffectReconciliationStarted(
                detail
            )

        executionKernel
            .markSideEffectReconciled(
                committed = false,
                detail = detail
            )
    }

    private fun runLocalRelativeMediaVolumeCommand(
        delta: Int,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_relative_volume",
            executor = "media_volume_executor"
        )

        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        val before =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val max =
            try {
                audioManager.getStreamMaxVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val min =
            if (
                Build.VERSION.SDK_INT >=
                Build.VERSION_CODES.P
            ) {
                try {
                    audioManager.getStreamMinVolume(
                        AudioManager.STREAM_MUSIC
                    )
                } catch (_: Exception) {
                    0
                }
            } else {
                0
            }

        if (before < 0 || max < 0) {
            respondAndResume(
                "Не удалось прочитать текущий диапазон громкости мультимедиа.",
                silent,
                success = false
            )
            return
        }

        val target =
            (before + delta)
                .coerceIn(
                    min,
                    max
                )

        if (target == before) {
            finishLocalCommand(
                "Громкость мультимедиа уже на границе диапазона: $before из $max.",
                silent
            )
            return
        }

        if (
            !beginLocalVerifiedSideEffect(
                kind = "media_volume_change",
                detail = "before=$before; delta=$delta; target=$target"
            )
        ) {
            respondAndResume(
                "Изменение громкости отменено до выполнения.",
                silent,
                success = false
            )
            return
        }

        try {
            audioManager.setStreamVolume(
                AudioManager.STREAM_MUSIC,
                target,
                AudioManager.FLAG_SHOW_UI
            )
        } catch (error: Exception) {
            markLocalSideEffectNotCommitted(
                "relative_volume_exception:${error.javaClass.simpleName}"
            )
            respondAndResume(
                "Не удалось изменить громкость мультимедиа.",
                silent,
                success = false,
                technical =
                    "relative_volume_exception:${error.javaClass.simpleName}"
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "media_volume_set:$target"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_media_volume:$target"
            )

        val actual =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val verified =
            actual == target

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail = "target=$target; actual=$actual"
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (verified) {
                    "volume_relative_verified"
                } else {
                    "volume_relative_failed"
                },
            message =
                if (verified) {
"Относительное изменение громкости подтверждено"
                } else {
                    "Относительное изменение громкости не подтверждено"
                },
            details =
                "before=$before; delta=$delta; target=$target; actual=$actual; max=$max"
        )

        if (verified) {
            finishLocalCommand(
                "Громкость мультимедиа изменена: $before → $actual из $max.",
                silent
            )
        } else {
            respondAndResume(
                "Не удалось подтвердить требуемое изменение громкости: ожидалось $target из $max, на устройстве $actual из $max.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalDeviceMetricCommand(
        metric: AyanaStructuredLocalCommandRouter.Metric,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_device_metric",
            executor = "device_metric_executor"
        )

        when (metric) {
            AyanaStructuredLocalCommandRouter.Metric.BATTERY -> {
                val state =
                    agentGetDeviceState()

                val battery =
                    state.optInt(
                        "battery_percent",
                        -1
                    )

                if (battery < 0) {
                    respondAndResume(
                        "Не удалось локально прочитать заряд батареи.",
                        silent,
                        success = false
                    )
                } else {
                    finishLocalCommand(
                        "Сейчас заряд батареи — $battery%. " +
                            if (
                                state.optBoolean(
                                    "charging",
                                    false
                                )
                            ) {
                                "Планшет заряжается."
                            } else {
                                "Планшет не заряжается."
                            },
                        silent
                    )
                }
            }

            AyanaStructuredLocalCommandRouter.Metric.MEDIA_VOLUME -> {
                val audioManager =
                    getSystemService(
                        Context.AUDIO_SERVICE
                    ) as AudioManager

                val current =
                    audioManager.getStreamVolume(
                        AudioManager.STREAM_MUSIC
                    )

                val max =
                    audioManager.getStreamMaxVolume(
                        AudioManager.STREAM_MUSIC
                    )

                val percent =
                    if (max > 0) {
                        ((current * 100.0) / max)
                            .toInt()
                    } else {
                        0
                    }

                finishLocalCommand(
                    "Громкость мультимедиа сейчас $current из $max — примерно $percent%.",
                    silent
                )
            }

            AyanaStructuredLocalCommandRouter.Metric.BRIGHTNESS -> {
                val raw =
                    try {
                        Settings.System.getInt(
                            contentResolver,
                            Settings.System.SCREEN_BRIGHTNESS
                        )
                    } catch (_: Exception) {
                        -1
                    }

                if (raw < 0) {
                    respondAndResume(
                        "Текущую яркость экрана локально прочитать не удалось.",
                        silent,
                        success = false
                    )
                } else {
                    val percent =
                        ((raw.coerceIn(0, 255) * 100.0) / 255.0)
                            .toInt()

                    val adaptive =
                        try {
                            Settings.System.getInt(
                                contentResolver,
                                Settings.System.SCREEN_BRIGHTNESS_MODE,
                                Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
                            ) ==
                                Settings.System.SCREEN_BRIGHTNESS_MODE_AUTOMATIC
                        } catch (_: Exception) {
                            false
                        }

                    finishLocalCommand(
                        "Яркость экрана сейчас примерно $percent%." +
                            if (adaptive) {
                                " Включена адаптивная яркость."
                            } else {
                                ""
                            },
                        silent
                    )
                }
            }

            AyanaStructuredLocalCommandRouter.Metric.STORAGE -> {
                val stat =
                    StatFs(
                        Environment
                            .getDataDirectory()
                            .absolutePath
                    )

                val free =
                    stat.availableBytes

                val total =
                    stat.totalBytes

                val used =
                    (total - free)
                        .coerceAtLeast(
                            0L
                        )

                finishLocalCommand(
                    "Хранилище планшета: свободно ${formatStorageGiB(free)} ГБ из ${formatStorageGiB(total)} ГБ; занято ${formatStorageGiB(used)} ГБ.",
                    silent
                )
            }

            AyanaStructuredLocalCommandRouter.Metric.DEVICE_MODEL -> {
                val manufacturer =
                    Build.MANUFACTURER
                        .trim()
                        .replaceFirstChar {
                            if (it.isLowerCase()) {
                                it.titlecase(
                                    Locale.ROOT
                                )
                            } else {
                                it.toString()
                            }
                        }

                finishLocalCommand(
                    "Модель планшета: $manufacturer ${Build.MODEL}. Устройство: ${Build.DEVICE}.",
                    silent
                )
            }

            AyanaStructuredLocalCommandRouter.Metric.DATE_TIME -> {
                val now =
                    LocalDateTime.now()

                val formatter =
                    DateTimeFormatter.ofPattern(
                        "EEEE, d MMMM yyyy 'года'. Сейчас HH:mm",
                        Locale(
                            "ru",
                            "RU"
                        )
                    )

                finishLocalCommand(
                    now
                        .format(
                            formatter
                        )
                        .replaceFirstChar {
                            if (it.isLowerCase()) {
                                it.titlecase(
                                    Locale(
                                        "ru",
                                        "RU"
                                    )
                                )
                            } else {
                                it.toString()
                            }
                        } +
                        " по часовому поясу ${ZoneId.systemDefault().id}.",
                    silent
                )
            }

            AyanaStructuredLocalCommandRouter.Metric.SCREEN_TITLE -> {
                val screen =
                    try {
                        screenIntelligence
                            .getScreenState()
                    } catch (_: Exception) {
                        JSONObject()
                    }

                val title =
                    screen
                        .optString(
                            "primary_window_title"
                        )
                        .trim()
                        .ifBlank {
                            val pkg =
                                screen.optString(
                                    "interaction_package",
                                    screen.optString(
                                        "package"
                                    )
                                )

                            if (
                                pkg ==
                                packageName
                            ) {
                                "AYANA AI"
                            } else {
                                pkg
                            }
                        }

                if (title.isBlank()) {
                    respondAndResume(
                        "Заголовок текущего экрана локально определить не удалось.",
                        silent,
                        success = false
                    )
                } else {
                    finishLocalCommand(
                        "Заголовок текущего экрана: «$title».",
                        silent
                    )
                }
            }
        }
    }

    private fun runLocalDetailedDeviceDiagnosticsCommand(
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_device_diagnostics",
            executor = "device_diagnostics_executor"
        )

        val state =
            try {
                agentGetDeviceState()
            } catch (_: Exception) {
                JSONObject()
            }

        val diagnostics =
            try {
                selfDiagnostics.run(
                    focus = "all"
                )
            } catch (_: Exception) {
                JSONObject()
            }

        val battery =
            state.optInt(
                "battery_percent",
                -1
            )

        val volume =
            state.optInt(
                "media_volume",
                -1
            )

        val volumeMax =
            state.optInt(
                "media_volume_max",
                -1
            )

        val stat =
            try {
                StatFs(
                    Environment
                        .getDataDirectory()
                        .absolutePath
                )
            } catch (_: Exception) {
                null
            }

        val activeTasks =
            try {
                taskStore.getFutureTasks().size
            } catch (_: Exception) {
                -1
            }

        val storedTasks =
            try {
                taskStore.count()
            } catch (_: Exception) {
                -1
            }

        val memoryCount =
            try {
                memoryStore.getAll(
                    350
                ).size
            } catch (_: Exception) {
                -1
            }

        val answer =
            buildString {
                append(
                    "Диагностика планшета выполнена локально."
                )

                if (battery >= 0) {
                    append(
                        " Заряд: $battery%"
                    )
                    if (
                        state.optBoolean(
                            "charging",
                            false
                        )
                    ) {
                        append(
                            ", идёт зарядка"
                        )
                    } else {
                        append(
                            ", зарядка не идёт"
                        )
                    }
                    append(
                        "."
                    )
                }

                if (
                    volume >= 0 &&
                    volumeMax > 0
                ) {
                    append(
                        " Громкость мультимедиа: $volume/$volumeMax."
                    )
                }

                append(
                    " Ориентация: "
                )
                append(
                    when (
                        state.optString(
                            "orientation"
                        )
                    ) {
                        "landscape" -> "альбомная"
                        "portrait" -> "портретная"
                        else -> "не определена"
                    }
                )
                append(
                    "."
                )

                if (stat != null) {
                    append(
                        " Хранилище: свободно ${formatStorageGiB(stat.availableBytes)} ГБ из ${formatStorageGiB(stat.totalBytes)} ГБ."
                    )
                }

                if (memoryCount >= 0) {
                    append(
                        " Долговременная память: $memoryCount записей."
                    )
                }

                if (
                    activeTasks >= 0 &&
                    storedTasks >= 0
                ) {
                    append(
                        " Напоминания: активных $activeTasks, всего сохранено $storedTasks."
                    )
                }

                append(
                    " Чтение уведомлений: "
                )
                append(
                    if (
                        AyanaNotificationListenerService
                            .isAccessGranted(
                                this@AyanaVoiceService
                            )
                    ) {
                        if (
                            AyanaNotificationListenerService
                                .isConnected()
                        ) {
                            "доступ разрешён, listener подключён."
                        } else {
                            "доступ разрешён, listener сейчас переподключается."
                        }
                    } else {
                        "доступ не разрешён."
                    }
                )

                if (
                    diagnostics.has(
                        "passed"
                    )
                ) {
                    append(
                        " Самодиагностика: исправно=${diagnostics.optInt("passed", 0)}, внимание=${diagnostics.optInt("warnings", 0)}, нет данных=${diagnostics.optInt("unknown", 0)}, ошибки=${diagnostics.optInt("failed", 0)}."
                    )
                }
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_device_diagnostics",
            message = "Диагностика планшета выполнена локально",
            details =
                "battery=$battery; volume=$volume/$volumeMax; memory=$memoryCount; active_reminders=$activeTasks; stored_reminders=$storedTasks"
        )

        finishLocalCommand(
            answer,
            silent
        )
    }

    private fun formatStorageGiB(
        bytes: Long
    ): String =
        String.format(
            Locale.US,
            "%.1f",
            bytes.toDouble() /
                (1024.0 * 1024.0 * 1024.0)
        )
            .replace(
                '.',
                ','
            )

    private fun runLocalAppVersionCommand(
        appName: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_app_metadata",
            executor = "package_metadata_executor"
        )

        val resolution =
            try {
                appResolver.resolve(
                    appName
                )
            } catch (_: Exception) {
                null
            }

        if (
            resolution == null ||
            !resolution.success ||
            resolution.packageName.isBlank()
        ) {
            respondAndResume(
                "Не удалось определить установленное приложение «$appName».",
                silent,
                success = false
            )
            return
        }

        val info =
            try {
                packageManager.getPackageInfo(
                    resolution.packageName,
                    0
                )
            } catch (_: Exception) {
                null
            }

        if (info == null) {
            respondAndResume(
                "Не удалось прочитать версию приложения ${resolution.label.ifBlank { appName }}.",
                silent,
                success = false
            )
            return
        }

        val versionName =
            info.versionName
                .orEmpty()
                .ifBlank {
                    "не указана"
                }

        val versionCode =
            if (
                Build.VERSION.SDK_INT >=
                Build.VERSION_CODES.P
            ) {
                info.longVersionCode
            } else {
                @Suppress("DEPRECATION")
                info.versionCode
                    .toLong()
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_app_metadata",
            message = "Версия установленного приложения прочитана локально",
            details =
                "package=${resolution.packageName}; version=$versionName; code=$versionCode"
        )

        finishLocalCommand(
            "Установленная версия ${resolution.label.ifBlank { appName }}: $versionName (код $versionCode).",
            silent
        )
    }

    private fun runLocalCommandHistoryQuery(
        limit: Int,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_command_history",
            executor = "command_history_executor"
        )

        val records =
            commandHistoryStore
                .recent(
                    limit + 8
                )
                .filter { record ->
                    record.optString(
                        "id"
                    ) !=
                        activeCommandHistoryId &&
                        record.optString(
                            "status"
                        ) !=
                        AyanaCommandHistoryStore.STATUS_RUNNING
                }
                .take(
                    limit
                )

        if (records.isEmpty()) {
            finishLocalCommand(
                "Предыдущих завершённых команд в истории сейчас нет.",
                silent
            )
            return
        }

        val lines =
            records.mapIndexed { index, record ->
                val command =
                    record.optString(
                        "command"
                    )
                        .replace(
                            Regex("\\s+"),
                            " "
                        )
                        .trim()
                        .take(
                            180
                        )

                val status =
                    record.optString(
                        "status"
                    )
                        .ifBlank {
                            "UNKNOWN"
                        }

                val duration =
                    record
                        .optLong(
                            "duration_ms",
                            -1L
                        )

                buildString {
                    append(index + 1)
                    append("). ")
                    append(command)
                    append(" — ")
                    append(status)
                    if (duration >= 0L) {
                        append(" • ")
                        append(duration)
                        append(" мс")
                    }
                }
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_history_read",
            message = "История команд прочитана локально",
            details = "requested=$limit; returned=${records.size}"
        )

        finishLocalCommand(
            lines.joinToString(
                "\n"
            ),
            silent
        )
    }

    private fun runLocalMemoryQuery(
        query: String?,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_memory_read",
            executor = "memory_store_executor"
        )

        val items =
            if (
                query.isNullOrBlank()
            ) {
                memoryStore.getAll(
                    50
                )
            } else {
                memoryStore.search(
                    query = query,
                    limit = 12
                )
            }

        if (items.isEmpty()) {
            finishLocalCommand(
                if (
                    query.isNullOrBlank()
                ) {
                    "Долговременная память AYANA сейчас пуста."
                } else {
                    "По запросу «$query» точного или достаточно релевантного совпадения в памяти нет."
                },
                silent
            )
            return
        }

        val lines =
            items.mapIndexed { index, item ->
                "${index + 1}). ${item.text}"
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_memory_read",
            message = "Долговременная память прочитана локально",
            details =
                "query=${query.orEmpty().take(120)}; count=${items.size}; total=${memoryStore.getAll(350).size}"
        )

        finishLocalCommand(
            if (
                query.isNullOrBlank()
            ) {
                "В памяти сохранено ${items.size} записей:\n" +
                    lines.joinToString(
                        "\n"
                    )
            } else {
                "Найдено в памяти:\n" +
                    lines.joinToString(
                        "\n"
                    )
            },
            silent
        )
    }

    private fun runLocalMemoryRemember(
        text: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_memory_write",
            executor = "memory_store_executor"
        )

        if (
            !beginLocalVerifiedSideEffect(
                kind = "memory_write",
                detail = text.take(180)
            )
        ) {
            respondAndResume(
                "Запись в память отменена до выполнения.",
                silent,
                success = false
            )
            return
        }

        val item =
            try {
                memoryStore.remember(
                    text = text,
                    category = "general",
                    source = "user",
                    provenance = "explicit",
                    confidence = 1.0
                )
            } catch (_: Exception) {
                null
            }

        if (item == null) {
            markLocalSideEffectNotCommitted(
                "memory_write_failed"
            )
            respondAndResume(
                "Не удалось сохранить запись в долговременную память.",
                silent,
                success = false
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "memory_id=${item.id}"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_memory_id=${item.id}"
            )

        val verified =
            memoryStore
                .getAll(
                    350
                )
                .any {
                    it.id == item.id &&
                        it.text == item.text
                }

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail = "memory_id=${item.id}; verified=$verified"
            )

        if (verified) {
            finishLocalCommand(
                "Сохранено в долговременную память: ${item.text}",
                silent
            )
        } else {
            respondAndResume(
                "Запись была отправлена в хранилище, но её сохранение не удалось подтвердить.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalMemoryForget(
        query: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_memory_delete",
            executor = "memory_store_executor"
        )

        val candidates =
            memoryStore.search(
                query = query,
                limit = 20
            )

        if (candidates.isEmpty()) {
            finishLocalCommand(
                "По запросу «$query» подходящих записей для удаления не найдено.",
                silent
            )
            return
        }

        if (
            !beginLocalVerifiedSideEffect(
                kind = "memory_delete",
                detail = query.take(180)
            )
        ) {
            respondAndResume(
                "Удаление памяти отменено до выполнения.",
                silent,
                success = false
            )
            return
        }

        val before =
            memoryStore
                .getAll(
                    350
                )
                .size

        val removed =
            try {
                memoryStore.forget(
                    query
                )
            } catch (_: Exception) {
                0
            }

        if (removed <= 0) {
            markLocalSideEffectNotCommitted(
                "memory_delete_removed=0"
            )
            respondAndResume(
                "Подходящие записи были найдены, но удалить их не удалось.",
                silent,
                success = false
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "memory_removed=$removed"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_memory_delete"
            )

        val after =
            memoryStore
                .getAll(
                    350
                )
                .size

        val verified =
            after ==
                before -
                    removed

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail = "before=$before; removed=$removed; after=$after"
            )

        if (verified) {
            finishLocalCommand(
                "Удалено записей из памяти: $removed.",
                silent
            )
        } else {
            respondAndResume(
                "Удаление выполнено, но итоговое состояние памяти не удалось подтвердить.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalReminderList(
        query: String?,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_reminder_read",
            executor = "task_store_executor"
        )

        val now =
            System.currentTimeMillis()

        val tasks =
            if (
                query.isNullOrBlank()
            ) {
                taskStore.getFutureTasks(
                    now
                )
            } else {
                taskStore
                    .findByQuery(
                        query = query,
                        limit = 12
                    )
                    .filter {
                        it.enabled &&
                            it.triggerAtMillis >=
                            now
                    }
            }

        if (tasks.isEmpty()) {
            finishLocalCommand(
                if (
                    query.isNullOrBlank()
                ) {
                    "Активных будущих задач и напоминаний нет."
                } else {
                    "Задача или напоминание «$query» среди активных не найдены."
                },
                silent
            )
            return
        }

        val zone =
            ZoneId.systemDefault()

        val formatter =
            DateTimeFormatter.ofPattern(
                "d MMMM yyyy, HH:mm",
                Locale(
                    "ru",
                    "RU"
                )
            )

        val lines =
            tasks.mapIndexed { index, task ->
                val time =
                    Instant
                        .ofEpochMilli(
                            task.triggerAtMillis
                        )
                        .atZone(
                            zone
                        )
                        .format(
                            formatter
                        )

                buildString {
append(index + 1)
                    append("). «")
                    append(task.title)
                    append("» — ")
                    append(time)
                    if (
                        task.message.isNotBlank() &&
                        task.message !=
                        task.title
                    ) {
                        append(". ")
                        append(task.message)
                    }
                }
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_reminder_read",
            message = "Задачи и напоминания прочитаны локально",
            details =
                "query=${query.orEmpty().take(120)}; returned=${tasks.size}; active=${taskStore.getFutureTasks(now).size}; stored=${taskStore.count()}"
        )

        finishLocalCommand(
            if (
                query.isNullOrBlank()
            ) {
                "Активных задач: ${tasks.size}\n" +
                    lines.joinToString(
                        "\n"
                    )
            } else {
                lines.joinToString(
                    "\n"
                )
            },
            silent
        )
    }

    private fun runLocalReminderCreate(
        request: AyanaStructuredLocalCommandRouter.Intent.ReminderCreate,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_reminder_create",
            executor = "task_store_executor"
        )

        val zone =
            ZoneId.systemDefault()

        val now =
            LocalDateTime.now(
                zone
            )

        val trigger =
            when {
                request.relativeMinutes != null ->
                    now.plusMinutes(
                        request.relativeMinutes.toLong()
                    )

                request.tomorrowHour != null &&
                    request.tomorrowMinute != null ->
                    now
                        .toLocalDate()
                        .plusDays(
                            1
                        )
                        .atTime(
                            request.tomorrowHour,
                            request.tomorrowMinute
                        )

                else ->
                    null
            }

        if (trigger == null) {
            respondAndResume(
                "Не удалось определить время напоминания.",
                silent,
                success = false
            )
            return
        }

        val formatter =
            DateTimeFormatter.ofPattern(
                "yyyy-MM-dd'T'HH:mm:ss"
            )

        if (
            !beginLocalVerifiedSideEffect(
                kind = "reminder_create",
                detail =
                    "${request.title.take(120)} @ ${trigger.format(formatter)}"
            )
        ) {
            respondAndResume(
                "Создание напоминания отменено до выполнения.",
                silent,
                success = false
            )
            return
        }

        val result =
            agentCreateReminder(
                title = request.title,
                message = request.title,
                triggerAtLocal = trigger.format(
                    formatter
                ),
                recurrence = AyanaTaskStore.RECURRENCE_NONE
            )

        if (
            !result.optBoolean(
                "success",
                false
            )
        ) {
            markLocalSideEffectNotCommitted(
                "reminder_create_failed"
            )
            respondAndResume(
                result.optString(
                    "message"
                )
                    .ifBlank {
                        result.optString(
                            "message_to_user",
                            "Не удалось создать напоминание."
                        )
                    },
                silent,
                success = false
            )
            return
        }

        val taskId =
            result.optString(
                "task_id"
            )

        executionKernel
            .markIrreversibleDispatchAccepted(
                "reminder_id=$taskId"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_reminder_id=$taskId"
            )

        val verified =
            taskId.isNotBlank() &&
                taskStore
                    .getTask(
                        taskId
                    ) !=
                null

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail =
                    "reminder_id=$taskId; verified=$verified"
            )

        if (verified) {
            finishLocalCommand(
                "Напоминание «${request.title}» создано на ${trigger.format(DateTimeFormatter.ofPattern("d MMMM, HH:mm", Locale("ru", "RU")))}.",
                silent
            )
        } else {
            respondAndResume(
                "Напоминание было передано планировщику, но его сохранение не удалось подтвердить.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalReminderDelete(
        query: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_reminder_delete",
            executor = "task_store_executor"
        )

        val candidates =
            taskStore.findByQuery(
                query = query,
                limit = 20
            )

        if (candidates.isEmpty()) {
            finishLocalCommand(
                "Напоминание «$query» не найдено.",
                silent
            )
            return
        }

        if (
            !beginLocalVerifiedSideEffect(
                kind = "reminder_delete",
                detail = query.take(180)
            )
        ) {
            respondAndResume(
                "Удаление напоминания отменено до выполнения.",
                silent,
                success = false
            )
            return
        }

        val result =
            agentDeleteReminder(
                query
            )

        val removed =
            result.optInt(
                "removed",
                0
            )

        if (
            !result.optBoolean(
                "success",
                false
            ) ||
            removed <= 0
        ) {
            markLocalSideEffectNotCommitted(
                "reminder_delete_failed; removed=$removed"
            )
            respondAndResume(
                result.optString(
                    "message"
                )
                    .ifBlank {
                        "Напоминание удалить не удалось."
                    },
                silent,
                success = false
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "reminders_removed=$removed"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_reminder_delete"
            )

        val remaining =
            taskStore.findByQuery(
                query = query,
                limit = 20
            )

        val verified =
            remaining.isEmpty()

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail =
                    "removed=$removed; remaining_matches=${remaining.size}"
            )

        if (verified) {
            finishLocalCommand(
                "Напоминание «$query» удалено.",
                silent
            )
        } else {
            respondAndResume(
                "Удаление выполнено, но совпадающая запись всё ещё присутствует в хранилище.",
                silent,
                success = false
            )
        }
    }

    /**
     * v12.19.4: narrow, local-first clipboard grammar.
     *
     * Only phrases that explicitly name the Android clipboard are accepted here.
     * This intentionally does NOT own generic "скопируй ..." requests, so file/UI
     * copy semantics continue to the existing routers. The captured payload keeps
     * the user's original case and punctuation; only surrounding whitespace is trimmed.
     */
    private fun extractLocalClipboardCopyRequest(
        command: String
    ): String? {

        val source =
            command
                .trim()

        if (source.isBlank()) {
            return null
        }

        val patterns =
            listOf(
                Regex(
                    pattern =
                        """^(?:скопируй|копируй|запиши|помести|сохрани|положи)\s+в\s+буфер(?:\s+обмена)?\s+(?:текст\s+)?(.+)$""",
                    option = RegexOption.IGNORE_CASE
                ),
                Regex(
                    pattern =
                        """^(?:скопируй|копируй|запиши|помести|сохрани|положи)\s+(?:текст\s+)?(.+?)\s+в\s+буфер(?:\s+обмена)?$""",
                    option = RegexOption.IGNORE_CASE
                )
            )

        val payload =
            patterns
                .asSequence()
                .mapNotNull { pattern ->
                    pattern
                        .matchEntire(source)
                        ?.groupValues
                        ?.getOrNull(1)
                        ?.trim()
                }
                .firstOrNull { it.isNotBlank() }
                ?: return null

        return payload
    }

    /**
     * v12.20.0 terminal truth guard.
     *
     * A final model/Worker reply is never promoted to SUCCESS when the original
     * request is an explicit action and the reply itself unambiguously says that
     * the action failed, is unavailable or was not performed. This guard only
     * downgrades success; it never fabricates successful evidence or a side effect.
     */
    private fun shouldFailClosedAgentFinalWithoutMachineTerminal(
        originalCommand: String,
        reply: String
    ): Boolean {

        val command =
            normalizeRecognitionText(
                originalCommand
            )

        val answer =
            normalizeRecognitionText(
                reply
            )

        if (
            command.isBlank() ||
            answer.isBlank()
        ) {
            return false
        }

        val explicitAction =
            AGENT_FAIL_CLOSED_ACTION_PREFIXES.any { prefix ->
                command.startsWith(prefix)
            }

        if (!explicitAction) {
            return false
        }

        return AGENT_FAIL_CLOSED_FAILURE_MARKERS.any { marker ->
            answer.contains(marker)
        }
    }

    /**
     * R7.9 artifact follow-up contract.
     * A request such as "создай файл TXT с готовым кодом" immediately after a
     * multimodal/code answer must carry the actual previous payload into create_artifact,
     * never a prose summary of that payload. The previous_response_id remains the source
     * of truth; this adds an execution-only reminder to the Agent Core turn.
     */
    private fun strengthenArtifactFollowUpMessage(
        message: String?,
        hasPreviousResponseContext: Boolean
    ): String? {
        val clean = message?.trim().orEmpty()
        if (
            clean.isBlank() ||
            !hasPreviousResponseContext ||
            !isArtifactFollowUpPayloadRequest(clean)
        ) {
            return message
        }

        return (
            clean +
                "\n\n[AYANA ARTIFACT FOLLOW-UP CONTRACT] " +
                "This request refers to payload from the immediately previous response context. " +
                "If you call create_artifact, arguments.content/rows MUST contain the actual requested payload " +
                "(for example the complete code), not a description, summary, instructions for saving it, or a placeholder. " +
                "If the exact payload is unavailable in previous_response_id context, do not call create_artifact and do not claim success."
            ).take(5000)
    }

    private fun isArtifactFollowUpPayloadRequest(
        message: String
    ): Boolean {
        val normalized =
            message
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val asksArtifact =
            listOf(
                "создай файл",
                "создать файл",
                "сохрани в файл",
                "сохранить в файл",
                "сделай файл",
                "запиши в файл"
            ).any { it in normalized }

        if (!asksArtifact) {
            return false
        }

        return listOf(
            "готовым кодом",
            "готовый код",
            "этим кодом",
            "кодом выше",
            "предыдущим кодом",
            "из предыдущего ответа",
            "с этим текстом",
            "этот текст",
            "весь код",
            "полный код"
        ).any { it in normalized }
    }

    /**
     * R7.9 semantic artifact gate. Byte/hash verification proves that a file exists,
     * not that it contains the deliverable the user asked for. This gate runs before
     * ArtifactEngine and therefore prevents publishing a verified-but-useless file.
     */
    private fun validateCreateArtifactContentContract(
        request: String,
        arguments: JSONObject
    ): JSONObject {
        val normalized =
            request
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val kind =
            arguments
                .optString("kind")
                .lowercase(Locale.ROOT)
                .trim()

        val content =
            arguments
                .optString("content")
                .trim()

        val titleAndName =
            (
                arguments.optString("title") +
                    " " +
                    arguments.optString("filename")
                )
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')

        val asksForCode =
            listOf(
                "готовый код",
                "готовым кодом",
                "полный код",
                "исходный код",
                "исходник",
                "напиши код",
                "код для",
                "kotlin",
                "java",
                "python",
                "javascript",
                "typescript"
            ).any { it in normalized } ||
                listOf("code", "код", "kotlin", "java", "python")
                    .any { it in titleAndName }

        val asksForSubstantialReport =
            listOf(
                "подробный отчет",
                "подробный отчёт",
                "полный отчет",
                "полный отчёт",
                "подробный анализ",
                "справка-обоснование",
                "справку-обоснование"
            ).any { it in normalized }

        val rows =
            arguments.optJSONArray("rows")

        val columns =
            arguments.optJSONArray("columns")

        val codeMarkerCount =
            listOf(
                "package ",
                "import ",
                "class ",
                "object ",
                "interface ",
                "fun ",
                "private ",
                "public ",
                "override ",
                "val ",
                "var ",
                "def ",
                "function ",
                "const ",
                "#include",
                "using namespace",
                "<!doctype",
                "<html",
                "<script",
                "<?xml"
            ).count { marker ->
                marker in content.lowercase(Locale.ROOT)
            }

        val codeLineCount =
            content
                .lineSequence()
                .count { it.trim().isNotBlank() }

        val structuredCodeShape =
            content.contains("{") &&
                content.contains("}") &&
                content.contains("(") &&
                content.contains(")")

        val obviousCodeDescriptionOnly =
            listOf(
                "сохраните содержимое как",
                "визуализация включает",
                "код не требует внешних библиотек",
                "переключение выполняется",
                "самостоятельный код визуализации"
            ).count { marker ->
                marker in content.lowercase(Locale.ROOT)
            } >= 2

        val codePayloadPresent =
            content.length >= 80 &&
                codeLineCount >= 4 &&
                !obviousCodeDescriptionOnly &&
                (
                    codeMarkerCount >= 2 ||
                        structuredCodeShape
                    )

        val tablePayloadPresent =
            kind != "xlsx" ||
                (
                    (columns?.length() ?: 0) > 0 &&
                        (rows?.length() ?: 0) > 0
                    )

        val reportPayloadPresent =
            !asksForSubstantialReport ||
                (
                    content.length >= 220 &&
                        content.lineSequence().count { it.trim().isNotBlank() } >= 5
                    )

        val allowed =
            (!asksForCode || codePayloadPresent) &&
                tablePayloadPresent &&
                reportPayloadPresent

        val reason =
            when {
                asksForCode && !codePayloadPresent ->
                    "requested_code_payload_missing"

                !tablePayloadPresent ->
                    "requested_table_payload_missing"

                !reportPayloadPresent ->
                    "requested_report_payload_incomplete"

                else ->
                    "semantic_payload_verified"
            }

        return JSONObject()
            .put("allowed", allowed)
            .put("reason", reason)
            .put("kind", kind)
            .put("content_chars", content.length)
            .put("content_lines", codeLineCount)
            .put("asks_for_code", asksForCode)
            .put("code_marker_count", codeMarkerCount)
            .put("code_payload_present", codePayloadPresent)
            .put("table_payload_present", tablePayloadPresent)
            .put("report_payload_present", reportPayloadPresent)
    }

    private fun runLocalClipboardCopy(
        text: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_clipboard_write",
            executor = "clipboard_executor"
        )

        val clipboard =
            getSystemService(
                Context.CLIPBOARD_SERVICE
            ) as ClipboardManager

        if (
            !beginLocalVerifiedSideEffect(
                kind = "clipboard_write",
                detail = "chars=${text.length}"
            )
        ) {
            respondAndResume(
                "Копирование отменено до выполнения.",
                silent,
                success = false
            )
            return
        }

        try {
            clipboard.setPrimaryClip(
                ClipData.newPlainText(
                    "AYANA",
                    text
                )
            )
        } catch (error: Exception) {
            markLocalSideEffectNotCommitted(
                "clipboard_exception:${error.javaClass.simpleName}"
            )
            respondAndResume(
                "Не удалось записать текст в буфер обмена.",
                silent,
                success = false,
                technical =
                    "clipboard_exception:${error.javaClass.simpleName}"
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "clipboard_write"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_clipboard"
            )

        val verified =
            try {
                clipboard.primaryClip
                    ?.getItemAt(
                        0
                    )
                    ?.coerceToText(
                        this
                    )
                    ?.toString() ==
                    text
            } catch (_: Exception) {
                false
            }

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail =
                    "chars=${text.length}; verified=$verified"
            )

        if (verified) {
            capabilityRegistry.recordCapabilityEvidence(
                capabilityId = "clipboard_write",
                detail = "ClipboardManager setPrimaryClip + exact read-back verified",
                verified = true
            )

            finishLocalCommand(
                "Текст скопирован в буфер обмена.",
                silent
            )
        } else {
            respondAndResume(
                "Текст был передан в буфер обмена, но запись не удалось подтвердить.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalInternalPageNavigation(
        page: AyanaStructuredLocalCommandRouter.Page,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_ayana_navigation",
            executor = "ayana_internal_navigation_executor"
        )

        val pageKey =
            when (page) {
                AyanaStructuredLocalCommandRouter.Page.HOME -> "HOME"
                AyanaStructuredLocalCommandRouter.Page.TASKS -> "TASKS"
                AyanaStructuredLocalCommandRouter.Page.MEMORY -> "MEMORY"
                AyanaStructuredLocalCommandRouter.Page.HISTORY -> "HISTORY"
                AyanaStructuredLocalCommandRouter.Page.SYSTEM -> "DIAGNOSTICS"
                AyanaStructuredLocalCommandRouter.Page.SETTINGS -> "SETTINGS"
            }

        val pageLabel =
            when (page) {
                AyanaStructuredLocalCommandRouter.Page.HOME -> "Главная"
                AyanaStructuredLocalCommandRouter.Page.TASKS -> "Задачи"
                AyanaStructuredLocalCommandRouter.Page.MEMORY -> "Память"
                AyanaStructuredLocalCommandRouter.Page.HISTORY -> "История"
                AyanaStructuredLocalCommandRouter.Page.SYSTEM -> "Система"
                AyanaStructuredLocalCommandRouter.Page.SETTINGS -> "Настройки"
            }

        if (
            !beginLocalVerifiedSideEffect(
                kind = "ayana_internal_navigation",
                detail = "page=$pageKey"
            )
        ) {
            respondAndResume(
                "Переход отменён до выполнения.",
                silent,
                success = false
            )
            return
        }

        try {
            startActivity(
                Intent(
                    this,
                    MainActivity::class.java
                ).apply {
                    putExtra(
                        MainActivity.EXTRA_OPEN_PAGE,
                        pageKey
                    )

                    addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK or
                            Intent.FLAG_ACTIVITY_CLEAR_TOP or
                            Intent.FLAG_ACTIVITY_SINGLE_TOP
                    )
                }
            )
        } catch (error: Exception) {
            markLocalSideEffectNotCommitted(
                "ayana_navigation_exception:${error.javaClass.simpleName}"
            )
            respondAndResume(
                "Не удалось открыть раздел «$pageLabel» в AYANA.",
                silent,
                success = false,
                technical =
                    "ayana_internal_navigation_exception:${error.javaClass.simpleName}"
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "page=$pageKey"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_page=$pageKey"
            )

        val prefs =
            getSharedPreferences(
                MainActivity.UI_STATE_PREFS,
                Context.MODE_PRIVATE
            )

        val deadline =
            System.currentTimeMillis() +
                1200L

        var actual =
            prefs.getString(
                MainActivity.UI_STATE_CURRENT_PAGE,
                ""
            )
                .orEmpty()

        while (
            actual != pageKey &&
            System.currentTimeMillis() <
            deadline
        ) {
            try {
                Thread.sleep(
                    60L
                )
            } catch (_: InterruptedException) {
                Thread.currentThread()
                    .interrupt()
                break
            }

            actual =
                prefs.getString(
                    MainActivity.UI_STATE_CURRENT_PAGE,
                    ""
                )
                    .orEmpty()
        }

        val verified =
            actual ==
                pageKey

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail =
                    "requested=$pageKey; actual=$actual"
            )

        if (verified) {
            finishLocalCommand(
                "Открыт раздел «$pageLabel» в AYANA.",
                silent
            )
        } else {
            respondAndResume(
                "AYANA открыта, но переход в раздел «$pageLabel» не удалось подтвердить.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalBrightnessSet(
        percent: Int,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_brightness_set",
            executor = "brightness_executor"
        )

        if (percent !in 0..100) {
            respondAndResume(
                "Некорректная яркость: $percent%. Допустимый диапазон — от 0 до 100%.",
                silent,
                success = false
            )
            return
        }

        if (
            Build.VERSION.SDK_INT >=
            Build.VERSION_CODES.M &&
            !Settings.System.canWrite(
                this
            )
        ) {
            respondBlockedAndResume(
                text =
                    "Для точной установки яркости AYANA нужен системный доступ «Изменение системных настроек». Его можно один раз выдать в настройках AYANA. Яркость не изменена.",
                silent = silent,
                technical = "write_settings_permission_required"
            )
            return
        }

        val target =
            ((percent / 100.0) * 255.0)
                .toInt()
                .coerceIn(
                    0,
                    255
                )

        if (
            !beginLocalVerifiedSideEffect(
                kind = "screen_brightness_set",
                detail = "percent=$percent; raw=$target"
            )
        ) {
            respondAndResume(
                "Изменение яркости отменено до выполнения.",
                silent,
                success = false
            )
            return
        }

        val wroteMode =
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
                )
            } catch (_: Exception) {
                false
            }

        val wroteBrightness =
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    target
                )
            } catch (_: Exception) {
                false
            }

        if (
            !wroteMode ||
            !wroteBrightness
        ) {
            markLocalSideEffectNotCommitted(
                "brightness_write_failed; mode=$wroteMode; value=$wroteBrightness"
            )
            respondAndResume(
                "Android не принял изменение яркости.",
                silent,
                success = false
            )
            return
        }

        executionKernel
            .markIrreversibleDispatchAccepted(
                "brightness_raw=$target"
            )
        executionKernel
            .markSideEffectReconciliationStarted(
                "verify_brightness"
            )

        val actual =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS
                )
            } catch (_: Exception) {
                -1
            }

        val mode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val verified =
            abs(
                actual -
                    target
            ) <=
                2 &&
                mode ==
                Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL

        executionKernel
            .markSideEffectReconciled(
                committed = verified,
                detail =
                    "target=$target; actual=$actual; mode=$mode"
            )

        if (verified) {
            finishLocalCommand(
                "Яркость экрана установлена на $percent%.",
                silent
            )
        } else {
            respondAndResume(
                "Изменение яркости не удалось надёжно подтвердить.",
                silent,
                success = false
            )
        }
    }

    private fun runLocalCompositeVolumeAndState(
        level: Int,
        scale: Int,
        silent: Boolean
    ) {
        val request =
            ExactMediaVolumeRequest(
                requestedLevel = level,
                requestedScaleMax = scale,
                percent = false
            )

        val result =
            setExactMediaVolume(
                request
            )

        if (
            !result.optBoolean(
                "success",
                false
            )
        ) {
            respondAndResume(
                result.optString(
                    "message"
                )
                    .ifBlank {
                        "Не удалось установить громкость."
                    },
                silent,
                success = false
            )
            return
        }

        val state =
            agentGetDeviceState()

        val actual =
            state.optInt(
                "media_volume",
                -1
            )

        val max =
            state.optInt(
                "media_volume_max",
                -1
            )

        val battery =
            state.optInt(
                "battery_percent",
                -1
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "multi_intent_verified",
            message = "Обе цели локальной составной команды подтверждены",
            details =
                "volume=$actual/$max; battery=$battery"
        )

        finishLocalCommand(
            "Громкость установлена: $actual из $max. Состояние планшета: заряд $battery%; громкость мультимедиа $actual/$max; ориентация " +
                when (
                    state.optString(
                        "orientation"
                    )
                ) {
                    "landscape" -> "альбомная"
                    "portrait" -> "портретная"
                    else -> "не определена"
                } +
                ".",
            silent
        )
    }

    private fun isLocalDeviceStateRequest(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        val deviceScope =
            normalized.contains("планшет") ||
                normalized.contains("устройств")

        val stateScope =
            normalized.contains("состояни") ||
                normalized.contains("статус")

        val requestIntent =
            normalized.contains("проверь") ||
                normalized.contains("покажи") ||
                normalized.contains("скажи") ||
                normalized.startsWith("какое ") ||
                normalized.startsWith("каков ") ||
                normalized.startsWith("что с ")

        return deviceScope &&
            stateScope &&
            requestIntent
    }

    private fun isLocalScreenStateRequest(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        return normalized in
            setOf(
                "что сейчас на экране",
                "что на экране",
                "что видно на экране",
                "что сейчас видно на экране",
                "прочитай экран",
                "прочитай текущий экран",
                "опиши текущий экран"
            )
    }

    private fun localSingleScrollDirection(
        command: String
    ): String? {
        val normalized =
            command
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        if (
            normalized.contains("до конца") ||
            (
                !normalized.contains("прокрути") &&
                    !normalized.contains("пролистай")
                )
        ) {
            return null
        }

        if (
            !normalized.contains("экран") &&
            !normalized.contains("страниц")
        ) {
            return null
        }

        return when {
            normalized.contains("вверх") ||
                normalized.contains("наверх") ->
                "up"

            normalized.contains("вниз") ||
                normalized.contains("ниже") ->
                "down"

            else ->
                null
        }
    }

    private fun formatLocalScreenSummary(
        screen: JSONObject
    ): String {
        if (
            !screen.optBoolean(
                "snapshot_success",
                screen.optBoolean(
                    "success",
                    false
                )
            )
        ) {
            return "Текущее содержимое экрана надёжно прочитать не удалось."
        }

        val title =
            screen
                .optString(
                    "primary_window_title"
                )
                .trim()

        val packageName =
            screen
                .optString(
                    "interaction_package",
                    screen.optString(
                        "package"
                    )
                )
                .trim()

        val contentState =
            screen
                .optString(
                    "primary_content_state",
                    screen.optString(
                        "content_status"
                    )
                )
                .trim()

        val visible =
            screen
                .optJSONArray(
                    "visible_text"
                )

        val texts =
            mutableListOf<String>()

        if (visible != null) {
            for (
                index in
                0 until minOf(
                    visible.length(),
                    12
                )
            ) {
                val value =
                    visible
                        .optString(
                            index
                        )
                        .replace(
                            Regex("\\s+"),
                            " "
                        )
                        .trim()
                        .take(
                            180
                        )

                if (
                    value.isNotBlank() &&
                    value !in texts
                ) {
                    texts.add(
                        value
                    )
                }
            }
        }

        return buildString {
            append(
                "Текущий экран"
            )

            if (title.isNotBlank()) {
                append(
                    ": "
                )
                append(
                    title
                )
            } else if (packageName.isNotBlank()) {
                append(
                    ": "
                )
                append(
                    packageName
                )
            }

            append(
                "."
)

            if (
                contentState in
                setOf(
                    "unavailable",
                    "structure_only",
                    "unknown"
                ) ||
                texts.isEmpty()
            ) {
                append(
                    " Содержимое читается только частично или недоступно через текущий Accessibility snapshot."
                )
            } else {
                append(
                    " Доступный текст: "
                )
                append(
                    texts.joinToString(
                        " • "
                    )
                )
            }
        }
            .take(
                1800
            )
    }

    private fun runLocalDeviceStateCommand(
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_device_state",
            executor = "device_state_executor"
        )

        val result =
            try {
                agentGetDeviceState()
            } catch (error: Exception) {
                respondAndResume(
                    text = "Не удалось локально прочитать состояние планшета.",
                    silent = silent,
                    success = false,
                    technical =
                        "local_device_state_exception:" +
                            error.javaClass.simpleName
                )
                return
            }

        val battery =
            result.optInt(
                "battery_percent",
                -1
            )

        val volume =
            result.optInt(
                "media_volume",
                -1
            )

        val volumeMax =
            result.optInt(
                "media_volume_max",
                -1
            )

        val orientation =
            when (
                result.optString(
                    "orientation"
                )
            ) {
                "landscape" ->
                    "альбомная"

                "portrait" ->
                    "портретная"

                else ->
                    "не определена"
            }

        val screen =
            result.optJSONObject(
                "screen"
            )

        val answer =
            buildString {
                append(
                    "Состояние планшета: "
                )

                if (battery >= 0) {
                    append(
                        "заряд "
                    )
                    append(
                        battery
                    )
                    append(
                        "%"
                    )

                    if (
                        result.optBoolean(
                            "charging",
                            false
                        )
                    ) {
                        append(
                            " (идёт зарядка)"
                        )
                    }
                } else {
                    append(
                        "заряд не определён"
                    )
                }

                if (
                    volume >= 0 &&
                    volumeMax > 0
                ) {
                    append(
                        "; громкость мультимедиа "
                    )
                    append(
                        volume
                    )
                    append(
                        "/"
                    )
                    append(
                        volumeMax
                    )
                }

                append(
                    "; ориентация "
                )
                append(
                    orientation
                )
                append(
                    "."
                )

                if (screen != null) {
                    append(
                        " "
                    )
                    append(
                        formatLocalScreenSummary(
                            screen
                        )
                    )
                }
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_device_state",
            message = "Состояние планшета прочитано локально",
            details =
                (
                    "battery=$battery; charging=${result.optBoolean("charging", false)}; " +
                        "volume=$volume/$volumeMax; orientation=${result.optString("orientation")}"
                    )
                    .take(
                        700
                    )
        )

        respondAndResume(
            text = answer,
            silent = silent,
            success = true
        )
    }

    private fun runLocalScreenStateCommand(
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_screen_state",
            executor = "screen_state_executor"
        )

        val screen =
            try {
                screenIntelligence
                    .getScreenState()
            } catch (error: Exception) {
                respondAndResume(
                    text = "Не удалось локально прочитать текущий экран.",
                    silent = silent,
                    success = false,
                    technical =
                        "local_screen_state_exception:" +
                            error.javaClass.simpleName
                )
                return
            }

        capabilityRegistry
            .recordScreenObservation(
                screen
            )

        val success =
            screen.optBoolean(
                "snapshot_success",
                screen.optBoolean(
                    "success",
                    false
                )
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_screen_state",
            message =
                if (success) {
                    "Текущий экран прочитан локально"
                } else {
                    "Текущий экран локально не подтверждён"
                },
            details =
                (
                    "package=${screen.optString("effective_foreground_package", screen.optString("interaction_package", screen.optString("package")))}; " +
                        "raw_package=${screen.optString("raw_interaction_package", screen.optString("package"))}; " +
                        "owner_fusion=${screen.optString("foreground_owner_confidence")}; " +
                        "content=${screen.optString("primary_content_state", screen.optString("content_status"))}; " +
                        "nodes=${screen.optInt("primary_node_count", screen.optInt("node_count", 0))}"
                    )
                    .take(
                        700
                    )
        )

        respondAndResume(
            text = formatLocalScreenSummary(
                screen
            ),
            silent = silent,
            success = success
        )
    }

    private fun runLocalSingleScrollCommand(
        direction: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_scroll",
            executor = "screen_scroll_executor"
        )

        val result =
            try {
                screenIntelligence
                    .scroll(
                        direction
                    )
            } catch (error: Exception) {
                respondAndResume(
                    text = "Не удалось выполнить локальную прокрутку.",
                    silent = silent,
                    success = false,
                    technical =
                        "local_scroll_exception:" +
                            error.javaClass.simpleName
                )
                return
            }

        val verified =
            result.optBoolean(
                "verified",
                result.optBoolean(
                    "success",
                    false
                )
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (verified) {
                    "local_scroll_verified"
                } else {
                    "local_scroll_unverified"
                },
            message =
                if (verified) {
                    "Прокрутка подтверждена локально"
                } else {
                    "Прокрутка не подтверждена"
                },
            details =
                result
                    .toString()
                    .take(
                        1200
                    )
        )

        if (verified) {
            finishLocalCommand(
                if (direction == "up") {
                    "Экран прокручен вверх."
                } else {
                    "Экран прокручен вниз."
                },
                silent
            )
        } else {
            respondAndResume(
                text =
                    result
                        .optString(
                            "message",
                            "Android не подтвердил изменение области просмотра."
                        ),
                silent = silent,
                success = false,
                technical =
                    "local_scroll_unverified:" +
                        result.optString(
                            "reason",
                            result.optString(
                                "status"
                            )
                        )
            )
        }
    }

    private fun localAcceptanceTestMode(
        command: String
    ): AyanaAcceptanceTestEngine.Mode? {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        if (normalized.isBlank()) {
            return null
        }

        // Do not steal explicit source-code/unit-test requests from development Q&A.
        val clearlyCodeScoped =
            listOf(
                "юнит тест",
                "unit test",
                "тесты кода",
                "тест кода",
                "тесты файла",
                "протестируй файл",
                "gradle test",
                "github actions"
            ).any(normalized::contains)

        val explicitAyanaScope =
            listOf(
                "аяна",
                "ayana",
                "себя",
                "своих возможност",
                "своих функц",
                "системн",
                "что добавлено",
                "какие функции новые",
                "новые функции",
                "внесли много улучш",
                "проверка сборки",
                "полномасштаб",
                "полноценный тест",
                "полный тест",
                "полная диагностика",
                "подробная диагностика",
                "все тесты",
                "всевозможные тесты"
            ).any(normalized::contains)

        if (clearlyCodeScoped && !explicitAyanaScope) {
            return null
        }

        // v12.17: natural user requests for "full diagnostics/all possible tests"
        // own the widest safe mode, including bounded online transport/context probes.
        val exhaustiveAcceptance =
            listOf(
                "полная диагностика",
                "полную диагностику",
                "подробная диагностика",
                "подробную диагностику",
                "все тесты аяна",
                "все тесты ayana",
                "всевозможные тесты",
                "всевозможные проверки",
                "все возможные тесты",
                "максимальная диагностика",
                "максимальную диагностику",
                "протестируй все функции",
                "протестируй все возможности",
                "протестируй все что можешь",
                "проверь все функции",
                "проверь все возможности",
                "проверь все что можешь",
                "полная проверка аяна",
                "полную проверку аяна"
            ).any(normalized::contains)

        if (exhaustiveAcceptance) {
            return AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
        }

        // Explicit engineering acceptance wording keeps the bounded zero-Agent-Core suite.
        val fullAcceptance =
            listOf(
                "полномасштаб",
                "полный тест своих",
                "полный тест возможност",
                "полный тест функц",
                "полноценный тест",
                "всех своих возможност",
                "всех своих функц",
                "acceptance test",
                "acceptance-тест",
                "приемочн"
            ).any(normalized::contains)

        if (fullAcceptance) {
            return AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE
        }

        val capabilityAudit =
            listOf(
                "что добавлено",
                "какие функции новые",
                "новые функции",
                "что нового в сборке",
                "внесли много улучш",
                "аудит возможност",
                "проверь возможности",
                "проверь функции",
                "проверка сборки"
            ).any(normalized::contains)

        if (capabilityAudit) {
            return AyanaAcceptanceTestEngine.Mode.CAPABILITY_AUDIT
        }

        val genericSelfTest =
            normalized in setOf(
                "проведи тесты",
                "проведи тест",
                "протестируй себя",
                "проверь себя"
            ) ||
                (
                    normalized.contains("проведи тест") &&
                        (
                            normalized.contains("результат") ||
                                normalized.contains("сво") ||
                                normalized.contains("аяна")
                            )
                    ) ||
                (
                    normalized.contains("тест") &&
                        normalized.contains("дай результат")
                    )

        return if (genericSelfTest) {
            AyanaAcceptanceTestEngine.Mode.QUICK_HEALTH
        } else {
            null
        }
    }


    private fun runCapabilityProofSweep(): JSONObject {
        val startedAt =
            System.currentTimeMillis()

        val targetIds =
            listOf(
                "clipboard_write",
                "structured_local_queries",
                "screen_content_reading",
                "google_image_search",
                "speed_test_launcher",
                "extended_accessibility_semantics"
            )

        val snapshot =
            try {
                capabilityRegistry.snapshot()
            } catch (_: Exception) {
                JSONObject()
            }

        val capabilities =
            snapshot.optJSONArray("capabilities")
                ?: JSONArray()

        val byId =
            linkedMapOf<String, JSONObject>()

        for (index in 0 until capabilities.length()) {
            val item =
                capabilities.optJSONObject(index)
                    ?: continue

            val id =
                item.optString("id")
                    .trim()

            if (id.isNotBlank()) {
                byId[id] =
                    item
            }
        }

        val results =
            JSONArray()

        var pendingBefore = 0
        var confirmedNow = 0
        var failedNow = 0
        var skippedAlreadyConfirmed = 0

        val confirmedIds =
            arrayListOf<String>()

        val failedIds =
            arrayListOf<String>()

        val skippedIds =
            arrayListOf<String>()

        targetIds.forEach { capabilityId ->
            val item =
                byId[capabilityId]

            val implemented =
                item?.optBoolean(
                    "implemented",
                    false
                ) == true

            val available =
                item?.optBoolean(
                    "available_now",
                    false
                ) == true

            val alreadyConfirmed =
                item?.optBoolean(
                    "device_confirmed",
                    false
                ) == true

            if (
                !implemented ||
                !available
            ) {
                results.put(
                    JSONObject()
                        .put("capability_id", capabilityId)
                        .put("status", "SKIPPED_UNAVAILABLE")
                        .put("verified", false)
                        .put(
                            "reason",
                            if (!implemented) {
                                "not_implemented"
                            } else {
                                "unavailable_now"
                            }
                        )
                )
                return@forEach
            }

            if (alreadyConfirmed) {
                skippedAlreadyConfirmed++
                skippedIds.add(
                    capabilityId
                )
                results.put(
                    JSONObject()
                        .put("capability_id", capabilityId)
                        .put("status", "ALREADY_CONFIRMED")
                        .put("verified", true)
                )
                return@forEach
            }

            pendingBefore++

            val probe =
                try {
                    when (capabilityId) {
                        "clipboard_write" ->
                            capabilityProbeClipboardWrite()

                        "structured_local_queries" ->
                            capabilityProbeStructuredLocalQueries()

                        "screen_content_reading" ->
                            capabilityProbeScreenContentReading()

                        "google_image_search" ->
                            capabilityProbeExternalUrlRoundTrip(
                                capabilityId = capabilityId,
                                url =
                                    "https://www.google.com/search?tbm=isch&q=" +
                                        Uri.encode(
                                            "AYANA R8.5.4 device proof"
                                        ),
                                detail =
                                    "Google Images ACTION_VIEW dispatched to verified external foreground and AYANA restored"
                            )

                        "speed_test_launcher" ->
                            capabilityProbeExternalUrlRoundTrip(
                                capabilityId = capabilityId,
                                url = "https://fast.com/",
                                detail =
                                    "FAST.com launcher ACTION_VIEW dispatched to verified external foreground and AYANA restored; no Mbps claim"
                            )

                        "extended_accessibility_semantics" ->
                            capabilityProbeExtendedAccessibilitySemantics()

                        else ->
                            JSONObject()
                                .put("verified", false)
                                .put("status", "UNKNOWN_PROBE")
                    }
                } catch (error: Exception) {
                    JSONObject()
                        .put("verified", false)
                        .put("status", "EXCEPTION")
                        .put(
                            "message",
                            (
                                error.message
                                    ?: error.javaClass.simpleName
                                ).take(400)
                        )
                }

            val verified =
                probe.optBoolean(
                    "verified",
                    false
                )

            if (verified) {
                confirmedNow++
                confirmedIds.add(
                    capabilityId
                )

                capabilityRegistry.recordCapabilityEvidence(
                    capabilityId = capabilityId,
                    detail =
                        probe
                            .optString(
                                "detail",
                                "R8.5.4 remaining capability proof verified"
                            )
                            .take(500),
                    verified = true
                )
            } else {
                failedNow++
                failedIds.add(
                    capabilityId +
                        ":" +
                        probe.optString(
                            "status",
                            "UNKNOWN"
                        )
                )
            }

            results.put(
                JSONObject(probe.toString())
                    .put(
                        "capability_id",
                        capabilityId
                    )
            )
        }

        val elapsed =
            (
                System.currentTimeMillis() -
                    startedAt
                ).coerceAtLeast(0L)

        val sweep =
            JSONObject()
                .put("version", "1.0")
                .put("requested", targetIds.size)
                .put("pending_before", pendingBefore)
                .put("confirmed_now", confirmedNow)
                .put("failed_now", failedNow)
                .put(
                    "skipped_already_confirmed",
                    skippedAlreadyConfirmed
                )
                .put("duration_ms", elapsed)
                .put(
                    "confirmed_ids",
                    JSONArray().apply {
                        confirmedIds.forEach {
                            put(it)
                        }
                    }
                )
                .put(
                    "failed_ids",
                    JSONArray().apply {
                        failedIds.forEach {
                            put(it)
                        }
                    }
                )
                .put(
                    "skipped_ids",
                    JSONArray().apply {
                        skippedIds.forEach {
                            put(it)
                        }
                    }
                )
                .put("results", results)

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "device_evidence_sweep",
            message =
                "R8.5.4 remaining capability proof завершён",
            details =
                (
                    "pending_before=$pendingBefore; " +
                        "confirmed_now=$confirmedNow; " +
                        "failed_now=$failedNow; " +
                        "skipped=$skippedAlreadyConfirmed; " +
                        "confirmed=${confirmedIds.joinToString(",")}; " +
                        "failed=${failedIds.joinToString(",")}; " +
                        "duration_ms=$elapsed"
                    ).take(900)
        )

        return sweep
    }

    private fun capabilityProbeClipboardWrite(): JSONObject {
        val clipboard =
            getSystemService(
                Context.CLIPBOARD_SERVICE
            ) as ClipboardManager

        val originalClip =
            try {
                clipboard.primaryClip
            } catch (_: Exception) {
                null
            }

        val hadOriginal =
            try {
                clipboard.hasPrimaryClip()
            } catch (_: Exception) {
                originalClip != null
            }

        val marker =
            "AYANA_R854_CLIP_" +
                UUID.randomUUID()
                    .toString()
                    .take(8)

        var observed =
            false

        var restored =
            false

        try {
            clipboard.setPrimaryClip(
                ClipData.newPlainText(
                    "AYANA acceptance",
                    marker
                )
            )

            Thread.sleep(60L)

            observed =
                try {
                    clipboard
                        .primaryClip
                        ?.getItemAt(0)
                        ?.coerceToText(this)
                        ?.toString() ==
                        marker
                } catch (_: Exception) {
                    false
                }
        } finally {
            restored =
                try {
                    if (
                        hadOriginal &&
                        originalClip != null
                    ) {
                        clipboard.setPrimaryClip(
                            originalClip
                        )
                    } else {
                        if (
                            Build.VERSION.SDK_INT >=
                            Build.VERSION_CODES.P
                        ) {
                            clipboard.clearPrimaryClip()
                        } else {
                            clipboard.setPrimaryClip(
                                ClipData.newPlainText(
                                    "AYANA",
                                    ""
                                )
                            )
                        }
                    }

                    true
                } catch (_: Exception) {
                    false
                }
        }

        val ok =
            observed &&
                restored

        return JSONObject()
            .put("verified", ok)
            .put(
                "status",
                if (ok) {
                    "PASS"
                } else {
                    "FAIL"
                }
            )
            .put(
                "detail",
                "ClipboardManager temporary write + exact read-back + restore verified"
            )
            .put("write_readback_verified", observed)
            .put("state_restored", restored)
    }

    private fun capabilityProbeStructuredLocalQueries(): JSONObject {
        // R8.5.4: prove the contract the Structured Router actually owns.
        // Device metrics have their own aggregate local route, so requiring
        // «покажи заряд батареи» to become StructuredLocalCommandRouter.DeviceMetric
        // created a false coverage gap even while the production metric route passed.
        val basicIntent =
            AyanaStructuredLocalCommandRouter
                .parse(
                    "покажи последние 3 уведомления"
                )

        val filteredIntent =
            AyanaStructuredLocalCommandRouter
                .parse(
                    "покажи последние 3 уведомления от Google"
                )

        val basicNotification =
            basicIntent as?
                AyanaStructuredLocalCommandRouter.Intent.NotificationRead

        val filteredNotification =
            filteredIntent as?
                AyanaStructuredLocalCommandRouter.Intent.NotificationRead

        val limitTyped =
            basicNotification?.limit ==
                3

        val filterTyped =
            filteredNotification != null &&
                filteredNotification.limit ==
                3 &&
                filteredNotification.appFilter
                    .orEmpty()
                    .contains(
                        "google",
                        ignoreCase = true
                    )

        val backend =
            try {
                if (filteredNotification == null) {
                    JSONObject()
                } else {
                    AyanaNotificationListenerService
                        .readRecent(
                            context = this,
                            limit = filteredNotification.limit ?: 3,
                            appFilter = filteredNotification.appFilter,
                            projection = filteredNotification.projection.wireValue
                        )
                }
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put(
                        "error",
                        (
                            error.message
                                ?: error.javaClass.simpleName
                            ).take(300)
                    )
            }

        val backendSuccess =
            backend.optBoolean(
                "success",
                false
            )

        val returned =
            backend
                .optJSONArray(
                    "notifications"
                )
                ?.length()
                ?: 0

        val boundedResult =
            returned <=
                3

        val ok =
            limitTyped &&
                filterTyped &&
                backendSuccess &&
                boundedResult

        return JSONObject()
            .put("verified", ok)
            .put(
                "status",
                if (ok) {
                    "PASS"
                } else {
                    "FAIL"
                }
            )
            .put(
                "detail",
                "Structured local notification query preserved typed limit+app filter and executed through live NotificationListener backend"
            )
            .put("limit_typed", limitTyped)
            .put("filter_typed", filterTyped)
            .put(
                "parsed_app_filter",
                filteredNotification
                    ?.appFilter
                    .orEmpty()
            )
            .put("backend_success", backendSuccess)
            .put("returned", returned)
            .put("bounded_result", boundedResult)
            .put(
                "backend_error",
                backend.optString("error")
            )
    }

    private fun capabilityProbeScreenContentReading(): JSONObject {
        val state =
            try {
                agentGetDeviceState()
            } catch (_: Exception) {
                JSONObject()
            }

        val screen =
            state.optJSONObject(
                "screen"
            ) ?: JSONObject()

        val contentState =
            screen.optString(
                "primary_content_state",
                screen.optString(
                    "content_status",
                    "unknown"
                )
            )

        val textCount =
            maxOf(
                screen.optInt(
                    "primary_readable_text_count",
                    0
                ),
                screen.optInt(
                    "primary_live_readable_text_count",
                    0
                )
            )

        val available =
            screen.optBoolean(
                "primary_content_available",
                false
            )

        val ok =
            screen.optBoolean(
                "success",
                false
            ) &&
                available &&
                contentState in
                setOf(
                    "readable",
                    "partial"
                ) &&
                textCount >
                0

        return JSONObject()
            .put("verified", ok)
            .put(
                "status",
                if (ok) {
                    "PASS"
                } else {
                    "FAIL"
                }
            )
            .put(
                "detail",
                "Live screen content exposed readable/partial primary content with non-zero readable text"
            )
            .put("content_state", contentState)
            .put("text_count", textCount)
            .put(
                "package",
                screen.optString(
                    "package"
                )
            )
    }

    private fun capabilityProbeExternalUrlRoundTrip(
        capabilityId: String,
        url: String,
        detail: String
    ): JSONObject {
        val network =
            readNetworkTruthSnapshot()

        if (
            !network.observationAvailable ||
            !network.connected
        ) {
            return JSONObject()
                .put("verified", false)
                .put("status", "NO_NETWORK")
                .put("detail", detail)
                .put(
                    "network_transport",
                    network.transport
                )
        }

        val uri =
            Uri.parse(
                url
            )

        val baseIntent =
            Intent(
                Intent.ACTION_VIEW,
                uri
            ).apply {
                addFlags(
                    Intent.FLAG_ACTIVITY_NEW_TASK
                )
            }

        val resolved =
            try {
                packageManager.resolveActivity(
                    baseIntent,
                    PackageManager.MATCH_DEFAULT_ONLY
                )
            } catch (_: Exception) {
                null
            }

        val expectedPackage =
            resolved
                ?.activityInfo
                ?.packageName
                .orEmpty()

        if (expectedPackage.isBlank()) {
            return JSONObject()
                .put("verified", false)
                .put("status", "NO_HANDLER")
                .put("detail", detail)
        }

        // Google search URLs may legitimately hand off from the default browser to
        // another installed app that is itself registered for the exact URL. Treat
        // only such registered handlers as eligible evidence; arbitrary foreground
        // packages still fail closed.
        val eligiblePackages =
            linkedSetOf<String>()

        eligiblePackages.add(
            expectedPackage
        )

        fun collectHandlers(
            flags: Int
        ) {
            try {
                packageManager
                    .queryIntentActivities(
                        baseIntent,
                        flags
                    )
                    .forEach { info ->
                        info.activityInfo
                            ?.packageName
                            ?.trim()
                            ?.takeIf {
                                it.isNotBlank() &&
                                    it != packageName
                            }
                            ?.let {
                                eligiblePackages.add(it)
                            }
                    }
            } catch (_: Exception) {
            }
        }

        collectHandlers(
            PackageManager.MATCH_DEFAULT_ONLY
        )
        collectHandlers(
            0
        )

        eligiblePackages.remove(
            packageName
        )

        var dispatched =
            false

        var externalObserved =
            false

        var observedPackage =
            ""

        var restored =
            false

        try {
            startActivity(
                Intent(baseIntent)
                    .setPackage(
                        expectedPackage
                    )
            )

            dispatched =
                true

            val deadline =
                SystemClock.elapsedRealtime() +
                    EXTERNAL_PROOF_MAX_WAIT_MS

            while (
                !externalObserved &&
                SystemClock.elapsedRealtime() <
                deadline
            ) {
                Thread.sleep(
                    EXTERNAL_PROOF_POLL_MS
                )

                val externalState =
                    try {
                        screenIntelligence.getScreenState()
                    } catch (_: Exception) {
                        JSONObject()
                    }

                val candidate =
                    externalState.optString(
                        "effective_foreground_package",
                        externalState.optString(
                            "interaction_package",
                            externalState.optString(
                                "package"
                            )
                        )
                    )
                        .trim()

                if (candidate.isNotBlank()) {
                    observedPackage =
                        candidate
                }

                externalObserved =
                    candidate.isNotBlank() &&
                        candidate !=
                        packageName &&
                        candidate in
                        eligiblePackages
            }
        } finally {
            val restoreDispatched =
                try {
                    startActivity(
                        Intent(
                            this,
                            MainActivity::class.java
                        ).apply {
                            addFlags(
                                Intent.FLAG_ACTIVITY_NEW_TASK or
                                    Intent.FLAG_ACTIVITY_RESET_TASK_IF_NEEDED
                            )
                        }
                    )

                    true
                } catch (_: Exception) {
                    false
                }

            if (restoreDispatched) {
                try {
                    Thread.sleep(
                        EXTERNAL_PROOF_RESTORE_MS
                    )

                    val restoreState =
                        screenIntelligence.getScreenState()

                    val restorePackage =
                        restoreState.optString(
                            "effective_foreground_package",
                            restoreState.optString(
                                "interaction_package",
                                restoreState.optString(
                                    "package"
                                )
                            )
                        )

                    restored =
                        restorePackage ==
                            packageName
                } catch (_: Exception) {
                    restored =
                        false
                }
            }
        }

        val ok =
            dispatched &&
                externalObserved &&
                restored

        val eligibleJson =
            JSONArray()

        eligiblePackages
            .forEach { packageId ->
                eligibleJson.put(
                    packageId
                )
            }

        return JSONObject()
            .put("verified", ok)
            .put(
                "status",
                if (ok) {
                    "PASS"
                } else {
                    "FAIL"
                }
            )
            .put("detail", detail)
            .put("expected_package", expectedPackage)
            .put("observed_package", observedPackage)
            .put("eligible_packages", eligibleJson)
            .put(
                "verification_mode",
                "registered_url_handler_foreground"
            )
            .put("external_foreground_verified", externalObserved)
            .put("state_restored", restored)
            .put("capability_id", capabilityId)
    }

    private fun capabilityProbeExtendedAccessibilitySemantics(): JSONObject {
        val registry =
            try {
                capabilityRegistry.snapshot()
            } catch (_: Exception) {
                JSONObject()
            }

        val runtime =
            registry.optJSONObject(
                "runtime"
            ) ?: JSONObject()

        val accessibilityConnected =
            runtime.optBoolean(
                "accessibility_connected",
                false
            )

        val screen =
            try {
                screenIntelligence.getScreenState()
            } catch (_: Exception) {
                JSONObject()
            }

        val fusionVersion =
            screen.optInt(
                "perception_fusion_version",
                0
            )

        val effectivePackage =
            screen.optString(
                "effective_foreground_package",
                screen.optString(
                    "interaction_package",
                    screen.optString(
                        "package"
                    )
                )
            )

        val rawPackage =
            screen.optString(
                "raw_interaction_package",
                screen.optString(
                    "interaction_package"
                )
            )

        val windowCount =
            screen.optInt(
                "window_count",
                screen.optInt(
                    "raw_window_count",
                    0
                )
            )

        val ok =
            accessibilityConnected &&
                screen.optBoolean(
                    "success",
                    false
                ) &&
                fusionVersion >=
                1 &&
                effectivePackage.isNotBlank() &&
                rawPackage.isNotBlank() &&
                windowCount >=
                1

        return JSONObject()
            .put("verified", ok)
            .put(
                "status",
                if (ok) {
                    "PASS"
                } else {
                    "FAIL"
                }
            )
            .put(
                "detail",
                "Live Accessibility semantics verified: connected service + owner-fusion + raw/effective package + window evidence"
            )
            .put(
                "accessibility_connected",
                accessibilityConnected
            )
            .put(
                "perception_fusion_version",
                fusionVersion
            )
            .put(
                "effective_package",
                effectivePackage
            )
            .put(
                "raw_package",
                rawPackage
            )
            .put(
                "window_count",
                windowCount
            )
    }

    private fun runLocalAcceptanceTestCommand(
        mode: AyanaAcceptanceTestEngine.Mode,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_acceptance_test",
            executor = "acceptance_test_executor"
        )

        broadcastStatus(
            when (mode) {
                AyanaAcceptanceTestEngine.Mode.QUICK_HEALTH ->
                    "Провожу быструю локальную проверку…"

                AyanaAcceptanceTestEngine.Mode.CAPABILITY_AUDIT ->
                    "Проверяю возможности сборки…"

                AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ->
                    "Провожу локальный acceptance-test AYANA…"

                AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE ->
                    "Провожу базовые и самонаправленные тесты AYANA…"
            },
            STATE_EXECUTING
        )

        val evidenceSweep =
            if (
                mode == AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ||
                mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
            ) {
                runCapabilityProofSweep()
            } else {
                JSONObject()
                    .put("version", "1.0")
                    .put("requested", 0)
                    .put("pending_before", 0)
                    .put("confirmed_now", 0)
                    .put("failed_now", 0)
                    .put("skipped_already_confirmed", 0)
                    .put("duration_ms", 0L)
                    .put("results", JSONArray())
            }

        val result =
            try {
                acceptanceTestEngine.run(mode)
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put("execution_success", false)
                    .put("engine", "AyanaAcceptanceTestEngine")
                    .put("engine_version", AyanaAcceptanceTestEngine.ENGINE_VERSION)
                    .put("mode", mode.wireName)
                    .put("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY)
                    .put("passed", 0)
                    .put("warnings", 0)
                    .put("failed", 1)
                    .put("blocked", 0)
                    .put("unsupported", 0)
                    .put("no_data", 0)
                    .put("cancelled", 0)
                    .put("critical_failures", 1)
                    .put("network_turns", 0)
                    .put("duration_ms", 0L)
                    .put("tests", JSONArray())
                    .put("known_limits", JSONArray())
                    .put(
                        "summary",
                        "Локальный acceptance-test не завершён: ${error.message ?: error.javaClass.simpleName}"
                    )
            }

        if (
            mode == AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ||
            mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
        ) {
            reconcileAcceptancePostProbeRuntimeTruth(
                result
            )
        }

        result.put(
            "device_evidence_sweep",
            evidenceSweep
        )

        try {
            capabilityRegistry.recordAcceptanceResult(
                mode = mode.wireName,
                grade = result.optString("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY),
                passed = result.optInt("passed", 0),
                warnings = result.optInt("warnings", 0),
                failed = result.optInt("failed", 0),
                blocked = result.optInt("blocked", 0),
                unsupported = result.optInt("unsupported", 0),
                noData = result.optInt("no_data", 0),
                durationMs = result.optLong("duration_ms", 0L),
                executionSuccess = result.optBoolean("execution_success", false)
            )
        } catch (_: Exception) {
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "acceptance_test_result",
            message =
                "${mode.wireName}: ${result.optString("grade", "UNKNOWN")}",
            details =
                (
                    "engine=${result.optString("engine_version", AyanaAcceptanceTestEngine.ENGINE_VERSION)}; " +
                        "pass=${result.optInt("passed")}; " +
                        "warning=${result.optInt("warnings")}; " +
                        "fail=${result.optInt("failed")}; " +
                        "blocked=${result.optInt("blocked")}; " +
                        "unsupported=${result.optInt("unsupported")}; " +
                        "no_data=${result.optInt("no_data")}; " +
                        "duration_ms=${result.optLong("duration_ms")}; " +
                        "network_turns=${result.optInt("network_turns", 0)}; " +
                        "baseline_tests=${result.optInt("baseline_tests_requested", result.optInt("tests_requested", 0))}; " +
                        "adaptive_tests=${result.optInt("adaptive_tests_generated", 0)}; " +
                        "evidence_sweep_confirmed=${evidenceSweep.optInt("confirmed_now", 0)}; " +
                        "evidence_sweep_failed=${evidenceSweep.optInt("failed_now", 0)}; " +
                        "evidence_sweep_pending_before=${evidenceSweep.optInt("pending_before", 0)}"
                    ).take(1200)
        )

        val baseSummary =
            result
                .optString(
                    if (silent) {
                        "summary"
                    } else {
                        "voice_summary"
                    }
                )
                .ifBlank {
                    result.optString("summary")
                }
                .ifBlank {
                    "Локальная проверка завершена, но итоговый отчёт не сформирован."
                }

        if (!result.optBoolean("execution_success", false)) {
            respondAndResume(
                text = baseSummary,
                silent = silent,
                success = false,
                technical = "acceptance_test_execution_failed:${mode.wireName}"
            )
            return
        }

        // FULL_ACCEPTANCE owns the user-requested end-to-end diagnostic artifact.
        // The suite result may legitimately be NOT_READY while this command itself
        // still succeeds: SUCCESS here means "tests executed and verified report saved".
        if (
            mode == AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ||
            mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
        ) {
            executionPhase(
                phase = "acceptance_report_publish",
                executor = "artifact_engine"
            )

            val reportText =
                try {
                    buildAcceptanceDetailedReport(result)
                } catch (error: Exception) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "acceptance_report_failed",
                        message = "Не удалось сформировать TXT-отчёт диагностики",
                        details = (error.message ?: error.javaClass.simpleName).take(600)
                    )

                    respondAndResume(
                        text =
                            "$baseSummary\n\nТесты выполнены, но TXT-отчёт сформировать не удалось.",
                        silent = silent,
                        success = false,
                        technical = "acceptance_report_build_failed"
                    )
                    return
                }

            val filename =
                (
                    if (mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE) {
                        "AYANA_EXHAUSTIVE_DIAGNOSTICS_"
                    } else {
                        "AYANA_FULL_DIAGNOSTICS_"
                    }
                    ) +
                    DateTimeFormatter
                        .ofPattern("yyyy-MM-dd_HHmmss")
                        .format(LocalDateTime.now()) +
                    ".txt"

            val artifactArguments =
                JSONObject()
                    .put("kind", "txt")
                    .put("filename", filename)
                    .put(
                        "title",
                        if (mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE) {
                            "AYANA Exhaustive Autonomous Diagnostics"
                        } else {
                            "AYANA Full Diagnostics"
                        }
                    )
                    .put("content", reportText)
                    .put("columns", JSONArray())
                    .put("rows", JSONArray())
                    .put("column_types", JSONArray())
                    .put("chart_type", "none")

            val published =
                try {
                    artifactEngine.create(
                        arguments = artifactArguments,
                        tryBeginPublish = { detail ->
                            executionKernel.tryBeginIrreversibleDispatch(
                                kind = "acceptance_report_publish",
                                detail = detail
                            )
                        },
                        onPublishAccepted = { detail ->
                            executionKernel.markIrreversibleDispatchAccepted(
                                detail
                            )
                        },
                        onPublishReconciliationStarted = { detail ->
                            executionKernel.markSideEffectReconciliationStarted(
                                detail
                            )
                        },
                        onPublishReconciled = { committed, detail ->
                            executionKernel.markSideEffectReconciled(
                                committed = committed,
                                detail = detail
                            )
                        }
                    )
                } catch (error: Exception) {
                    JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("message", error.message ?: error.javaClass.simpleName)
                }

            val reportVerified =
                published.optBoolean("success", false) &&
                    published.optString("artifact_reference").isNotBlank()

            if (!reportVerified) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "acceptance_report_failed",
                    message = "Полная диагностика выполнена, но TXT-отчёт не подтверждён",
                    details = published.toString().take(1800)
                )

                respondAndResume(
                    text =
                        "$baseSummary\n\nТесты выполнены, но сохранение итогового TXT-отчёта не подтверждено.",
                    silent = silent,
                    success = false,
                    technical =
                        "acceptance_report_publish_unverified:" +
                            published.toString().take(1200)
                )
                return
            }

            val finalName =
                published
                    .optString("name", filename)
                    .ifBlank { filename }

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "acceptance_report_verified",
                message = "TXT-отчёт полной диагностики создан и проверен",
                details =
                    (
                        "name=$finalName; " +
                            "artifact_reference=${published.optString("artifact_reference").take(600)}; " +
                            "grade=${result.optString("grade")}; " +
                            "tests=${result.optInt("tests_completed", 0)}"
                        ).take(1200)
            )

            finishLocalCommand(
                "$baseSummary\n\nПодробный TXT-отчёт сохранён в Downloads/AYANA: $finalName",
                silent
            )
            return
        }

        finishLocalCommand(
            baseSummary,
            silent
        )
    }

    /**
     * v12.16 diagnostic artifact renderer.
     *
     * It renders only the exact statuses/evidence returned by AyanaAcceptanceTestEngine;
     * it never re-grades a test. This keeps the acceptance engine as the single source
     * of PASS/FAIL truth while allowing the service to persist a human-readable TXT
     * without requiring a parallel Agent Core turn.
     */
    /**
     * R9.0.3 post-probe truth reconciliation.
     *
     * HEALTH-001 is intentionally executed near the beginning of the baseline suite,
     * while ONLINE-001..003 execute later. Those online probes use the isolated
     * acceptance transport and therefore historically did not refresh Capability
     * Registry Agent Core health. This helper closes that temporal gap only when all
     * three bounded online probes are PASS. It never invents PASS from reachability
     * alone and never rewrites a failed online probe.
     */
    private fun reconcileAcceptancePostProbeRuntimeTruth(
        result: JSONObject
    ) {
        val tests =
            result.optJSONArray("tests")
                ?: return

        fun testById(
            id: String
        ): JSONObject? {
            for (index in 0 until tests.length()) {
                val item =
                    tests.optJSONObject(index)
                        ?: continue

                if (item.optString("id") == id) {
                    return item
                }
            }

            return null
        }

        val onlineIds =
            listOf(
                "ONLINE-001",
                "ONLINE-002",
                "ONLINE-003"
            )

        val onlineRows =
            onlineIds.mapNotNull {
                testById(it)
            }

        val allOnlinePassed =
            onlineRows.size == onlineIds.size &&
                onlineRows.all {
                    it.optString("status") ==
                        AyanaAcceptanceTestEngine.STATUS_PASS &&
                        it.optBoolean("verified", false)
                }

        if (!allOnlinePassed) {
            return
        }

        val ordinaryElapsedMs =
            testById("ONLINE-001")
                ?.optJSONObject("evidence")
                ?.optLong("elapsed_ms", 0L)
                ?.coerceAtLeast(0L)
                ?: 0L

        try {
            capabilityRegistry.recordAgentCoreResult(
                success = true,
                latencyMs = ordinaryElapsedMs
            )
        } catch (_: Exception) {
            return
        }

        val reconciledAt =
            System.currentTimeMillis()

        fun mergeProbeIntoExistingRow(
            id: String,
            probe: JSONObject
        ) {
            val row =
                testById(id)
                    ?: return

            row
                .put(
                    "status",
                    probe.optString(
                        "status",
                        row.optString("status")
                    )
                )
                .put(
                    "verified",
                    probe.optBoolean(
                        "verified",
                        row.optBoolean("verified", false)
                    )
                )
                .put(
                    "message",
                    probe.optString(
                        "message",
                        row.optString("message")
                    )
                )
                .put(
                    "evidence_scope",
                    probe.optString(
                        "evidence_scope",
                        row.optString("evidence_scope")
                    )
                )

            val evidence =
                probe.optJSONObject("evidence")
                    ?: JSONObject()

            evidence
                .put("post_probe_reconciled", true)
                .put("agent_core_live_probe_passes", onlineRows.size)
                .put("agent_core_reconciled_at_ms", reconciledAt)
                .put("agent_core_reconciled_latency_ms", ordinaryElapsedMs)

            row.put(
                "evidence",
                evidence
            )
        }

        val recoveryEvidence =
            JSONObject()
                .put(
                    "agent_core_verified_successes",
                    onlineRows.size
                )
                .put(
                    "agent_core_verified_at",
                    reconciledAt
                )

        // R9.0.3: HEALTH-001 is measured before ONLINE/TTS probes. If Marin is
        // UNKNOWN only because its previous measurement is stale, perform a tiny
        // production /tts round-trip without AudioTrack playback, persist that live
        // result, then re-run the diagnostic presentation probes. This proves the
        // actual Worker voice contract (Marin/profile/speed + first PCM bytes) and
        // does not infer TTS health from generic network reachability.
        val ttsFreshnessNeeded =
            acceptanceHealthNeedsFreshTts(
                testById("HEALTH-001")
            )

        val ttsProof =
            if (ttsFreshnessNeeded) {
                runAcceptanceTtsFreshnessProof()
            } else {
                JSONObject()
                    .put("attempted", false)
                    .put("success", true)
                    .put("reason", "fresh_tts_measurement_already_present")
            }

        if (ttsFreshnessNeeded) {
            result.put(
                "network_turns",
                result.optInt("network_turns", 0) + 1
            )

            result.put(
                "duration_ms",
                result.optLong("duration_ms", 0L) +
                    ttsProof.optLong("elapsed_ms", 0L)
            )
        }

        // Re-run only the two diagnostic presentation probes after fresh, verified
        // Agent Core evidence and optional live Marin evidence have been persisted.
        // DiagnosticClosure v1.1 receives Agent Core recovery evidence separately,
        // so it can close a matching historical network incident without pretending
        // acceptance probes were user commands.
        mergeProbeIntoExistingRow(
            "HEALTH-001",
            acceptanceDiagnosticsProbe(
                recoveryEvidence = recoveryEvidence
            )
        )

        mergeProbeIntoExistingRow(
            "EXT-001",
            acceptanceDiagnosticsDetailProbe(
                recoveryEvidence = recoveryEvidence
            )
        )

        testById("HEALTH-001")
            ?.optJSONObject("evidence")
            ?.apply {
                put(
                    "tts_live_probe_attempted",
                    ttsProof.optBoolean("attempted", false)
                )
                put(
                    "tts_live_probe_success",
                    ttsProof.optBoolean("success", false)
                )
                put(
                    "tts_live_probe_http_code",
                    ttsProof.optInt("http_code", -1)
                )
                put(
                    "tts_live_probe_first_byte_ms",
                    ttsProof.optLong("first_byte_ms", -1L)
                )
                put(
                    "tts_live_probe_bytes_observed",
                    ttsProof.optInt("bytes_observed", 0)
                )
                put(
                    "tts_live_probe_voice_contract_verified",
                    ttsProof.optBoolean(
                        "voice_contract_verified",
                        false
                    )
                )
                put(
                    "tts_live_probe_error",
                    ttsProof.optString("error")
                )
            }

        result
            .put("post_probe_health_reconciled", true)
            .put("post_probe_agent_core_passes", onlineRows.size)
            .put("post_probe_agent_core_reconciled_at_ms", reconciledAt)
            .put(
                "post_probe_tts_reconciliation_attempted",
                ttsProof.optBoolean("attempted", false)
            )
            .put(
                "post_probe_tts_reconciliation_success",
                ttsProof.optBoolean("success", false)
            )
            .put(
                "post_probe_tts_first_byte_ms",
                ttsProof.optLong("first_byte_ms", -1L)
            )

        // R9.2.1: Adaptive hypotheses are generated before the post-probe
        // Agent Core/TTS reconciliation. If a baseline non-PASS row becomes PASS
        // after fresh evidence, remove only that now-stale follow-up hypothesis.
        // Other adaptive hypotheses and historical anomalies remain untouched.
        reconcileAdaptiveHypothesesAgainstFinalTests(
            result
        )

        recalculateAcceptanceOutcomeAfterReconciliation(
            result
        )

        // MainActivity's HOME health cards are render-time snapshots. Re-dispatch the
        // current internal page so freshly persisted Agent Core / Marin results become
        // visible without requiring the user to navigate away and back manually.
        refreshCurrentOwnAppPageForRuntimeTruth()
    }

    private fun reconcileAdaptiveHypothesesAgainstFinalTests(
        result: JSONObject
    ) {
        val hypotheses =
            result.optJSONArray("adaptive_hypotheses")
                ?: return

        val tests =
            result.optJSONArray("tests")
                ?: return

        val finalStatuses =
            mutableMapOf<String, String>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            val id =
                item.optString("id")
                    .trim()

            if (id.isNotBlank()) {
                finalStatuses[id] =
                    item.optString("status")
            }
        }

        val reconciled =
            JSONArray()

        var removed =
            0

        for (index in 0 until hypotheses.length()) {
            val item =
                hypotheses.optJSONObject(index)
                    ?: continue

            val staleBaselineFollowUp =
                item.optString("kind") ==
                    "baseline_non_pass_follow_up" &&
                    finalStatuses[
                        item.optString("source_test_id")
                    ] ==
                    AyanaAcceptanceTestEngine.STATUS_PASS

            if (staleBaselineFollowUp) {
                removed++
                continue
            }

            reconciled.put(
                JSONObject(
                    item.toString()
                )
            )
        }

        result
            .put(
                "adaptive_hypotheses",
                reconciled
            )
            .put(
                "adaptive_hypotheses_reconciled",
                true
            )
            .put(
                "adaptive_hypotheses_removed_after_reconciliation",
                removed
            )

        result
            .optJSONObject(
                "adaptive_coverage"
            )
            ?.apply {
                put(
                    "hypotheses_generated",
                    reconciled.length()
                )
                put(
                    "hypotheses_reconciled_removed",
                    removed
                )
            }
    }

    private fun acceptanceHealthNeedsFreshTts(
        healthRow: JSONObject?
    ): Boolean {
        val nonPass =
            healthRow
                ?.optJSONObject("evidence")
                ?.optJSONArray("non_pass_checks")
                ?: return false

        for (index in 0 until nonPass.length()) {
            val item =
                nonPass.optJSONObject(index)
                    ?: continue

            if (
                item.optString("id") == "tts" &&
                item.optString("status") ==
                    AyanaDiagnosticClosure.STATUS_UNKNOWN
            ) {
                return true
            }
        }

        return false
    }

    private fun runAcceptanceTtsFreshnessProof(): JSONObject {
        val startedAt =
            SystemClock.elapsedRealtime()

        var connection:
            HttpsURLConnection? = null

        var httpCode =
            -1

        var firstByteMs =
            -1L

        var bytesObserved =
            0

        var voiceContractVerified =
            false

        return try {
            connection =
                URL(
                    "$WORKER_URL/tts"
                )
                    .openConnection()
                    as HttpsURLConnection

            executionKernel.bindConnection(
                connection
            )

            connection.requestMethod =
                "POST"

            connection.setRequestProperty(
                "Content-Type",
                "application/json"
            )

            connection.setRequestProperty(
                "Accept",
                "application/octet-stream"
            )

            connection.connectTimeout =
                TTS_CONNECT_TIMEOUT_MS

            connection.readTimeout =
                TTS_READ_TIMEOUT_MS

            connection.doOutput =
                true

            val requestJson =
                JSONObject()
                    .put(
                        "text",
                        "Да."
                    )
                    .put(
                        "format",
                        "pcm"
                    )
                    .put(
                        "voice_profile",
                        TTS_VOICE_PROFILE
                    )

            val requestBytes =
                requestJson
                    .toString()
                    .toByteArray(
                        Charsets.UTF_8
                    )

            connection.setFixedLengthStreamingMode(
                requestBytes.size
            )

            connection.outputStream
                .use { output ->
                    output.write(
                        requestBytes
                    )
                }

            httpCode =
                connection.responseCode

            if (httpCode !in 200..299) {
                val body =
                    try {
                        connection.errorStream
                            ?.bufferedReader()
                            ?.use {
                                it.readText()
                            }
                            .orEmpty()
                            .take(400)
                    } catch (_: Exception) {
                        ""
                    }

                throw IllegalStateException(
                    "TTS HTTP $httpCode ${body.trim()}"
                        .trim()
                )
            }

            verifyTtsVoiceContract(
                connection
            )

            voiceContractVerified =
                true

            connection.inputStream
                .use { input ->
                    val buffer =
                        ByteArray(
                            512
                        )

                    val read =
                        input.read(
                            buffer
                        )

                    if (read <= 0) {
                        throw IllegalStateException(
                            "TTS PCM health probe was empty"
                        )
                    }

                    bytesObserved =
                        read

                    firstByteMs =
                        (
                            SystemClock.elapsedRealtime() -
                                startedAt
                            )
                            .coerceAtLeast(0L)
                }

            capabilityRegistry.recordTtsResult(
                success = true,
                firstByteMs = firstByteMs,
                error = ""
            )

            JSONObject()
                .put("attempted", true)
                .put("success", true)
                .put("http_code", httpCode)
                .put("first_byte_ms", firstByteMs)
                .put("bytes_observed", bytesObserved)
                .put(
                    "voice_contract_verified",
                    voiceContractVerified
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            startedAt
                        )
                        .coerceAtLeast(0L)
                )
                .put("error", "")
        } catch (error: Exception) {
            val technical =
                ttsTechnicalError(
                    error
                )

            try {
                capabilityRegistry.recordTtsResult(
                    success = false,
                    firstByteMs = firstByteMs,
                    error = technical
                )
            } catch (_: Exception) {
            }

            JSONObject()
                .put("attempted", true)
                .put("success", false)
                .put("http_code", httpCode)
                .put("first_byte_ms", firstByteMs)
                .put("bytes_observed", bytesObserved)
                .put(
                    "voice_contract_verified",
                    voiceContractVerified
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            startedAt
                        )
                        .coerceAtLeast(0L)
                )
                .put(
                    "error",
                    technical.take(600)
                )
        } finally {
            connection
                ?.let {
                    executionKernel.clearConnection(
                        it
                    )
                }

            try {
                connection?.disconnect()
            } catch (_: Exception) {
            }
        }
    }

    private fun recalculateAcceptanceOutcomeAfterReconciliation(
        result: JSONObject
    ) {
        val tests =
            result.optJSONArray("tests")
                ?: return

        var passed = 0
        var warnings = 0
        var failed = 0
        var blocked = 0
        var unsupported = 0
        var noData = 0
        var cancelled = 0
        var criticalFailures = 0

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            when (item.optString("status")) {
                AyanaAcceptanceTestEngine.STATUS_PASS ->
                    passed++

                AyanaAcceptanceTestEngine.STATUS_WARNING ->
                    warnings++

                AyanaAcceptanceTestEngine.STATUS_FAIL -> {
                    failed++
                    if (item.optBoolean("critical", false)) {
                        criticalFailures++
                    }
                }

                AyanaAcceptanceTestEngine.STATUS_BLOCKED ->
                    blocked++

                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED ->
                    unsupported++

                AyanaAcceptanceTestEngine.STATUS_NO_DATA ->
                    noData++

                AyanaAcceptanceTestEngine.STATUS_CANCELLED ->
                    cancelled++

                else -> {
                    failed++
                    if (item.optBoolean("critical", false)) {
                        criticalFailures++
                    }
                }
            }
        }

        val limits =
            result.optJSONArray("known_limits")
                ?: JSONArray()

        val grade =
            when {
                cancelled > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_CANCELLED

                criticalFailures > 0 || failed > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_NOT_READY

                blocked > 0 ||
                    unsupported > 0 ||
                    noData > 0 ||
                    warnings > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_READY_WITH_LIMITATIONS

                result.optString("mode") !=
                    AyanaAcceptanceTestEngine.Mode.QUICK_HEALTH.wireName &&
                    limits.length() > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_READY_WITH_LIMITATIONS

                else ->
                    AyanaAcceptanceTestEngine.GRADE_READY
            }

        result
            .put("passed", passed)
            .put("warnings", warnings)
            .put("failed", failed)
            .put("blocked", blocked)
            .put("unsupported", unsupported)
            .put("no_data", noData)
            .put("cancelled", cancelled)
            .put("critical_failures", criticalFailures)
            .put("grade", grade)
            .put("execution_success", cancelled == 0)
            .put("success", cancelled == 0)
            .put(
                "summary",
                buildReconciledAcceptanceSummary(
                    result = result,
                    voice = false
                )
            )
            .put(
                "voice_summary",
                buildReconciledAcceptanceSummary(
                    result = result,
                    voice = true
                )
            )
    }

    private fun buildReconciledAcceptanceSummary(
        result: JSONObject,
        voice: Boolean
    ): String {
        val tests =
            result.optJSONArray("tests")
                ?: JSONArray()

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaAcceptanceTestEngine.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val priorityOrder =
            mapOf(
                AyanaAcceptanceTestEngine.STATUS_FAIL to 0,
                AyanaAcceptanceTestEngine.STATUS_BLOCKED to 1,
                AyanaAcceptanceTestEngine.STATUS_WARNING to 2,
                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED to 3,
                AyanaAcceptanceTestEngine.STATUS_NO_DATA to 4,
                AyanaAcceptanceTestEngine.STATUS_CANCELLED to 5
            )

        val prioritized =
            nonPass
                .sortedWith(
                    compareBy<JSONObject> {
                        priorityOrder[
                            it.optString("status")
                        ] ?: 99
                    }.thenByDescending {
                        it.optBoolean("critical", false)
                    }
                )
                .take(
                    if (voice) {
                        3
                    } else {
                        5
                    }
                )

        val modeLabel =
            if (
                result.optString("mode") ==
                AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE.wireName
            ) {
                "Всесторонняя автономная диагностика AYANA завершена."
            } else {
                "Полная диагностика AYANA завершена."
            }

        return buildString {
            append(modeLabel)
            append("\n\n")
            append(
                "Итог: PASS ${result.optInt("passed", 0)}, " +
                    "WARNING ${result.optInt("warnings", 0)}, " +
                    "FAIL ${result.optInt("failed", 0)}, " +
                    "BLOCKED ${result.optInt("blocked", 0)}, " +
                    "UNSUPPORTED ${result.optInt("unsupported", 0)}, " +
                    "NO_DATA ${result.optInt("no_data", 0)}."
            )
            append("\n")
            append(
                "Статус готовности: ${result.optString("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY)}."
            )
            append("\n")
            append(
                "Время теста: ${result.optLong("duration_ms", 0L)} мс. " +
                    "Сетевых обращений Agent Core/Worker: ${result.optInt("network_turns", 0)}. " +
                    "Всего проверок: ${result.optInt("tests_completed", tests.length())}; " +
                    "самонаправленно сгенерировано: ${result.optInt("adaptive_tests_generated", 0)}."
            )

            if (prioritized.isNotEmpty()) {
                append("\n\nТребуют внимания:\n")
                prioritized.forEachIndexed { index, item ->
                    append(index + 1)
                    append(". ")
                    append(item.optString("title"))
                    append(": ")
                    append(
                        when (item.optString("status")) {
                            AyanaAcceptanceTestEngine.STATUS_FAIL -> "ошибка"
                            AyanaAcceptanceTestEngine.STATUS_WARNING -> "предупреждение"
                            AyanaAcceptanceTestEngine.STATUS_NO_DATA -> "нет данных"
                            AyanaAcceptanceTestEngine.STATUS_BLOCKED -> "заблокировано"
                            AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED -> "не поддерживается"
                            else -> item.optString("status").lowercase(Locale.ROOT)
                        }
                    )
                    append(" — ")
                    append(
                        item.optString("message")
                            .replace("\n", " ")
                            .take(
                                if (voice) {
                                    280
                                } else {
                                    560
                                }
                            )
                    )
                    append("\n")
                }
            }

            if (!voice) {
                append(
                    "\nПолный список ${tests.length()} проверок сохранён в подробном TXT-отчёте; " +
                        "в ответе показаны только приоритетные отклонения."
                )
            }
        }
    }

    private fun refreshCurrentOwnAppPageForRuntimeTruth() {
        try {
            val prefs =
                getSharedPreferences(
                    MainActivity.UI_STATE_PREFS,
                    Context.MODE_PRIVATE
                )

            val page =
                prefs.getString(
                    MainActivity.UI_STATE_CURRENT_PAGE,
                    "HOME"
                )
                    .orEmpty()
                    .takeIf {
                        it in setOf(
                            "HOME",
                            "TASKS",
                            "MEMORY",
                            "HISTORY",
                            "DIAGNOSTICS",
                            "SETTINGS"
                        )
                    }
                    ?: "HOME"

            startActivity(
                Intent(
                    this,
                    MainActivity::class.java
                ).apply {
                    putExtra(
                        MainActivity.EXTRA_OPEN_PAGE,
                        page
                    )
                    addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK or
                            Intent.FLAG_ACTIVITY_CLEAR_TOP or
                            Intent.FLAG_ACTIVITY_SINGLE_TOP
                    )
                }
            )
        } catch (_: Exception) {
            // Registry truth is already persisted; UI refresh is best-effort only.
        }
    }

    private fun buildAcceptanceDetailedReport(
        result: JSONObject
    ): String {
        val tests =
            result.optJSONArray("tests")
                ?: JSONArray()

        val limits =
            result.optJSONArray("known_limits")
                ?: JSONArray()

        val durationMs =
            result.optLong("duration_ms", 0L)

        val generatedAt =
            result.optLong("finished_at_ms", System.currentTimeMillis())

        val startedAt =
            result.optLong(
                "started_at_ms",
                if (durationMs > 0L) {
                    (generatedAt - durationMs).coerceAtLeast(0L)
                } else {
                    0L
                }
            )

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaAcceptanceTestEngine.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val priorityOrder =
            mapOf(
                AyanaAcceptanceTestEngine.STATUS_FAIL to 0,
                AyanaAcceptanceTestEngine.STATUS_BLOCKED to 1,
                AyanaAcceptanceTestEngine.STATUS_WARNING to 2,
                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED to 3,
                AyanaAcceptanceTestEngine.STATUS_NO_DATA to 4,
                AyanaAcceptanceTestEngine.STATUS_CANCELLED to 5
            )

        val prioritized =
            nonPass.sortedWith(
                compareBy<JSONObject> {
                    priorityOrder[
                        it.optString("status")
                    ] ?: 99
                }.thenByDescending {
                    it.optBoolean(
                        "critical",
                        false
                    )
                }
            )

        val detailedReport = buildString {
            append(
                if (
                    result.optString("mode") ==
                    AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE.wireName
                ) {
                    "AYANA — ВСЕСТОРОННИЙ АВТОНОМНЫЙ ОТЧЁТ ДИАГНОСТИКИ\n"
                } else {
                    "AYANA — ПОЛНЫЙ ОТЧЁТ ДИАГНОСТИКИ\n"
                }
            )
            append("========================================\n")
            append("Engine: ${result.optString("engine", "AyanaAcceptanceTestEngine")} v${result.optString("engine_version", "unknown")}\n")
            append("Режим: ${result.optString("mode", "full_acceptance")}\n")
            append("Начало: ${formatAcceptanceReportTime(startedAt)}\n")
            append("Окончание: ${formatAcceptanceReportTime(generatedAt)}\n")
            append("Длительность: $durationMs мс\n")
            append("Agent Core network turns: ${result.optInt("network_turns", 0)}\n")
            append("Выполнение набора тестов завершено: ${result.optBoolean("execution_success", false)}\n")
            append("Readiness grade: ${result.optString("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY)}\n")
            append("\n")
            append("ИТОГОВЫЕ СЧЁТЧИКИ\n")
            append("----------------------------------------\n")
            append("PASS: ${result.optInt("passed", 0)}\n")
            append("WARNING: ${result.optInt("warnings", 0)}\n")
            append("FAIL: ${result.optInt("failed", 0)}\n")
            append("BLOCKED: ${result.optInt("blocked", 0)}\n")
            append("UNSUPPORTED: ${result.optInt("unsupported", 0)}\n")
            append("NO_DATA: ${result.optInt("no_data", 0)}\n")
            append("CANCELLED: ${result.optInt("cancelled", 0)}\n")
            append("Critical failures: ${result.optInt("critical_failures", 0)}\n")
            append("Тестов запрошено: ${result.optInt("tests_requested", tests.length())}\n")
            append("Тестов завершено: ${result.optInt("tests_completed", tests.length())}\n")
            append("Baseline tests: ${result.optInt("baseline_tests_requested", result.optInt("tests_requested", tests.length()))}\n")
            append("Self-directed tests generated: ${result.optInt("adaptive_tests_generated", 0)}\n")
            val adaptiveEngine = result.optString("adaptive_engine")
            if (adaptiveEngine.isNotBlank()) {
                append("Adaptive engine: $adaptiveEngine v${result.optString("adaptive_engine_version", "unknown")}\n")
            }

            val evidenceSweep =
                result.optJSONObject("device_evidence_sweep")
                    ?: JSONObject()

            if (evidenceSweep.length() > 0) {
                append(
                    "Device evidence sweep: pending_before=${evidenceSweep.optInt("pending_before", 0)}; " +
                        "confirmed_now=${evidenceSweep.optInt("confirmed_now", 0)}; " +
                        "failed_now=${evidenceSweep.optInt("failed_now", 0)}; " +
                        "skipped=${evidenceSweep.optInt("skipped_already_confirmed", 0)}; " +
                        "duration=${evidenceSweep.optLong("duration_ms", 0L)} мс\n"
                )

                fun compactSweepIds(
                    key: String
                ): String {
                    val values =
                        evidenceSweep.optJSONArray(key)
                            ?: JSONArray()

                    val items =
                        arrayListOf<String>()

                    for (index in 0 until values.length()) {
                        values.optString(index)
                            .trim()
                            .takeIf {
                                it.isNotBlank()
                            }
                            ?.let {
                                items.add(it)
                            }
                    }

                    return items.joinToString(", ")
                }

                val confirmedIds =
                    compactSweepIds(
                        "confirmed_ids"
                    )

                val failedIds =
                    compactSweepIds(
                        "failed_ids"
                    )

                if (confirmedIds.isNotBlank()) {
                    append(
                        "Device evidence confirmed: $confirmedIds\n"
                    )
                }

                if (failedIds.isNotBlank()) {
                    append(
                        "Device evidence failed: $failedIds\n"
                    )
                }
            }
            append("\n")
            append("КОНТРАКТ ДОСТОВЕРНОСТИ\n")
            append("----------------------------------------\n")
            append("execution_success=true означает только то, что сам набор диагностики завершился.\n")
            append("Это не означает, что все функции AYANA исправны. Готовность определяется grade и статусами каждого теста.\n")

            if (prioritized.isNotEmpty()) {
                append("\nПРИОРИТЕТНЫЕ ПРОБЛЕМЫ\n")
                append("----------------------------------------\n")

                prioritized.forEachIndexed {
                    index,
                    item ->
                    append(
                        "${index + 1}. ${item.optString("status")} — " +
                            "${item.optString("id")} — ${item.optString("title")}\n"
                    )
                    append("   Critical: ${item.optBoolean("critical", false)}\n")
                    append(
                        "   Message: " +
                            item.optString("message")
                                .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                            "\n"
                    )
                    append("   Evidence scope: ${item.optString("evidence_scope")}\n")
                }
            }

            append("\nВСЕ ТЕСТЫ\n")
            append("========================================\n")

            for (index in 0 until tests.length()) {
                val item =
                    tests.optJSONObject(index)
                        ?: continue

                val status =
                    item.optString("status")

                val id =
                    item.optString("id")

                val compactAdaptivePass =
                    id.startsWith("AUTO-") &&
                        status == AyanaAcceptanceTestEngine.STATUS_PASS

                append(
                    "[${index + 1}/${tests.length()}] $status — " +
                        "$id — ${item.optString("title")}\n"
                )

                // Generated PASS matrices can be numerous. Preserve every test row
                // while avoiding repetitive successful evidence in the TXT artifact.
                // Every baseline test and every non-PASS adaptive test stays detailed.
                if (compactAdaptivePass) {
                    continue
                }

                append("Critical: ${item.optBoolean("critical", false)}\n")
                append("Verified: ${item.optBoolean("verified", false)}\n")
                append("Duration: ${item.optLong("duration_ms", 0L)} мс\n")
                append("Evidence scope: ${item.optString("evidence_scope")}\n")
                append(
                    "Message: " +
                        item.optString("message")
                            .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                        "\n"
                )

                val evidence =
                    item.optJSONObject("evidence")
                        ?: JSONObject()

                if (evidence.length() > 0) {
                    append("Evidence: ")
                    append(
                        evidence
                            .toString(2)
                            .take(ACCEPTANCE_REPORT_EVIDENCE_LIMIT)
                    )
                    append("\n")
                }

                append("----------------------------------------\n")
            }

            val adaptiveCoverage =
                result.optJSONObject("adaptive_coverage")
                    ?: JSONObject()
            val adaptiveHypotheses =
                result.optJSONArray("adaptive_hypotheses")
                    ?: JSONArray()
            val adaptiveAnomalies =
                result.optJSONArray("adaptive_anomalies")
                    ?: JSONArray()

            if (adaptiveCoverage.length() > 0) {
                append("\nSELF-DIRECTED COVERAGE\n")
                append("========================================\n")
                append(adaptiveCoverage.toString(2).take(ACCEPTANCE_REPORT_EVIDENCE_LIMIT))
                append("\n")
            }

            if (adaptiveHypotheses.length() > 0) {
                append("\nАВТОНОМНО СФОРМИРОВАННЫЕ ГИПОТЕЗЫ / СЛЕДУЮЩИЕ ПРОВЕРКИ\n")
                append("========================================\n")
                for (index in 0 until adaptiveHypotheses.length()) {
                    val item = adaptiveHypotheses.optJSONObject(index) ?: continue
                    append("${index + 1}. ${item.optString("priority", "normal").uppercase(Locale.ROOT)} — ${item.optString("kind")}\n")
                    append("   ${item.optString("hypothesis").take(ACCEPTANCE_REPORT_MESSAGE_LIMIT)}\n")
                    val sourceTest = item.optString("source_test_id")
                    val capabilityId = item.optString("capability_id")
                    if (sourceTest.isNotBlank()) append("   source_test=$sourceTest\n")
                    if (capabilityId.isNotBlank()) append("   capability=$capabilityId\n")
                    append("   safe_execution=${item.optString("safe_execution")}\n")
                }
            }

            if (adaptiveAnomalies.length() > 0) {
                append("\nАНОМАЛИИ, НАЙДЕННЫЕ ПО РЕАЛЬНОЙ ИСТОРИИ\n")
                append("========================================\n")
                for (index in 0 until adaptiveAnomalies.length()) {
                    val item = adaptiveAnomalies.optJSONObject(index) ?: continue
                    append("${index + 1}. ${item.optString("kind")} — ${item.optString("message").take(ACCEPTANCE_REPORT_MESSAGE_LIMIT)}\n")
                    append("   history_id=${item.optString("history_id")}\n")
                    append("   command=${item.optString("command").take(500)}\n")
}
            }

            if (limits.length() > 0) {
                append("\nИЗВЕСТНЫЕ ОГРАНИЧЕНИЯ\n")
                append("========================================\n")

                for (index in 0 until limits.length()) {
                    val raw =
                        limits.opt(index)

                    when (raw) {
                        is JSONObject -> {
                            append("${index + 1}. ")
                            append(
                                raw.optString("label")
                                    .ifBlank {
                                        raw.optString("id")
                                    }
                                    .ifBlank {
                                        raw.toString()
                                    }
                                    .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT)
                            )

                            val note =
                                raw.optString("note")
                                    .ifBlank {
                                        raw.optString("next")
                                    }
                                    .ifBlank {
                                        raw.optString("message")
                                    }

                            if (note.isNotBlank()) {
                                append(
                                    " — " +
                                        note.take(
                                            ACCEPTANCE_REPORT_MESSAGE_LIMIT
                                        )
                                )
                            }

                            append("\n")
                        }

                        else ->
                            append(
                                "${index + 1}. " +
                                    raw
                                        ?.toString()
                                        .orEmpty()
                                        .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                                    "\n"
                            )
                    }
                }
            }

            append("\nСВОДКА\n")
            append("========================================\n")
            append(
                result.optString("summary")
                    .take(ACCEPTANCE_REPORT_SUMMARY_LIMIT)
            )
            append("\n")
            append(
                "REPORT_COMPLETE tests=${tests.length()}; " +
                    "adaptive=${result.optInt("adaptive_tests_generated", 0)}; " +
                    "renderer=v12.21.0-r7.9\n"
            )
        }

        if (
            detailedReport.length <=
            ACCEPTANCE_REPORT_SAFE_CHAR_BUDGET
        ) {
            return detailedReport
        }

        return buildAcceptanceCompactReport(
            result
        )
    }

    /**
     * Last-resort persistence renderer.
     *
     * If adaptive coverage grows beyond the safe detailed TXT budget, rebuild a
     * complete one-line index of every test rather than letting Artifact Engine
     * silently cut the report tail.
     */
    private fun buildAcceptanceCompactReport(
        result: JSONObject
    ): String {
        val tests =
            result.optJSONArray("tests")
                ?: JSONArray()

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaAcceptanceTestEngine.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val compact =
            buildString {
                append("AYANA — COMPACT COMPLETE DIAGNOSTIC INDEX\n")
                append("========================================\n")
                append("Engine: ${result.optString("engine")} v${result.optString("engine_version")}\n")
                append("Mode: ${result.optString("mode")}\n")
                append("Grade: ${result.optString("grade")}\n")
                append(
                    "PASS=${result.optInt("passed", 0)}; " +
                        "WARNING=${result.optInt("warnings", 0)}; " +
                        "FAIL=${result.optInt("failed", 0)}; " +
                        "BLOCKED=${result.optInt("blocked", 0)}; " +
                        "UNSUPPORTED=${result.optInt("unsupported", 0)}; " +
                        "NO_DATA=${result.optInt("no_data", 0)}\n"
                )
                append(
                    "tests=${tests.length()}; " +
                        "baseline=${result.optInt("baseline_tests", 0)}; " +
                        "adaptive=${result.optInt("adaptive_tests_generated", 0)}\n"
                )
                append(
                    "NOTE: compact fallback activated before TXT artifact limit; " +
                        "no test rows were omitted.\n"
                )

                if (nonPass.isNotEmpty()) {
                    append("\nNON-PASS DETAILS\n")
                    append("----------------------------------------\n")
                    nonPass.forEach { item ->
                        append(
                            "${item.optString("status")} — " +
                                "${item.optString("id")} — " +
                                "${item.optString("title")}\n"
                        )
                        append(
                            "Message: " +
                                item.optString("message")
                                    .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                                "\n"
                        )
                        append(
                            "Scope: ${item.optString("evidence_scope")}; " +
                                "critical=${item.optBoolean("critical", false)}; " +
                                "verified=${item.optBoolean("verified", false)}\n"
                        )
                    }
                }

                append("\nALL TESTS — COMPLETE INDEX\n")
                append("========================================\n")

                for (index in 0 until tests.length()) {
                    val item =
                        tests.optJSONObject(index)
                            ?: continue

                    append(
                        "[${index + 1}/${tests.length()}] " +
                            "${item.optString("status")} — " +
                            "${item.optString("id")} — " +
                            item.optString("title")
                                .replace("\n", " ")
                                .take(260) +
                            "\n"
                    )
                }

                append("\n")
                append(
                    "REPORT_COMPLETE tests=${tests.length()}; " +
                        "adaptive=${result.optInt("adaptive_tests_generated", 0)}; " +
                        "renderer=v12.21.0-r7.9-compact\n"
                )
            }

        if (
            compact.length >
            ACCEPTANCE_REPORT_HARD_CHAR_BUDGET
        ) {
            throw IllegalStateException(
                "acceptance_report_too_large_even_compact:" +
                    compact.length
            )
        }

        return compact
    }

    private fun formatAcceptanceReportTime(
        timestampMs: Long
    ): String {
        if (timestampMs <= 0L) {
            return "нет данных"
        }

        return try {
            java.text.SimpleDateFormat(
                "yyyy-MM-dd HH:mm:ss Z",
                Locale.getDefault()
            ).format(
                java.util.Date(
                    timestampMs
                )
            )
        } catch (_: Exception) {
            timestampMs.toString()
        }
    }

    private fun runAcceptanceProbe(
        probeId: String
    ): JSONObject {
        return when (probeId) {
            AyanaAcceptanceTestEngine.PROBE_DIAGNOSTICS_LIVE ->
                acceptanceDiagnosticsProbe()

            AyanaAcceptanceTestEngine.PROBE_RUNTIME_CAPABILITIES ->
                acceptanceRuntimeCapabilitiesProbe()

