    private fun runR9FoundationProbes(): JSONArray {
        val tests =
            JSONArray()

        fun add(
            id: String,
            title: String,
            critical: Boolean,
            ok: Boolean,
            message: String,
            evidence: JSONObject
        ) {
            tests.put(
                JSONObject()
                    .put("id", id)
                    .put("title", title)
                    .put(
                        "status",
                        if (ok) {
                            AyanaAcceptanceTestEngine.STATUS_PASS
                        } else {
                            AyanaAcceptanceTestEngine.STATUS_FAIL
                        }
                    )
                    .put("critical", critical)
                    .put("verified", ok)
                    .put("message", message)
                    .put("evidence_scope", "r9_foundation_contract")
                    .put("evidence", evidence)
            )
        }

        val recoveryOk =
            try {
                agentCoreRecoveryPolicy.selfTest()
            } catch (_: Exception) {
                false
            }

        add(
            id = "R9-FOUND-001",
            title = "Agent Core bounded completion recovery contract",
            critical = true,
            ok = recoveryOk,
            message =
                if (recoveryOk) {
                    "Read-only incomplete-response recovery is bounded and side-effect requests remain fail-closed."
                } else {
                    "R9 Agent Core recovery contract self-test failed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaAgentCoreRecoveryPolicy.VERSION)
                    .put("compact_restart_budget", 1)
                    .put("side_effect_restart_allowed", false)
        )

        val graphOk =
            try {
                AyanaAutonomousTaskGraph.selfTest()
            } catch (_: Exception) {
                false
            }

        add(
            id = "R9-FOUND-002",
            title = "Autonomous Task Graph recovery/reconciliation ledger contract",
            critical = true,
            ok = graphOk,
            message =
                if (graphOk) {
                    "Task Graph v2 create/dispatch/result/recovery/reconciliation/persistence/backward-restore contract verified."
                } else {
                    "R9.2 Autonomous Task Graph v2 self-test failed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaAutonomousTaskGraph.VERSION)
                    .put("durable_goal_orchestrator_replaced", false)
                    .put("reconciliation_ledger", true)
                    .put("pre_dispatch_persistence_guard", true)
                    .put("read_only_observation_preserves_mutation_identity", true)
                    .put("blind_replay_authority", false)
        )

        val diagnosticOk =
            try {
                diagnosticClosure.selfTest()
            } catch (_: Exception) {
                false
            }

        add(
            id = "R9-FOUND-003",
            title = "Diagnostic freshness and latency attribution contract",
            critical = false,
            ok = diagnosticOk,
            message =
                if (diagnosticOk) {
                    "Historical incident closure preserves UNKNOWN truth and separates server/model wait from local latency."
                } else {
                    "R9 Diagnostic Closure self-test failed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaDiagnosticClosure.VERSION)
                    .put(
                        "active_incident_window_ms",
                        AyanaDiagnosticClosure.ACTIVE_INCIDENT_WINDOW_MS
                    )
        )

        val developmentOk =
            try {
                developmentTransactionContract.selfTest()
            } catch (_: Exception) {
                false
            }

        val developmentAvailability =
            developmentTransactionContract.evaluate(
                AyanaDevelopmentTransactionContract.Availability(
                    repositoryAuthorized = false,
                    writeExecutorAvailable = false,
                    commitPushExecutorAvailable = false,
                    buildExecutorAvailable = false,
                    artifactVerifierAvailable = false,
                    rollbackExecutorAvailable = false
                )
            )

        add(
            id = "R9-FOUND-004",
            title = "Development transaction fail-closed foundation",
            critical = true,
            ok =
                developmentOk &&
                    !developmentAvailability.optBoolean(
                        "ready",
                        true
                    ),
            message =
                if (
                    developmentOk &&
                    !developmentAvailability.optBoolean(
                        "ready",
                        true
                    )
                ) {
                    "Development transaction contract exists and correctly remains unavailable without authorized executors."
                } else {
                    "Development transaction contract does not fail closed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaDevelopmentTransactionContract.VERSION)
                    .put(
                        "current_availability",
                        developmentAvailability
                    )
        )

        val proactivityOk =
            try {
                controlledProactivityPolicy.selfTest()
            } catch (_: Exception) {
                false
            }

        add(
            id = "R9-FOUND-005",
            title = "Controlled proactivity permission/cooldown contract",
            critical = true,
            ok = proactivityOk,
            message =
                if (proactivityOk) {
                    "Proactivity policy is evidence-gated, default-closed and never turns notification permission into mutation permission."
                } else {
                    "Controlled proactivity policy self-test failed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaControlledProactivityPolicy.VERSION)
                    .put("watchers_enabled_by_foundation", false)
                    .put("recovery_event_classes_supported", true)
        )

        val autonomousRecoveryOk =
            try {
                autonomousRecoveryCoordinator.selfTest()
            } catch (_: Exception) {
                false
            }

        add(
            id = "R9-FOUND-006",
            title = "Autonomous recovery no-blind-replay contract",
            critical = true,
            ok = autonomousRecoveryOk,
            message =
                if (autonomousRecoveryOk) {
                    "R9.2 recovery retries only allow-listed read-only observations, pauses uncertain side effects and replans pre-dispatch failures."
                } else {
                    "R9.2 Autonomous Recovery Coordinator self-test failed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaAutonomousRecoveryCoordinator.VERSION)
                    .put(
                        "max_local_read_only_retries",
                        AyanaAutonomousRecoveryCoordinator.MAX_LOCAL_READ_ONLY_RETRIES
                    )
                    .put(
                        "max_graph_recoveries",
                        AyanaAutonomousRecoveryCoordinator.MAX_GRAPH_RECOVERIES
                    )
                    .put("blind_side_effect_retry_allowed", false)
        )

        val appIntegrationOk =
            try {
                appIntegrationRegistry.selfTest()
            } catch (_: Exception) {
                false
            }

        add(
            id = "R9-FOUND-007",
            title = "App Integration registry / verified-handoff contract",
            critical = true,
            ok = appIntegrationOk,
            message =
                if (appIntegrationOk) {
                    "R9.3 registers five app domains, exposes no autonomous mutation action and preserves Personal Search ownership for file/photo discovery."
                } else {
                    "R9.3 App Integration Registry self-test failed."
                },
            evidence =
                JSONObject()
                    .put("version", AyanaAppIntegrationRegistry.VERSION)
                    .put("registered_app_domains", appIntegrationRegistry.allApps().size)
                    .put("worker_schema_replaced", false)
                    .put("package_hints_require_device_validation", true)
                    .put("file_photo_search_delegated_to_personal_search", true)
                    .put("calendar_event_commit_claimed", false)
                    .put("autonomous_mutation_actions", 0)
        )

        return tests
    }

    private fun acceptanceDiagnosticsProbe(
        recoveryEvidence: JSONObject? = null
    ): JSONObject {
        val rawDiagnostics =
            selfDiagnostics.run(
                focus = "all"
            )

        val diagnostics =
            diagnosticClosure
                .normalizeSelfDiagnostics(
                    raw = rawDiagnostics,
                    recentHistory =
                        commandHistoryStore
                            .recent(
                                24
                            ),
                    recoveryEvidence = recoveryEvidence
                )

        val passed = diagnostics.optInt("passed", 0)
        val warnings = diagnostics.optInt("warnings", 0)
        val unknown = diagnostics.optInt("unknown", 0)
        val failed = diagnostics.optInt("failed", 0)
        val checks = diagnostics.optJSONArray("checks") ?: JSONArray()

        val nonPass =
            JSONArray()

        for (index in 0 until checks.length()) {
            val item = checks.optJSONObject(index) ?: continue
            if (
                item.optString("status") !=
                AyanaDiagnosticClosure.STATUS_PASS
            ) {
                nonPass.put(
                    JSONObject(item.toString())
                )
            }
        }

        val canonicalReport =
            try {
                diagnosticClosure.reportFromNormalized(
                    diagnostics
                )
            } catch (_: Exception) {
                ""
            }

        val status =
            when {
                failed > 0 -> AyanaAcceptanceTestEngine.STATUS_FAIL
                warnings > 0 -> AyanaAcceptanceTestEngine.STATUS_WARNING
                unknown > 0 -> AyanaAcceptanceTestEngine.STATUS_NO_DATA
                else -> AyanaAcceptanceTestEngine.STATUS_PASS
            }

        return acceptanceProbeResult(
            status = status,
            message =
                buildString {
                    append(
                        "Self-Diagnostics R9 closure: PASS $passed, WARNING $warnings, " +
                            "NO_DATA $unknown, FAIL $failed."
                    )
                    if (canonicalReport.isNotBlank()) {
                        append(" ")
                        append(canonicalReport.take(2200))
                    }
                },
            evidenceScope = "live_runtime_plus_incident_freshness",
            verified = failed == 0,
            evidence =
                JSONObject()
                    .put("passed", passed)
                    .put("warnings", warnings)
                    .put("unknown", unknown)
                    .put("failed", failed)
                    .put(
                        "diagnostic_closure_version",
                        diagnostics.optString(
                            "diagnostic_closure_version",
                            AyanaDiagnosticClosure.VERSION
                        )
                    )
                    .put(
                        "last_error_age_ms",
                        diagnostics.optLong(
                            "last_error_age_ms",
                            -1L
                        )
                    )
                    .put(
                        "successes_after_last_error",
                        diagnostics.optInt(
                            "successes_after_last_error",
                            0
                        )
                    )
                    .put(
                        "live_agent_core_recovery_passes",
                        diagnostics.optInt(
                            "live_agent_core_recovery_passes",
                            0
                        )
                    )
                    .put(
                        "live_agent_core_recovery_applied",
                        diagnostics.optBoolean(
                            "live_agent_core_recovery_applied",
                            false
                        )
                    )
                    .put("non_pass_checks", nonPass)
                    .put("canonical_report", canonicalReport.take(5000))
                    .put(
                        "screen_stabilization_attempted",
                        diagnostics.optBoolean(
                            "screen_stabilization_attempted",
                            false
                        )
                    )
                    .put(
                        "screen_stabilization_applied",
                        diagnostics.optBoolean(
                            "screen_stabilization_applied",
                            false
                        )
                    )
                    .put(
                        "screen_stabilization_initial_state",
                        diagnostics.optString(
                            "screen_stabilization_initial_state",
                            ""
                        )
                    )
                    .put(
                        "screen_stabilization_final_state",
                        diagnostics.optString(
                            "screen_stabilization_final_state",
                            ""
                        )
                    )
        )
    }

    private fun acceptanceRuntimeCapabilitiesProbe(): JSONObject {
        val snapshot =
            capabilityRegistry.snapshot()

        val runtime =
            snapshot.optJSONObject("runtime")
                ?: JSONObject()

        val ok =
            snapshot.optBoolean("success", false) &&
                snapshot.optString("build").isNotBlank() &&
                runtime.optInt("launchable_app_count", -1) >= 0

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Capability Registry доступен; build=${snapshot.optString("build")}, приложений=${runtime.optInt("launchable_app_count", -1)}."
                } else {
                    "Capability Registry не вернул полный runtime snapshot."
                },
            evidenceScope = "live_runtime",
            verified = ok,
            evidence =
                JSONObject()
                    .put("build", snapshot.optString("build"))
                    .put("launchable_app_count", runtime.optInt("launchable_app_count", -1))
                    .put("voice_service_running", runtime.optBoolean("voice_service_running", false))
                    .put("accessibility_connected", runtime.optBoolean("accessibility_connected", false))
        )
    }

    private fun acceptanceScreenPerceptionProbe(): JSONObject {
        val screen =
            screenIntelligence.getScreenState()

        if (!screen.optBoolean("success", false)) {
            return acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_FAIL,
                message = screen.optString("message").ifBlank { "Accessibility snapshot не получен." },
                evidenceScope = "live_accessibility",
                verified = false,
                evidence =
                    JSONObject()
                        .put("reason", screen.optString("reason"))
            )
        }

        val state =
            screen.optString("primary_content_state", "unknown")

        val status =
            when (state) {
                "readable" -> AyanaAcceptanceTestEngine.STATUS_PASS
                "partial", "structure_only" -> AyanaAcceptanceTestEngine.STATUS_WARNING
                "unavailable", "unknown" -> AyanaAcceptanceTestEngine.STATUS_NO_DATA
                else -> AyanaAcceptanceTestEngine.STATUS_WARNING
            }

        val effectivePackage =
            screen.optString(
                "effective_foreground_package",
                screen.optString("interaction_package", screen.optString("package"))
            )

        try {
            capabilityRegistry.recordScreenObservation(screen)
        } catch (_: Exception) {
        }

        return acceptanceProbeResult(
            status = status,
            message =
                "Экран: package=${effectivePackage.ifBlank { "не определён" }}, content=$state.",
            evidenceScope = "live_accessibility",
            verified = state == "readable" || state == "partial",
            evidence =
                JSONObject()
                    .put("effective_foreground_package", effectivePackage)
                    .put("raw_interaction_package", screen.optString("raw_interaction_package"))
                    .put("content_state", state)
                    .put("perception_fusion_version", screen.optInt("perception_fusion_version", 0))
                    .put("window_context_mode", screen.optString("window_context_mode"))
                    .put("input_method_visible", screen.optBoolean("input_method_visible", false))
                    .put("input_method_package", screen.optString("input_method_package"))
                    .put("input_method_context_count", screen.optInt("input_method_context_count", 0))
                    .put("primary_acquisition_source", screen.optString("primary_acquisition_source"))
                    .put("snapshot_duration_ms", screen.optLong("snapshot_duration_ms", -1L))
        )
    }

    private fun acceptanceAgentCoreLatencyProbe(): JSONObject {
        val latency =
            capabilityRegistry.agentCoreLatencySnapshot()

        val registryClassification =
            latency.optString(
                "classification",
                "NO_DATA"
            )

        val split =
            diagnosticClosure
                .classifyLatency(
                    latency
                )

        val effectiveClassification =
            if (
                registryClassification ==
                "NO_DATA"
            ) {
                "NO_DATA"
            } else {
                split.optString(
                    "classification",
                    registryClassification
                )
            }

        val status =
            when (effectiveClassification) {
                "NO_DATA" ->
                    AyanaAcceptanceTestEngine.STATUS_NO_DATA

                "MODEL_OR_SERVER_WAIT" ->
                    AyanaAcceptanceTestEngine.STATUS_PASS

                "ANDROID_OR_TRANSPORT_LOCAL",
                "MIXED",
                "ANDROID_PREPARE_SLOW",
                "UPLOAD_SLOW",
                "RESPONSE_BODY_SLOW",
                "ANDROID_PARSE_SLOW",
                "HIGH_LATENCY_UNCLASSIFIED",
                "CLIENT_PROCESSING_SLOW" ->
                    AyanaAcceptanceTestEngine.STATUS_WARNING

                else ->
                    AyanaAcceptanceTestEngine.STATUS_PASS
            }

        val externalWaitOnly =
            effectiveClassification ==
                "MODEL_OR_SERVER_WAIT"

        val evidence =
            JSONObject(
                latency.toString()
            )
                .put(
                    "registry_classification",
                    registryClassification
                )
                .put(
                    "r9_effective_classification",
                    effectiveClassification
                )
                .put(
                    "local_android_transport_ms",
                    split.optLong(
                        "local_android_transport_ms",
                        -1L
                    )
                )
                .put(
                    "model_server_wait_ms",
                    split.optLong(
                        "model_server_wait_ms",
                        -1L
                    )
                )
                .put(
                    "remote_share_pct",
                    split.optLong(
                        "remote_share_pct",
                        -1L
                    )
                )
                .put("external_wait_only", externalWaitOnly)
                .put(
                    "current_local_health_warning",
                    status == AyanaAcceptanceTestEngine.STATUS_WARNING
                )
                .put(
                    "diagnostic_closure_version",
                    AyanaDiagnosticClosure.VERSION
                )

        return acceptanceProbeResult(
            status = status,
            message =
                if (externalWaitOnly) {
                    "Agent Core telemetry R9.1: внешний model/server wait=${split.optLong("model_server_wait_ms", -1L)} мс; " +
                        "локальный Android/transport=${split.optLong("local_android_transport_ms", -1L)} мс. " +
                        "Измерение сохранено как performance evidence и не считается локальным дефектом AYANA."
                } else {
                    "Agent Core telemetry R9.1: class=$effectiveClassification, " +
                        "total=${latency.optLong("total_ms", -1L)} мс, " +
                        "local=${split.optLong("local_android_transport_ms", -1L)} мс, " +
                        "model/server=${split.optLong("model_server_wait_ms", -1L)} мс."
                },
            evidenceScope =
                if (externalWaitOnly) {
                    "stored_measured_telemetry_external_wait_informational"
                } else {
                    "stored_measured_telemetry_r9_attribution"
                },
            verified = effectiveClassification != "NO_DATA",
            evidence = evidence
        )
    }

    private fun acceptanceNotificationAccessProbe(): JSONObject {
        val runtime =
            capabilityRegistry.snapshot()
                .optJSONObject("runtime")
                ?: JSONObject()

        val access =
            runtime.optBoolean("notification_listener_access", false)

        val connected =
            runtime.optBoolean("notification_listener_connected", false)

        val status =
            when {
                access && connected -> AyanaAcceptanceTestEngine.STATUS_PASS
                access -> AyanaAcceptanceTestEngine.STATUS_WARNING
                else -> AyanaAcceptanceTestEngine.STATUS_BLOCKED
            }

        return acceptanceProbeResult(
            status = status,
            message =
                when {
                    access && connected -> "NotificationListener имеет доступ и подключён."
                    access -> "Доступ к уведомлениям выдан, но listener сейчас не подтверждён как подключённый."
                    else -> "Доступ NotificationListener не выдан."
                },
            evidenceScope = "live_runtime",
            verified = access && connected,
            evidence =
                JSONObject()
                    .put("access", access)
                    .put("connected", connected)
        )
    }

    private fun acceptanceCapabilityRegistryIntegrityProbe(): JSONObject {
        val snapshot = capabilityRegistry.snapshot()
        val capabilities = snapshot.optJSONArray("capabilities") ?: JSONArray()
        val required =
            listOf(
                "strict_terminal_verification",
                "durable_goals",
                "memory_v2",
                "tasks_reminders_v2",
                "artifact_generation",
                "docx_translation",
                "image_vision_analysis",
                "capability_truth_grounding",
                "perception_owner_fusion",
                "autonomous_execution_loop",
                "whole_goal_routing_guard",
                "artifact_whole_goal_orchestration",
                "agent_core_timeout_recovery",
                "local_acceptance_test_engine"
            )

        val present =
            linkedSetOf<String>()

        var contradictions = 0

        for (index in 0 until capabilities.length()) {
            val item = capabilities.optJSONObject(index) ?: continue
            val id = item.optString("id")
            if (id.isNotBlank()) {
                present += id
            }

            val implemented = item.optBoolean("implemented", false)
            val available = item.optBoolean("available_now", false)
            val confirmed = item.optBoolean("device_confirmed", false)

            if ((!implemented && available) || (!implemented && confirmed)) {
                contradictions++
            }
        }

        val missing = required.filterNot(present::contains)
        val ok = missing.isEmpty() && contradictions == 0

        return acceptanceProbeResult(
            status = if (ok) AyanaAcceptanceTestEngine.STATUS_PASS else AyanaAcceptanceTestEngine.STATUS_FAIL,
            message =
                if (ok) {
                    "Capability Registry непротиворечив; обязательные capability-id присутствуют."
                } else {
                    "Capability Registry: отсутствуют ${missing.joinToString(", ").ifBlank { "нет" }}; противоречий=$contradictions."
                },
            evidenceScope = "build_runtime_truth",
            verified = ok,
            evidence =
                JSONObject()
                    .put("capability_count", capabilities.length())
                    .put("missing", JSONArray(missing))
                    .put("contradictions", contradictions)
        )
    }

    private fun acceptanceAutonomyFoundationProbe(): JSONObject {
        val snapshot =
            capabilityRegistry.snapshot()

        val ids =
            listOf(
                "strict_terminal_verification",
                "durable_goals",
                "goal_compiler_execution_contract",
                "unified_execution_session",
                "autonomous_execution_loop"
            )

        val missing =
            mutableListOf<String>()

        val unavailable =
            mutableListOf<String>()

        ids.forEach { id ->
            val item =
                acceptanceCapability(
                    snapshot,
                    id
                )

            if (
                item == null ||
                !item.optBoolean(
                    "implemented",
                    false
                )
            ) {
                missing += id
            } else if (
                !item.optBoolean(
                    "available_now",
                    false
                )
            ) {
                unavailable += id
            }
        }

        val runtimeConfirmed =
            linkedSetOf<String>()

        val runtimeFailures =
            linkedMapOf<String, String>()

        val runtimeEvidence =
            JSONObject()

        // -----------------------------------------------------
        // 1) Goal Compiler execution contract — pure/read-only.
        // -----------------------------------------------------
        try {
            val compiled =
                androidGoalCompiler.compile(
                    JSONObject()
                        .put(
                            "type",
                            "open_app"
                        )
                        .put(
                            "app",
                            "AYANA AI"
                        )
                        .put(
                            "max_actions",
                            2
                        )
                )

            val contract =
                compiled.optJSONObject(
                    "execution_contract"
                )
                    ?: JSONObject()

            val plan =
                compiled.optJSONObject(
                    "plan"
                )
                    ?: JSONObject()

            val steps =
                plan.optJSONArray(
                    "steps"
                )
                    ?: JSONArray()

            val firstStep =
                steps.optJSONObject(
                    0
                )
                    ?: JSONObject()

            val blockedMutation =
                androidGoalCompiler.compile(
                    JSONObject()
                        .put(
                            "type",
                            "open_app"
                        )
                        .put(
                            "app",
                            "AYANA AI"
                        )
                        .put(
                            "change_state",
                            true
                        )
                )

            // Do not bind runtime truth to an exact compiler-version string.
            // The device currently runs Goal Compiler v2.1 while the original
            // probe was written against v2.0. Capability truth is defined by
            // the observable execution contract, not by a stale version literal.
            val compiledSuccess =
                compiled.optBoolean(
                    "success",
                    false
                )

            val goalTypeOk =
                compiled.optString(
                    "goal_type"
                ) == "open_app"

            val executorOk =
                contract.optString(
                    "executor_key"
                ) == "app_launch_executor"

            val terminalPolicyOk =
                contract.optString(
                    "terminal_policy"
                ) == "verified_terminal_only"

            val verificationPolicyOk =
                contract.optString(
                    "verification_policy"
                ) == "fresh_foreground_package"

            val cancellationRequired =
                contract.optBoolean(
                    "cancellation_required",
                    false
                )

            val replanPolicyOk =
                contract.optString(
                    "replan_policy"
                ) == "bounded_safe_replan"

            val falseSuccessGuardOk =
                !contract.optBoolean(
                    "false_success_allowed",
                    true
                )

            val actionBudgetOk =
                plan.optInt(
                    "max_actions",
                    -1
                ) in 1..2

            val terminalStepOk =
                steps.length() == 1 &&
                    firstStep.optString(
                        "action"
                    ) == "open_app" &&
                    firstStep.optBoolean(
                        "terminal",
                        false
                    )

            val mutationGuardOk =
                !blockedMutation.optBoolean(
                    "success",
                    true
                ) &&
                    blockedMutation.optString(
                        "terminal_status"
                    ) == "BLOCKED"

            val failedChecks =
                mutableListOf<String>()

            if (!compiledSuccess) {
                failedChecks += "compiled_success"
            }
            if (!goalTypeOk) {
                failedChecks += "goal_type"
            }
            if (!executorOk) {
                failedChecks += "executor_key"
            }
            if (!terminalPolicyOk) {
                failedChecks += "terminal_policy"
            }
            if (!verificationPolicyOk) {
                failedChecks += "verification_policy"
            }
            if (!cancellationRequired) {
                failedChecks += "cancellation_required"
            }
            if (!replanPolicyOk) {
                failedChecks += "replan_policy"
            }
            if (!falseSuccessGuardOk) {
                failedChecks += "false_success_guard"
            }
            if (!actionBudgetOk) {
                failedChecks += "action_budget"
            }
            if (!terminalStepOk) {
                failedChecks += "terminal_step"
            }
            if (!mutationGuardOk) {
                failedChecks += "mutation_guard"
            }

            val compilerOk =
                failedChecks.isEmpty()

            runtimeEvidence.put(
                "goal_compiler_execution_contract",
                JSONObject()
                    .put(
                        "ok",
                        compilerOk
                    )
                    .put(
                        "compiler_version",
                        compiled.optString(
                            "compiler_version"
                        )
                    )
                    .put(
                        "compiled_success",
                        compiledSuccess
                    )
                    .put(
                        "goal_type_ok",
                        goalTypeOk
                    )
                    .put(
                        "executor_key",
                        contract.optString(
                            "executor_key"
                        )
                    )
                    .put(
                        "executor_key_ok",
                        executorOk
                    )
                    .put(
                        "terminal_policy",
                        contract.optString(
                            "terminal_policy"
                        )
                    )
                    .put(
                        "terminal_policy_ok",
                        terminalPolicyOk
                    )
                    .put(
                        "verification_policy",
                        contract.optString(
                            "verification_policy"
                        )
                    )
                    .put(
                        "verification_policy_ok",
                        verificationPolicyOk
                    )
                    .put(
                        "cancellation_required",
                        cancellationRequired
                    )
                    .put(
                        "replan_policy",
                        contract.optString(
                            "replan_policy"
                        )
                    )
                    .put(
                        "replan_policy_ok",
                        replanPolicyOk
                    )
                    .put(
                        "false_success_allowed",
                        contract.optBoolean(
                            "false_success_allowed",
                            true
                        )
                    )
                    .put(
                        "false_success_guard_ok",
                        falseSuccessGuardOk
                    )
                    .put(
                        "max_actions",
plan.optInt(
                            "max_actions",
                            -1
                        )
                    )
                    .put(
                        "action_budget_ok",
                        actionBudgetOk
                    )
                    .put(
                        "step_count",
                        steps.length()
                    )
                    .put(
                        "terminal_step_ok",
                        terminalStepOk
                    )
                    .put(
                        "mutation_guard_terminal",
                        blockedMutation.optString(
                            "terminal_status"
                        )
                    )
                    .put(
                        "mutation_guard_ok",
                        mutationGuardOk
                    )
                    .put(
                        "failed_checks",
                        JSONArray(
                            failedChecks
                        )
                    )
            )

            if (compilerOk) {
                runtimeConfirmed +=
                    "goal_compiler_execution_contract"
            } else {
                runtimeFailures[
                    "goal_compiler_execution_contract"
                ] =
                    "execution_contract_probe_failed:" +
                        failedChecks.joinToString(
                            ","
                        )
            }
        } catch (
            error: Exception
        ) {
            runtimeFailures[
                "goal_compiler_execution_contract"
            ] =
                "exception:${error.javaClass.simpleName}"

            runtimeEvidence.put(
                "goal_compiler_execution_contract",
                JSONObject()
                    .put(
                        "ok",
                        false
                    )
                    .put(
                        "error",
                        error.javaClass.simpleName
                    )
                    .put(
                        "message",
                        error.message
                            .orEmpty()
                            .take(
                                300
                            )
                    )
            )
        }

        // -----------------------------------------------------
        // 2) Unified Execution Session — live production session
        //    + isolated kernel lifecycle, no active-session mutation.
        // -----------------------------------------------------
        try {
            val live =
                executionKernel.current()

            val liveOk =
                live != null &&
                    live.terminalStatus ==
                    AyanaExecutionKernel.TerminalStatus.RUNNING &&
                    live.id.isNotBlank() &&
                    live.lane.isNotBlank() &&
                    live.executor.isNotBlank()

            val isolatedKernel =
                AyanaExecutionKernel()

            val begin =
                isolatedKernel.begin(
                    objective =
                        "AYANA acceptance execution-session probe",
                    source =
                        "acceptance",
                    lane =
                        "runtime_probe",
                    executor =
                        "probe_executor"
                )

            isolatedKernel.setPhase(
                "probe_phase"
            )

            isolatedKernel.setExecutor(
                "probe_executor_verified"
            )

            isolatedKernel.addEvidence(
                type =
                    "probe_evidence",
                source =
                    "acceptance",
                detail =
                    "unified_execution_session",
                confidence =
                    100
            )

            val middle =
                isolatedKernel.current()

            val completed =
                isolatedKernel.complete(
                    status =
                        AyanaExecutionKernel.TerminalStatus.SUCCESS,
                    reason =
                        "probe_complete"
                )

            isolatedKernel.begin(
                objective =
                    "AYANA acceptance cancellation probe",
                source =
                    "acceptance",
                lane =
                    "runtime_probe_cancel",
                executor =
                    "probe_executor"
            )

            val cancelled =
                isolatedKernel.cancel(
                    "probe_cancel"
                )

            val isolatedOk =
                begin.terminalStatus ==
                    AyanaExecutionKernel.TerminalStatus.RUNNING &&
                    middle != null &&
                    middle.phase ==
                    "probe_phase" &&
                    middle.executor ==
                    "probe_executor_verified" &&
                    middle.evidence.any {
                        it.type ==
                            "probe_evidence"
                    } &&
                    completed != null &&
                    completed.terminalStatus ==
                    AyanaExecutionKernel.TerminalStatus.SUCCESS &&
                    completed.reason ==
                    "probe_complete" &&
                    cancelled != null &&
                    cancelled.terminalStatus ==
                    AyanaExecutionKernel.TerminalStatus.CANCELLED &&
                    cancelled.cancelled &&
                    cancelled.reason ==
                    "probe_cancel"

            val sessionOk =
                liveOk &&
                    isolatedOk

            runtimeEvidence.put(
                "unified_execution_session",
                JSONObject()
                    .put(
                        "ok",
                        sessionOk
                    )
                    .put(
                        "live_session_present",
                        live != null
                    )
                    .put(
                        "live_id",
                        live?.id.orEmpty()
                    )
                    .put(
                        "live_lane",
                        live?.lane.orEmpty()
                    )
                    .put(
                        "live_executor",
                        live?.executor.orEmpty()
                    )
                    .put(
                        "live_phase",
                        live?.phase.orEmpty()
                    )
                    .put(
                        "live_terminal",
                        live?.terminalStatus
                            ?.name
                            .orEmpty()
                    )
                    .put(
                        "isolated_terminal",
                        completed?.terminalStatus
                            ?.name
                            .orEmpty()
                    )
                    .put(
                        "isolated_cancel_terminal",
                        cancelled?.terminalStatus
                            ?.name
                            .orEmpty()
                    )
                    .put(
                        "isolated_cancelled",
                        cancelled?.cancelled
                            ?: false
                    )
            )

            if (sessionOk) {
                runtimeConfirmed +=
                    "unified_execution_session"
            } else {
                runtimeFailures[
                    "unified_execution_session"
                ] =
                    "execution_session_probe_failed"
            }
        } catch (
            error: Exception
        ) {
            runtimeFailures[
                "unified_execution_session"
            ] =
                "exception:${error.javaClass.simpleName}"

            runtimeEvidence.put(
                "unified_execution_session",
                JSONObject()
                    .put(
                        "ok",
                        false
                    )
                    .put(
                        "error",
                        error.javaClass.simpleName
                    )
                    .put(
                        "message",
                        error.message
                            .orEmpty()
                            .take(
                                300
                            )
                    )
            )
        }

        // -----------------------------------------------------
        // 3) Autonomous execution loop — safe integrated contract
        //    probe: Planner -> Resolver -> Compiler -> live Kernel
        //    -> Durable Goal readability -> Completion Contract.
        //    No UI action is dispatched.
        // -----------------------------------------------------
        try {
            val planner =
                agentPlannerV2.buildEnvelope(
                    "открой приложение AYANA AI"
                )

            val resolution =
                planner.optJSONObject(
                    "app_resolution"
                )
                    ?: JSONObject()

            val compiled =
                androidGoalCompiler.compile(
                    JSONObject()
                        .put(
                            "type",
                            "open_app"
                        )
                        .put(
                            "app",
                            "AYANA AI"
                        )
                )

            val executionContract =
                compiled.optJSONObject(
                    "execution_contract"
                )
                    ?: JSONObject()

            val durableReadable =
                try {
                    durableGoalStore
                        .getRecoverableJson(
                            20
                        )
                    true
                } catch (_: Exception) {
                    false
                }

            val completionGuard =
                completionContract.validateEvidence(
                    request =
                        "создай PDF файл acceptance_contract_test.pdf",
                    reply =
                        "Готово, файл создан.",
                    artifactEvidence =
                        emptyList<AyanaCompletionContract.ArtifactEvidence>()
                )

            val live =
                executionKernel.current()

            val loopOk =
                planner.optString(
                    "domain"
                ) == "android_action" &&
                    planner.optString(
                        "terminal_criterion"
                    ).isNotBlank() &&
                    resolution.optBoolean(
                        "success",
                        false
                    ) &&
                    resolution.optString(
                        "package"
                    ) ==
                    packageName &&
                    compiled.optBoolean(
                        "success",
                        false
                    ) &&
                    executionContract.optString(
                        "terminal_policy"
                    ) ==
                    "verified_terminal_only" &&
                    executionContract.optString(
                        "replan_policy"
                    ) ==
                    "bounded_safe_replan" &&
                    !executionContract.optBoolean(
                        "false_success_allowed",
                        true
                    ) &&
                    durableReadable &&
                    !completionGuard.satisfied &&
                    live != null &&
                    live.terminalStatus ==
                    AyanaExecutionKernel.TerminalStatus.RUNNING

            runtimeEvidence.put(
                "autonomous_execution_loop",
                JSONObject()
                    .put(
                        "ok",
                        loopOk
                    )
                    .put(
                        "planner_domain",
                        planner.optString(
                            "domain"
                        )
                    )
                    .put(
                        "planner_terminal_criterion",
                        planner.optString(
                            "terminal_criterion"
                        ).isNotBlank()
                    )
                    .put(
                        "resolved_package",
                        resolution.optString(
                            "package"
                        )
                    )
                    .put(
                        "compiler_success",
                        compiled.optBoolean(
                            "success",
                            false
                        )
                    )
                    .put(
                        "terminal_policy",
                        executionContract.optString(
                            "terminal_policy"
                        )
                    )
                    .put(
                        "replan_policy",
                        executionContract.optString(
                            "replan_policy"
                        )
                    )
                    .put(
                        "durable_store_readable",
                        durableReadable
                    )
                    .put(
                        "false_success_guard_rejected",
                        !completionGuard.satisfied
                    )
                    .put(
                        "live_execution_session",
                        live != null
                    )
            )

            if (loopOk) {
                runtimeConfirmed +=
                    "autonomous_execution_loop"
            } else {
                runtimeFailures[
                    "autonomous_execution_loop"
                ] =
                    "integrated_loop_probe_failed"
            }
        } catch (
            error: Exception
        ) {
            runtimeFailures[
                "autonomous_execution_loop"
            ] =
                "exception:${error.javaClass.simpleName}"

            runtimeEvidence.put(
                "autonomous_execution_loop",
                JSONObject()
                    .put(
                        "ok",
                        false
                    )
                    .put(
                        "error",
                        error.javaClass.simpleName
                    )
                    .put(
                        "message",
                        error.message
                            .orEmpty()
                            .take(
                                300
                            )
                    )
            )
        }

        val runtimeTargetIds =
            setOf(
                "goal_compiler_execution_contract",
                "unified_execution_session",
                "autonomous_execution_loop"
            )

        val runtimeUnconfirmed =
            runtimeTargetIds
                .filter {
                    it !in runtimeConfirmed
                }

        val registryUnconfirmed =
            ids.filter { id ->
                val item =
                    acceptanceCapability(
                        snapshot,
                        id
                    )

                item != null &&
                    item.optBoolean(
                        "implemented",
                        false
                    ) &&
                    item.optBoolean(
                        "available_now",
                        false
                    ) &&
                    !item.optBoolean(
                        "device_confirmed",
                        false
                    )
            }

        val effectiveUnconfirmed =
            registryUnconfirmed
                .filter {
                    it !in runtimeConfirmed
                }

        val status =
            when {
                missing.isNotEmpty() ||
                    unavailable.isNotEmpty() ||
                    runtimeFailures.isNotEmpty() ->
                    AyanaAcceptanceTestEngine.STATUS_FAIL

                effectiveUnconfirmed.isNotEmpty() ->
                    AyanaAcceptanceTestEngine.STATUS_WARNING

                else ->
                    AyanaAcceptanceTestEngine.STATUS_PASS
            }

        return acceptanceProbeResult(
            status =
                status,
            message =
                when (status) {
                    AyanaAcceptanceTestEngine.STATUS_PASS ->
                        "Автономная база подтверждена runtime-probe: Goal Compiler execution contract, unified Execution Session и autonomous execution loop прошли безопасную интеграционную проверку."

                    AyanaAcceptanceTestEngine.STATUS_WARNING ->
                        "Автономная база доступна; свежие runtime-probe подтверждены частично. Остались неподтверждённые слои: ${effectiveUnconfirmed.joinToString(", ")}."

                    else ->
                        "Автономная база не прошла runtime-проверку: missing=${missing.joinToString(",")}; unavailable=${unavailable.joinToString(",")}; runtime_failed=${runtimeFailures.keys.joinToString(",")}."
                },
            evidenceScope =
                "live_runtime_contract",
            verified =
                status ==
                    AyanaAcceptanceTestEngine.STATUS_PASS,
            evidence =
                JSONObject()
                    .put(
                        "missing",
                        JSONArray(
                            missing
                        )
                    )
                    .put(
                        "unavailable",
                        JSONArray(
                            unavailable
                        )
                    )
                    .put(
                        "registry_unconfirmed",
                        JSONArray(
                            registryUnconfirmed
                        )
                    )
                    .put(
                        "runtime_unconfirmed",
                        JSONArray(
                            runtimeUnconfirmed
                        )
                    )
                    .put(
                        "runtime_confirmed_capabilities",
                        JSONArray(
                            runtimeConfirmed.toList()
                        )
                    )
                    .put(
                        "runtime_failures",
                        JSONObject(
                            runtimeFailures
                        )
                    )
                    .put(
                        "runtime_probe_evidence",
                        runtimeEvidence
                    )
        )
    }

    private fun acceptancePerceptionTruthProbe(): JSONObject {
        val snapshot = capabilityRegistry.snapshot()
        val fusion = acceptanceCapability(snapshot, "perception_owner_fusion")
        val runtime = snapshot.optJSONObject("runtime") ?: JSONObject()
        val state = runtime.optString("screen_primary_content_state", "unknown")

        val fusionReady =
            fusion?.optBoolean("implemented", false) == true &&
                fusion.optBoolean("available_now", false)

        val status =
            when {
                !fusionReady -> AyanaAcceptanceTestEngine.STATUS_FAIL
                state == "readable" -> AyanaAcceptanceTestEngine.STATUS_PASS
                state == "partial" || state == "structure_only" -> AyanaAcceptanceTestEngine.STATUS_WARNING
                else -> AyanaAcceptanceTestEngine.STATUS_NO_DATA
            }

        return acceptanceProbeResult(
            status = status,
            message = "Perception owner-fusion=${fusionReady}; current_content=$state.",
            evidenceScope = "build_plus_live_runtime",
            verified = fusionReady,
            evidence =
                JSONObject()
                    .put("fusion_ready", fusionReady)
                    .put("content_state", state)
                    .put("current_package", runtime.optString("screen_primary_package"))
        )
    }

    private fun acceptanceArtifactDocumentTruthProbe(): JSONObject {
        val snapshot = capabilityRegistry.snapshot()
        val ids =
            listOf(
                "artifact_generation",
                "docx_style_preserving_transform",
                "docx_translation"
            )

        val notConfirmed =
            ids.filter { id ->
                val item = acceptanceCapability(snapshot, id)
                item == null ||
                    !item.optBoolean("implemented", false) ||
                    !item.optBoolean("available_now", false) ||
                    !item.optBoolean("device_confirmed", false)
            }

        val ok = notConfirmed.isEmpty()

        return acceptanceProbeResult(
            status = if (ok) AyanaAcceptanceTestEngine.STATUS_PASS else AyanaAcceptanceTestEngine.STATUS_WARNING,
            message =
                if (ok) {
                    "TXT/DOCX/PDF/XLSX/JPEG/graph и DOCX translation имеют device-confirmed evidence."
                } else {
                    "Не все File/Document capability подтверждены на устройстве: ${notConfirmed.joinToString(", ")}."
                },
            evidenceScope = "device_confirmed_registry",
            verified = ok,
            evidence = JSONObject().put("not_confirmed", JSONArray(notConfirmed))
        )
    }

    private fun acceptanceMultimodalTruthProbe(): JSONObject {
        val snapshot = capabilityRegistry.snapshot()
        val positive =
            listOf(
                "image_upload_to_ayana",
                "video_upload_to_ayana",
                "image_vision_analysis",
                "video_analysis",
                "document_understanding"
            )

        val badPositive =
            positive.filter { id ->
                val item = acceptanceCapability(snapshot, id)
                item == null ||
                    !item.optBoolean("implemented", false) ||
                    !item.optBoolean("available_now", false) ||
                    !item.optBoolean("device_confirmed", false)
            }

        val videoAudio = acceptanceCapability(snapshot, "video_audio_analysis")
        val negativeTruthOk =
            videoAudio != null &&
                !videoAudio.optBoolean("implemented", true) &&
                !videoAudio.optBoolean("available_now", true)

        val ok = badPositive.isEmpty() && negativeTruthOk

        return acceptanceProbeResult(
            status = if (ok) AyanaAcceptanceTestEngine.STATUS_PASS else AyanaAcceptanceTestEngine.STATUS_FAIL,
            message =
                if (ok) {
                    "Multimodal truth корректна: image/document/sample-frame video подтверждены; video audio честно недоступен."
                } else {
                    "Multimodal capability truth противоречива или неполна."
                },
            evidenceScope = "device_confirmed_registry",
            verified = ok,
            evidence =
                JSONObject()
                    .put("positive_not_confirmed", JSONArray(badPositive))
                    .put("video_audio_negative_truth_ok", negativeTruthOk)
        )
    }

    private fun acceptanceDevelopmentTruthProbe(): JSONObject {
        val snapshot = capabilityRegistry.snapshot()
        val ids =
            listOf(
                "development_agent_transaction",
                "github_repository_write",
                "github_commit_push",
                "android_apk_build",
                "direct_apk_delivery"
            )

        val wronglyAdvertised =
            ids.filter { id ->
                val item = acceptanceCapability(snapshot, id)
                item == null ||
                    item.optBoolean("implemented", true) ||
                    item.optBoolean("available_now", true)
            }

        val ok = wronglyAdvertised.isEmpty()

        return acceptanceProbeResult(
            status = if (ok) AyanaAcceptanceTestEngine.STATUS_PASS else AyanaAcceptanceTestEngine.STATUS_FAIL,
            message =
                if (ok) {
                    "Development/GitHub/APK ограничения представлены честно: неподтверждённые внешние действия не рекламируются как доступные."
                } else {
                    "Capability truth ошибочно рекламирует development-возможности: ${wronglyAdvertised.joinToString(", ")}."
                },
            evidenceScope = "negative_capability_truth",
            verified = ok,
            evidence = JSONObject().put("wrongly_advertised", JSONArray(wronglyAdvertised))
        )
    }

    private fun acceptanceExternalIntegrationTruthProbe(): JSONObject {
        val snapshot = capabilityRegistry.snapshot()
        val ids =
            listOf(
                "external_account_actions",
                "external_mail_calendar_files",
                "controlled_proactivity"
            )

        val wronglyAdvertised =
            ids.filter { id ->
                val item = acceptanceCapability(snapshot, id)
                item == null ||
                    item.optBoolean("implemented", true) ||
                    item.optBoolean("available_now", true)
            }

        val ok = wronglyAdvertised.isEmpty()

        return acceptanceProbeResult(
            status = if (ok) AyanaAcceptanceTestEngine.STATUS_PASS else AyanaAcceptanceTestEngine.STATUS_FAIL,
            message =
                if (ok) {
                    "Внешние account/mail/calendar/files действия не объявляются доступными без специализированных executors."
                } else {
                    "External integration truth содержит ложноположительные capability."
                },
            evidenceScope = "negative_capability_truth",
            verified = ok,
            evidence = JSONObject().put("wrongly_advertised", JSONArray(wronglyAdvertised))
        )
    }

    private fun acceptanceAppResolverProbe(): JSONObject {
        val apps =
            appResolver.listLaunchableApps(
                forceRefresh = true
            )

        if (apps.isEmpty()) {
            return acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_FAIL,
                message = "App Resolver не получил запускаемые приложения.",
                evidenceScope = "live_device",
                verified = false
            )
        }

        val candidate =
            apps.firstOrNull {
                it.packageName != packageName &&
                    it.label.isNotBlank()
            } ?: apps.first()

        val resolved =
            appResolver.resolve(
                candidate.label,
                forceRefresh = false
            )

        val ok =
            resolved.success &&
                resolved.packageName == candidate.packageName

        return acceptanceProbeResult(
            status = if (ok) AyanaAcceptanceTestEngine.STATUS_PASS else AyanaAcceptanceTestEngine.STATUS_FAIL,
            message =
                if (ok) {
                    "App Resolver: ${apps.size} приложений; round-trip «${candidate.label}» → ${resolved.packageName} подтверждён."
                } else {
                    "App Resolver list/resolve round-trip не совпал для «${candidate.label}»."
                },
            evidenceScope = "live_device",
            verified = ok,
            evidence =
                JSONObject()
                    .put("app_count", apps.size)
                    .put("label", candidate.label)
                    .put("expected_package", candidate.packageName)
                    .put("resolved_package", resolved.packageName)
                    .put("confidence", resolved.confidence)
        )
    }

    private fun acceptancePlannerProbe(): JSONObject {
        val objective =
            "Открой настройки батареи, затем вернись в AYANA"

        val envelope =
