    private fun acceptanceWholeGoalRoutingProbe(): JSONObject {
        val lifecycle =
            extractVerifiedAppOpenRequest(
                "открой приложение Камера и проверь, что на переднем плане именно камера"
            )

        val appDetail =
            extractCompositeAppDetailFinalGoal(
                "открой настройки приложений, найди YouTube и зайди в разрешения"
            )

        val metrics =
            extractRequestedAggregateMetrics(
                "проверь состояние устройства по трём параметрам: заряд батареи, подключение к интернету и свободное место в хранилище, затем дай один общий результат"
            )

        val volumeTarget =
            extractExactMediaVolumeRequest(
                "уменьшить громкость до 2"
            )

        val clipboardRoutePrefix =
            extractLocalClipboardCopyRequest(
                "скопируй в буфер обмена текст AYANA-R78-CLIPBOARD-001"
            )

        val clipboardRouteSuffix =
            extractLocalClipboardCopyRequest(
                "запиши текст AYANA-R78-CLIPBOARD-002 в буфер обмена"
            )

        val lifecycleSemanticObjectRejected =
            extractLocalAppLifecycleRequest(
                "включи несуществующую функцию AYANA TEST-R78-UNAVAILABLE-001"
            ) == null

        val refusalFailClosed =
            shouldFailClosedAgentFinalWithoutMachineTerminal(
                originalCommand =
                    "скопируй в буфер обмена текст AYANA-R78-CLIPBOARD-001",
                reply =
                    "Не могу напрямую скопировать текст в буфер обмена: инструмент работы с буфером сейчас недоступен."
            )

        val unsupportedDevelopmentAction =
            unsupportedExecutionCapabilityReason(
                "измени код AYANA в GitHub, сделай commit, запусти сборку APK и дай мне готовый APK"
            )

        val informationalDevelopmentQuestion =
            unsupportedExecutionCapabilityReason(
                "почему AYANA пока не может собрать APK"
            )

        val artifactCommand =
            "проверь свободное место в хранилище и создай TXT-файл с этим результатом"

        val artifact =
            requestsArtifactDeliverable(
                artifactCommand
            )

        val validCodeArtifactContract =
            validateCreateArtifactContentContract(
                request = "создай TXT-файл с готовым Kotlin кодом",
                arguments =
                    JSONObject()
                        .put("kind", "txt")
                        .put("filename", "sample.kt.txt")
                        .put(
                            "content",
                            """
                            package kg.autonomous.agent

                            import android.content.Context

                            class Sample(
                                private val context: Context
                            ) {
                                fun value(): Int {
                                    return 1
                                }
                            }
                            """.trimIndent()
                        )
            )

        val invalidCodeArtifactContract =
            validateCreateArtifactContentContract(
                request = "создай TXT-файл с готовым кодом",
                arguments =
                    JSONObject()
                        .put("kind", "txt")
                        .put("filename", "fake_code.txt")
                        .put(
                            "content",
                            "Готовый автономный код визуализации AYANA. Сохраните содержимое как HTML-файл. Визуализация включает несколько состояний. Переключение выполняется функцией setState(). Код не требует внешних библиотек."
                        )
            )

        val artifactSemanticContentOk =
            validCodeArtifactContract.optBoolean("allowed", false) &&
                !invalidCodeArtifactContract.optBoolean("allowed", true)

        val artifactFollowUpContractOk =
            strengthenArtifactFollowUpMessage(
                message = "создай файл txt с готовым кодом",
                hasPreviousResponseContext = true
            )
                ?.contains("actual requested payload", ignoreCase = true) == true

        val artifactMetricsSuppressed =
            extractRequestedAggregateMetrics(
                artifactCommand
            ).isEmpty()

        val mixedSideEffectMetricsSuppressed =
            extractRequestedAggregateMetrics(
                "проверь батарею и интернет и открой Chrome"
            ).isEmpty()

        val pureMetricGoalTerminalLocal =
            !aggregateMetricHasRemainingSemanticGoal(
                "проверь состояние устройства по трём параметрам: заряд батареи, подключение к интернету и свободное место в хранилище, затем дай один общий результат"
            )

        val analyticalMetricGoalRequiresHandoff =
            aggregateMetricHasRemainingSemanticGoal(
                "проверь заряд батареи, подключение к интернету и свободное место в хранилище; определи, есть ли сейчас проблема, требующая моего вмешательства, и объясни одним итогом"
            )

        val conditionalMetricGoalRequiresHandoff =
            aggregateMetricHasRemainingSemanticGoal(
                "проверь заряд батареи и свободное место; если хотя бы один показатель требует внимания, скажи какой именно, иначе скажи что всё нормально"
            )

        val personalSearchBroad =
            AyanaPersonalSearchEngine
                .parseRequest(
                    "найди всё про YouTube"
                )

        val personalSearchScoped =
            AyanaPersonalSearchEngine
                .parseRequest(
                    "поищи в памяти и истории про кредит"
                )

        val externalGoogleSearchRejected =
            AyanaPersonalSearchEngine
                .parseRequest(
                    "найди в Google новости AYANA"
                ) == null

        val existingNotificationReadRejected =
            AyanaPersonalSearchEngine
                .parseRequest(
                    "покажи последние уведомления"
                ) == null

        val documentContentSearchScoped =
            AyanaPersonalSearchEngine
                .parseRequest(
                    "найди в документах Озгур"
                )

        val existingReminderListRejected =
            AyanaPersonalSearchEngine
                .parseRequest(
                    "покажи мои задачи"
                ) == null

        val personalSearchRoutingOk =
            personalSearchBroad != null &&
                personalSearchBroad.query.equals(
                    "YouTube",
                    ignoreCase = true
                ) &&
                personalSearchBroad.sources.size ==
                    AyanaPersonalSearchEngine.Source.values().size &&
                personalSearchScoped != null &&
                personalSearchScoped.query.equals(
                    "кредит",
                    ignoreCase = true
                ) &&
                personalSearchScoped.sources ==
                    setOf(
                        AyanaPersonalSearchEngine.Source.MEMORY,
                        AyanaPersonalSearchEngine.Source.HISTORY
                    ) &&
                externalGoogleSearchRejected &&
                existingNotificationReadRejected &&
                documentContentSearchScoped != null &&
                documentContentSearchScoped.query.equals(
                    "озгур",
                    ignoreCase = true
                ) &&
                documentContentSearchScoped.sources ==
                    setOf(
                        AyanaPersonalSearchEngine.Source.FILES
                    ) &&
                existingReminderListRejected

        val lifecycleOk =
            lifecycle != null &&
                lifecycle.first.contains("камера") &&
                lifecycle.second?.contains("камера") == true

        val appDetailOk =
            appDetail != null &&
                appDetail.section == "permissions" &&
                appDetail.appName.contains("youtube")

        val metricsOk =
            AggregateMetric.BATTERY in metrics &&
                AggregateMetric.NETWORK in metrics &&
                AggregateMetric.STORAGE in metrics &&
                metrics.size == 3

        val volumeTargetOk =
            volumeTarget?.requestedLevel == 2 &&
                volumeTarget.requestedScaleMax == null &&
                !volumeTarget.percent

        val unsupportedTerminalOk =
            !unsupportedDevelopmentAction.isNullOrBlank() &&
                informationalDevelopmentQuestion == null

        val clipboardRoutingOk =
            clipboardRoutePrefix == "AYANA-R78-CLIPBOARD-001" &&
                clipboardRouteSuffix == "AYANA-R78-CLIPBOARD-002"

        val ok =
            lifecycleOk &&
                appDetailOk &&
                metricsOk &&
                volumeTargetOk &&
                unsupportedTerminalOk &&
                clipboardRoutingOk &&
                lifecycleSemanticObjectRejected &&
                refusalFailClosed &&
                artifact &&
                artifactSemanticContentOk &&
                artifactFollowUpContractOk &&
                personalSearchRoutingOk &&
                artifactMetricsSuppressed &&
                mixedSideEffectMetricsSuppressed &&
                pureMetricGoalTerminalLocal &&
                analyticalMetricGoalRequiresHandoff &&
                conditionalMetricGoalRequiresHandoff

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Whole-goal routing guard распознал lifecycle verification, App Detail final target, clipboard local route, Personal Global Search local route, semantic-object lifecycle guard, fail-closed refusal truth, artifact semantic-content gate + follow-up payload contract, pure multi-metric fast path, verified-facts reasoning handoff и artifact deliverable без greedy interception."
                } else {
                    "Whole-goal routing regression: lifecycle=$lifecycleOk, app_detail=$appDetailOk, metrics=$metricsOk, volume_target=$volumeTargetOk, unsupported_terminal=$unsupportedTerminalOk, clipboard_route=$clipboardRoutingOk, lifecycle_semantic_guard=$lifecycleSemanticObjectRejected, refusal_fail_closed=$refusalFailClosed, artifact=$artifact, artifact_semantic_content=$artifactSemanticContentOk, artifact_follow_up=$artifactFollowUpContractOk, personal_search_route=$personalSearchRoutingOk, artifact_metric_guard=$artifactMetricsSuppressed, mixed_metric_guard=$mixedSideEffectMetricsSuppressed, pure_metric_local=$pureMetricGoalTerminalLocal, analytical_handoff=$analyticalMetricGoalRequiresHandoff, conditional_handoff=$conditionalMetricGoalRequiresHandoff."
                },
            evidenceScope = "live_pure_contract",
            verified = ok,
            evidence =
                JSONObject()
                    .put("lifecycle_ok", lifecycleOk)
                    .put("app_detail_ok", appDetailOk)
                    .put("metrics_ok", metricsOk)
                    .put("volume_target_ok", volumeTargetOk)
                    .put("unsupported_terminal_ok", unsupportedTerminalOk)
                    .put("clipboard_routing_ok", clipboardRoutingOk)
                    .put("lifecycle_semantic_object_guard_ok", lifecycleSemanticObjectRejected)
                    .put("agent_refusal_fail_closed_ok", refusalFailClosed)
                    .put("artifact_ok", artifact)
                    .put("artifact_semantic_content_ok", artifactSemanticContentOk)
                    .put("artifact_follow_up_contract_ok", artifactFollowUpContractOk)
                    .put("personal_search_routing_ok", personalSearchRoutingOk)
                    .put("personal_search_google_guard_ok", externalGoogleSearchRejected)
                    .put("personal_search_notification_route_guard_ok", existingNotificationReadRejected)
                    .put("personal_search_task_route_guard_ok", existingReminderListRejected)
                    .put("artifact_metric_guard", artifactMetricsSuppressed)
                    .put("mixed_metric_guard", mixedSideEffectMetricsSuppressed)
                    .put("pure_metric_goal_terminal_local", pureMetricGoalTerminalLocal)
                    .put("analytical_metric_goal_requires_handoff", analyticalMetricGoalRequiresHandoff)
                    .put("conditional_metric_goal_requires_handoff", conditionalMetricGoalRequiresHandoff)
                    .put("metric_count", metrics.size)
        )
    }


