    private fun acceptanceDiagnosticsDetailProbe(
        recoveryEvidence: JSONObject? = null
    ): JSONObject {
        val rawResult =
            selfDiagnostics.run(
                focus = "all"
            )

        val result =
            diagnosticClosure
                .normalizeSelfDiagnostics(
                    raw = rawResult,
                    recentHistory =
                        commandHistoryStore
                            .recent(
                                24
                            ),
                    recoveryEvidence = recoveryEvidence
                )

        val checks =
            result.optJSONArray("checks")
                ?: JSONArray()

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until checks.length()) {
            val item =
                checks.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaDiagnosticClosure.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val report =
            try {
                diagnosticClosure.reportFromNormalized(
                    result
                )
            } catch (_: Exception) {
                ""
            }

        val missingFromReport =
            nonPass
                .mapNotNull { item ->
                    val name =
                        item.optString("name")
                            .ifBlank {
                                item.optString("id")
                            }
                            .trim()

                    if (
                        name.isNotBlank() &&
                        !report.contains(
                            name,
                            ignoreCase = true
                        )
                    ) {
                        name
                    } else {
                        null
                    }
                }

        val ok =
            report.isNotBlank() &&
                missingFromReport.isEmpty()

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Self-Diagnostics R9 раскрывает все ${nonPass.size} актуальные non-PASS проверки в каноническом отчёте."
                } else {
                    "Self-Diagnostics R9 не раскрыл все актуальные non-PASS проверки: ${missingFromReport.joinToString(", ")}."
                },
            evidenceScope = "live_runtime_contract_r9_freshness",
            verified = ok,
            evidence =
                JSONObject()
                    .put("non_pass_count", nonPass.size)
                    .put("missing_from_report", JSONArray(missingFromReport))
                    .put(
                        "diagnostic_closure_version",
                        AyanaDiagnosticClosure.VERSION
                    )
                    .put(
                        "successes_after_last_error",
                        result.optInt(
                            "successes_after_last_error",
                            0
                        )
                    )
                    .put(
                        "live_agent_core_recovery_passes",
                        result.optInt(
                            "live_agent_core_recovery_passes",
                            0
                        )
                    )
                    .put(
                        "live_agent_core_recovery_applied",
                        result.optBoolean(
                            "live_agent_core_recovery_applied",
                            false
                        )
                    )
                    .put("report", report.take(5000))
        )
    }

