                    append(
                        "_ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789|"
                    )
                }
                append(
                    "LONG_RESULT_END"
                )
            }

        var deleted =
            false

        return try {
            commandHistoryStore.finish(
                id = id,
                success = true,
                result = expected,
                technical = "self_test_long_result"
