        val allowedPages =
            setOf(
                "HOME",
                "TASKS",
                "MEMORY",
                "HISTORY",
                "DIAGNOSTICS",
                "SETTINGS"
            )

        val originalPage =
            prefs.getString(
                MainActivity.UI_STATE_CURRENT_PAGE,
                "HOME"
            )
                .orEmpty()
                .let {
                    if (it in allowedPages) {
                        it
                    } else {
                        "HOME"
                    }
                }

        fun openInternalPageForProbe(
            pageKey: String
        ): Boolean {
            if (pageKey !in allowedPages) {
                return false
            }

            return try {
                startActivity(
                    Intent(
                        this,
                        MainActivity::class.java
                    ).apply {
                        putExtra(
                            MainActivity.EXTRA_OPEN_PAGE,
                            pageKey
                        )

                        addFlags(
                            Intent.FLAG_ACTIVITY_NEW_TASK or
                                Intent.FLAG_ACTIVITY_CLEAR_TOP or
                                Intent.FLAG_ACTIVITY_SINGLE_TOP
                        )
                    }
                )

                val deadline =
                    System.currentTimeMillis() +
                        HISTORY_LIVE_REFRESH_PAGE_VERIFY_TIMEOUT_MS

                var actual =
                    prefs.getString(
                        MainActivity.UI_STATE_CURRENT_PAGE,
                        ""
                    )
                        .orEmpty()

                while (
                    actual != pageKey &&
                    System.currentTimeMillis() < deadline
                ) {
                    try {
                        Thread.sleep(60L)
                    } catch (_: InterruptedException) {
                        Thread.currentThread()
                            .interrupt()
                        break
                    }

                    actual =
                        prefs.getString(
                            MainActivity.UI_STATE_CURRENT_PAGE,
                            ""
                        )
                            .orEmpty()
                }

                actual == pageKey
            } catch (_: Exception) {
                false
            }
        }

        var markerId =
            ""

        var historyTabOpened =
            false

        var markerVisible =
            false

        var cleanupDeleted =
            false

        var restoredOwnApp =
            false

        var restoredPage =
            false

        var observedPackage =
            ""

        var failureReason =
            ""

        try {
            // Use the same production internal-page contract as
            // runLocalInternalPageNavigation(): MainActivity.EXTRA_OPEN_PAGE +
            // UI_STATE_CURRENT_PAGE verification. Accessibility semantic click is
            // intentionally not used here because an in-app navigation tab is not
            // a generic semantic-object action target.
            historyTabOpened =
                openInternalPageForProbe(
                    "HISTORY"
                )

            if (!historyTabOpened) {
                val actual =
                    prefs.getString(
                        MainActivity.UI_STATE_CURRENT_PAGE,
                        ""
                    )
                        .orEmpty()

                failureReason =
                    "history_page_not_verified:actual=$actual"
            } else {
                Thread.sleep(300L)

                markerId =
                    commandHistoryStore.begin(
                        command = marker,
                        source = "selftest"
                    )

                commandHistoryStore.finish(
                    id = markerId,
                    success = true,
                    result = "R9 history live-refresh proof",
                    technical = "reversible_acceptance_probe"
                )

                // MainActivity v7.9 schedules History refresh only on terminal
                // service states (SUCCESS / ERROR / CANCELLED / STOPPED). The R9.0.1
                // probe incorrectly emitted STATE_EXECUTING, so the UI refresh runnable
                // was never scheduled even though the record was persisted correctly.
                // Emit the same terminal SUCCESS signal used by production command
                // completion, wait beyond the 280 ms UI debounce, then restore the
                // diagnostic command's EXECUTING status after the marker check.
                broadcastStatus(
                    "Проверка live-refresh Истории завершена",
                    STATE_SUCCESS
                )

                Thread.sleep(
                    HISTORY_LIVE_REFRESH_PROOF_WAIT_MS
                )

                val screen =
                    try {
                        screenIntelligence.getScreenState()
                    } catch (_: Exception) {
                        JSONObject()
                    }

                observedPackage =
                    screen.optString(
                        "effective_foreground_package",
                        screen.optString(
                            "interaction_package",
                            screen.optString(
                                "package"
                            )
                        )
                    )

                markerVisible =
                    diagnosticClosure
                        .screenContainsMarker(
                            screen = screen,
                            marker = marker
                        )

                if (!markerVisible) {
                    failureReason =
                        "history_marker_not_visible"
                }

                // Continue the still-running acceptance command with truthful state.
                broadcastStatus(
                    "Продолжаю диагностику AYANA…",
                    STATE_EXECUTING
                )
            }
        } finally {
            if (markerId.isNotBlank()) {
                cleanupDeleted =
                    try {
                        commandHistoryStore.delete(
                            markerId
                        )
                    } catch (_: Exception) {
                        false
                    }
            } else {
                cleanupDeleted =
                    true
            }

            restoredPage =
                openInternalPageForProbe(
                    originalPage
                )

            if (restoredPage) {
                try {
                    Thread.sleep(
                        HISTORY_LIVE_REFRESH_RESTORE_WAIT_MS
                    )

                    val restore =
                        screenIntelligence.getScreenState()

                    val restorePackage =
                        restore.optString(
                            "effective_foreground_package",
                            restore.optString(
                                "interaction_package",
                                restore.optString(
                                    "package"
                                )
                            )
                        )

                    restoredOwnApp =
                        restorePackage ==
                            packageName
                } catch (_: Exception) {
                    restoredOwnApp =
                        false
                }
            }

            if (
                failureReason.isBlank() &&
                (!restoredPage || !restoredOwnApp)
            ) {
                failureReason =
                    "history_state_restore_unverified"
            }
        }

        val ok =
            historyTabOpened &&
                markerVisible &&
                cleanupDeleted &&
                restoredPage &&
                restoredOwnApp

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_WARNING
                },
            message =
                if (ok) {
                    "History live-refresh device-confirmed: временная terminal-запись появилась в открытой вкладке История без повторного входа; cleanup и возврат на исходную вкладку AYANA подтверждены."
                } else {
                    "History live-refresh не удалось подтвердить в этом прогоне: ${failureReason.ifBlank { "ui_roundtrip_unverified" }}."
                },
            evidenceScope = "live_ui_reversible_roundtrip",
            verified = ok,
            evidence =
                JSONObject()
                    .put("ui_instrumentation_available", true)
                    .put("navigation_contract", "MainActivity.EXTRA_OPEN_PAGE")
                    .put("original_page", originalPage)
                    .put("history_tab_opened", historyTabOpened)
                    .put("marker_visible_after_terminal", markerVisible)
                    .put("history_refresh_signal_state", STATE_SUCCESS)
                    .put("history_refresh_debounce_wait_ms", HISTORY_LIVE_REFRESH_PROOF_WAIT_MS)
                    .put("cleanup_deleted", cleanupDeleted)
                    .put("page_restored", restoredPage)
                    .put("state_restored", restoredOwnApp)
                    .put("observed_package", observedPackage)
                    .put("marker_prefix", "R9HIST")
                    .put("failure_reason", failureReason)
        )
    }

    private fun acceptanceDiagnosticRoutingProbe(): JSONObject {
        val cases =
            listOf(
                "проведи полную диагностику AYANA",
                "проведи подробную диагностику",
                "проведи всевозможные тесты",
                "протестируй все функции AYANA",
                "проверь все возможности AYANA"
            )

        val routed =
            cases.map {
                phrase ->
                phrase to
                    localAcceptanceTestMode(
                        phrase
                    )
            }

        val exhaustiveOk =
            routed.all {
                it.second ==
                    AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
            }

        val boundedFullOk =
            localAcceptanceTestMode(
                "acceptance test AYANA"
            ) ==
                AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE

        val quickOk =
            localAcceptanceTestMode(
                "проведи тесты"
            ) ==
                AyanaAcceptanceTestEngine.Mode.QUICK_HEALTH

        val codeRequestNotHijacked =
            localAcceptanceTestMode(
                "напиши unit test для Kotlin файла"
            ) ==
                null

        val ok =
            exhaustiveOk &&
                boundedFullOk &&
                quickOk &&
                codeRequestNotHijacked

        val mapping =
            JSONArray()

        routed.forEach {
            (phrase, mode) ->
            mapping.put(
                JSONObject()
                    .put(
                        "phrase",
                        phrase
                    )
                    .put(
                        "mode",
                        mode?.wireName
                            ?: "none"
                    )
            )
        }

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Команды полной диагностики ведут в exhaustive mode; bounded/full/quick и code-scope не конфликтуют."
                } else {
                    "Регрессия маршрутизации диагностических команд."
                },
            evidenceScope = "live_pure_routing_contract",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "exhaustive_mappings",
                        mapping
                    )
                    .put(
                        "bounded_full_ok",
                        boundedFullOk
                    )
                    .put(
                        "quick_ok",
                        quickOk
                    )
                    .put(
                        "code_request_not_hijacked",
                        codeRequestNotHijacked
                    )
        )
    }

    private fun acceptanceWakeGrammarProbe(): JSONObject {
        val command =
            removeLeadingWakeWord(
                "аяна открой ютуб"
            )

        val wakeOnly =
            removeLeadingWakeWord(
                "аяна"
            )

        val noWake =
            removeLeadingWakeWord(
                "открой ютуб"
            )

        val variant =
            removeLeadingWakeWord(
                "айана проверь батарею"
            )

        val ok =
            command ==
                "открой ютуб" &&
                wakeOnly.isBlank() &&
                noWake ==
                "открой ютуб" &&
                variant ==
                "проверь батарею"

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Wake-word grammar корректно отделяет «Аяна»/варианты от команды и сохраняет фразу без wake-word."
                } else {
                    "Wake-word grammar regression."
                },
            evidenceScope = "live_pure_voice_grammar",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "ayana_command",
                        command
                    )
                    .put(
                        "wake_only_blank",
                        wakeOnly.isBlank()
                    )
                    .put(
                        "no_wake",
                        noWake
                    )
                    .put(
                        "variant_command",
                        variant
                    )
        )
    }

    private fun acceptanceStopGrammarProbe(): JSONObject {
        val direct =
            cancelPhraseDetector.detect(
                value = "стоп",
                speaking = false
            )

        val withWake =
            cancelPhraseDetector.detect(
                value = "аяна стоп",
                speaking = false
            )

        val ordinary =
            cancelPhraseDetector.detect(
                value = "открой ютуб",
                speaking = false
