    private fun acceptanceAgentCoreOrdinaryProbe(): JSONObject {
        val response =
            acceptanceWorkerRequest(
                payload =
                    acceptanceAgentMessagePayload(
                        "что такое фотосинтез"
                    ),
                readTimeoutMs = 26000
            )

        val code =
            response.optInt(
                "http_code",
                -1
            )

        val data =
            response.optJSONObject(
                "data"
            ) ?: JSONObject()

        val reply =
            data.optString(
                "reply"
            )

        val ok =
            code in 200..299 &&
                data.optString(
                    "type"
                ) ==
                "final" &&
                data.optString(
                    "terminal_status"
                ) ==
                "SUCCESS" &&
                reply.length >=
                40

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Agent Core ordinary online response completed: ${response.optLong("elapsed_ms")} мс, profile=${data.optString("worker_transport_profile")}."
                } else {
                    "Agent Core ordinary online probe failed: HTTP=$code, type=${data.optString("type")}, error=${data.optString("error")}."
                },
            evidenceScope = "bounded_online_agent_core",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "http_code",
                        code
                    )
                    .put(
                        "elapsed_ms",
                        response.optLong(
                            "elapsed_ms"
                        )
                    )
                    .put(
                        "type",
                        data.optString(
                            "type"
                        )
                    )
                    .put(
                        "terminal_status",
                        data.optString(
                            "terminal_status"
                        )
                    )
                    .put(
                        "completion_integrity",
                        data.optString(
                            "completion_integrity"
                        )
                    )
                    .put(
                        "worker_transport_profile",
                        data.optString(
                            "worker_transport_profile"
                        )
                    )
                    .put(
                        "worker_attempts",
                        data.optInt(
                            "worker_attempts",
                            -1
                        )
                    )
                    .put(
                        "context_mode",
                        data.optString(
                            "context_mode"
                        )
                    )
                    .put(
                        "reply_chars",
                        reply.length
                    )
        )
            .put(
                "network_turns",
                1
            )
    }

