    private fun durableArgumentsForPersistence(
        toolName: String,
        arguments: JSONObject
    ): JSONObject {

        val copy =
            try {
                JSONObject(
                    arguments.toString()
                )
            } catch (_: Exception) {
                JSONObject()
            }

        if (
            toolName ==
            "input_screen_text" &&
            copy.has(
                "text"
            )
        ) {
            copy.put(
                "text",
                "[не сохраняется]"
            )
        }

        return copy
    }

