    private fun isSemanticActionTruthTool(
        name: String
    ): Boolean =
        name in
            setOf(
                "click_text",
                "click_screen_element",
                "input_screen_text",
                "scroll_screen",
                "tap_screen_coordinates"
            )
private fun isSemanticActionResultVerified(
        result: JSONObject
    ): Boolean {

        if (
            !result.optBoolean(
                "success",
                false
            )
        ) {
            return false
        }

        // New semantic tools carry explicit `verified`. Keep compatibility with
        // any legacy local result that only exposes factual success.
        return !result.has(
            "verified"
        ) ||
            result.optBoolean(
                "verified",
                false
            )
    }

    private fun semanticActionFailureTerminalStatus(
        result: JSONObject
    ): String? =
        when (
            result
                .optString(
                    "terminal_status"
                )
                .uppercase(
                    Locale.ROOT
                )
        ) {
            "BLOCKED" ->
                AyanaCommandHistoryStore.STATUS_BLOCKED

            "UNSUPPORTED" ->
                AyanaCommandHistoryStore.STATUS_UNSUPPORTED

            // ERROR remains the default when success=false and no explicit
            // non-error terminal class applies.
            else ->
                null
        }

    private fun executeAgentTool(
        name: String,
        arguments: JSONObject,
        trustedUserConfirmation: Boolean = false
    ): JSONObject {

        // Confirmation is a local user-authored fact, never a model-authored
        // field. Sensitive tools receive confirmed=true only on the explicit
        // resume/confirm path above.
        if (
            name in
            setOf(
                "click_screen_element",
                "tap_screen_coordinates",
                "execute_android_plan"
            )
        ) {
            arguments.put(
                "confirmed",
                trustedUserConfirmation
            )
        }

        val safetyDecision =
            try {
                safetyPolicy
                    .evaluateTool(
                        name,
                        arguments
                    )
            } catch (error: Exception) {
                AyanaSafetyPolicy.Decision(
                    allowed = false,
                    requiresConfirmation = false,
                    riskLevel = AyanaSafetyPolicy.RISK_PROHIBITED,
                    riskName = "policy_error",
                    reason = error.message
                        ?: "Ошибка локальной политики безопасности"
                )
            }

        if (!safetyDecision.allowed) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "safety_gate",
                message = safetyDecision.riskName,
                details = safetyDecision.reason.take(260)
            )

            return toolResult(
                false,
                safetyDecision.reason
                    .ifBlank {
                        "Действие остановлено локальной политикой безопасности AYANA."
                    }
            )
                .put(
                    "safety_blocked",
                    true
                )
                .put(
                    "risk_level",
                    safetyDecision.riskLevel
                )
                .put(
                    "risk_name",
                    safetyDecision.riskName
                )
                .put(
                    "requires_confirmation",
                    safetyDecision.requiresConfirmation
                )
        }

        return try {

            when (name) {

                "execute_android_goal" -> {
                    executeAndroidGoal(
                        arguments
                    )
                }

                "execute_android_plan" -> {

                    // Universal Android execution bridge. Persist the plan before
                    // execution so an interrupted low-risk plan can resume from a
                    // checkpoint instead of restarting the whole navigation.
                    val durableId =
                        currentDurableGoalId

                    if (durableId != null) {
                        val planSaved =
                            try {
                                durableGoalStore
                                    .attachAndroidPlan(
                                        id = durableId,
                                        arguments = arguments,
                                        plan = arguments
                                    ) !=
                                    null
                            } catch (error: Exception) {
                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "goal_checkpoint_error",
                                    message = "Android plan не сохранён перед выполнением",
                                    details = error.message.orEmpty().take(220)
                                )
                                false
                            }

                        if (!planSaved) {
                            return toolResult(
                                false,
                                "Android-план не выполнен: durable checkpoint плана не удалось сохранить."
                            )
                                .put(
                                    "status",
                                    "checkpoint_failed"
                                )
                                .put(
                                    "checkpoint_failed",
                                    true
                                )
                        }
                    }

                    androidTaskEngine
                        .execute(
                            plan = arguments,
                            confirmed =
                                arguments
                                    .optBoolean(
                                        "confirmed",
                                        false
                                    ),
                            startIndex = 0,
                            initialActionsUsed = 0,
                            onCheckpoint =
                                { checkpoint ->
                                    persistAndroidGoalCheckpoint(
                                        goalId = durableId,
                                        checkpoint = checkpoint,
                                        historyMessage = "Android plan checkpoint"
                                    )
                                }
                        )
                }

                "open_app" -> {

                    agentOpenApp(
                        arguments
                            .optString(
                                "name"
                            )
                    )
                }

                "open_settings" -> {

                    agentOpenSettings(
                        arguments
                            .optString(
                                "section"
                            )
                    )
                }

                "open_app_info" -> {

                    agentOpenAppInfo(
                        arguments
                            .optString(
                                "name"
                            )
                    )
                }

                "open_app_settings" -> {

                    agentOpenAppSettings(
                        requestedName =
                            arguments
                                .optString(
                                    "name"
                                ),
                        section =
                            arguments
                                .optString(
                                    "section",
                                    "info"
                                )
                    )
                }

                "get_device_state" -> {

                    agentGetDeviceState()
                }

                "get_device_capabilities" -> {

                    agentGetDeviceCapabilities()
                }

                "run_self_diagnostics" -> {

                    agentRunSelfDiagnostics(
                        focus =
                            arguments.optString(
                                "focus",
                                "all"
                            ),
                        appName =
                            arguments.optString(
                                "app"
                            )
                    )
                }

                "list_installed_apps" -> {

                    agentListInstalledApps(
                        query =
                            arguments.optString(
                                "query"
                            ),
                        offset =
                            arguments.optInt(
                                "offset",
                                0
                            ),
                        limit =
                            arguments.optInt(
                                "limit",
                                80
                            ),
                        namesOnly =
                            arguments.optBoolean(
                                "names_only",
                                true
                            )
                    )
                }

                "resolve_app" -> {

                    agentResolveApp(
                        arguments.optString(
                            "name"
                        )
                    )
                }

                "list_goals" -> {

                    agentListGoals()
                }

                "select_goal" -> {

                    agentSelectGoal(
                        arguments.optString(
                            "query"
                        )
                    )
                }

                "cancel_goal" -> {

                    agentCancelGoal(
                        arguments.optString(
                            "query"
                        )
                    )
                }

                "press_back" -> {

                    screenIntelligence
                        .pressBack()
                }

                "press_home" -> {

                    screenIntelligence
                        .pressHome()
                }

                "change_volume" -> {

                    agentChangeVolume(
                        arguments
                            .optString(
                                "action"
                            )
                    )
                }

                "click_text" -> {

                    val target =
                        arguments
                            .optString(
                                "text"
                            )
                            .trim()

                    if (target.isBlank()) {
                        toolResult(
                            false,
                            "Не указан элемент для нажатия"
                        )
                    } else {
                        val result =
                            screenIntelligence.click(
                                target = target,
                                confirmed = false
                            )

                        result.optJSONObject("screen")?.let { screen ->
                            capabilityRegistry.recordScreenObservation(screen)
                        }

                        result
                    }
                }

                "youtube_search" -> {

                    agentYouTubeSearch(
                        arguments
                            .optString(
                                "query"
                            )
                    )
                }

                "google_search" -> {

                    agentGoogleSearch(
                        arguments
                            .optString(
                                "query"
                            )
                    )
                }

                "map_search" -> {

                    agentMapSearch(
                        arguments
                            .optString(
                                "query"
                            )
                    )
                }

                "remember_memory" -> {

                    agentRememberMemory(
                        text =
                            arguments
                                .optString(
                                    "text"
                                ),
                        category =
                            arguments
                                .optString(
                                    "category",
                                    "general"
                                )
                    )
                }

                "forget_memory" -> {

                    agentForgetMemory(
                        arguments
                            .optString(
                                "query"
                            )
                    )
                }

                "recall_memory" -> {

                    agentRecallMemory(
                        arguments
                            .optString(
                                "query"
                            )
                    )
                }

                "list_memory" -> {

                    agentListMemory(
                        arguments.optString(
                            "query"
                        )
                    )
                }

                "update_memory" -> {

                    agentUpdateMemory(
                        query =
                            arguments.optString(
                                "query"
                            ),
                        newText =
                            arguments.optString(
                                "new_text"
                            ),
                        category =
                            arguments.optString(
                                "category"
                            )
                    )
                }

                "create_reminder" -> {

                    agentCreateReminder(
                        title =
                            arguments
                                .optString(
                                    "title"
                                ),
                        message =
                            arguments
                                .optString(
                                    "message"
                                ),
                        triggerAtLocal =
                            arguments
                                .optString(
                                    "trigger_at_local"
                                ),
                        recurrence =
                            arguments
                                .optString(
                                    "recurrence",
                                    AyanaTaskStore
                                        .RECURRENCE_NONE
                                )
                    )
                }

                "list_reminders" -> {

                    agentListReminders()
                }

                "create_artifact" -> {

                    artifactEngine
                        .create(
                            arguments = arguments,
                            tryBeginPublish = { detail ->
                                executionKernel.tryBeginIrreversibleDispatch(
                                    kind = "artifact_publish",
                                    detail = detail
                                )
                            },
                            onPublishAccepted = { detail ->
                                executionKernel.markIrreversibleDispatchAccepted(
                                    detail
                                )
                            },
                            onPublishReconciliationStarted = { detail ->
                                executionKernel.markSideEffectReconciliationStarted(
                                    detail
                                )
                            },
                            onPublishReconciled = { committed, detail ->
                                executionKernel.markSideEffectReconciled(
                                    committed = committed,
                                    detail = detail
                                )
                            }
                        )
                }

                "delete_reminder" -> {

                    agentDeleteReminder(
                        arguments
                            .optString(
                                "query"
                            )
                    )
                }

                "update_reminder" -> {

                    agentUpdateReminder(
                        query =
                            arguments.optString(
                                "query"
                            ),
                        title =
                            arguments.optString(
                                "title"
                            ),
                        message =
                            arguments.optString(
                                "message"
                            ),
                        triggerAtLocal =
                            arguments.optString(
                                "trigger_at_local"
                            ),
                        recurrence =
                            arguments.optString(
                                "recurrence"
                            ),
                        enabledMode =
                            arguments.optString(
                                "enabled_mode",
                                "keep"
                            )
                    )
                }

                "set_reminder_enabled" -> {

                    agentSetReminderEnabled(
                        query =
                            arguments.optString(
                                "query"
                            ),
                        enabled =
                            arguments.optBoolean(
                                "enabled",
                                true
                            )
                    )
                }

                "get_screen_state" -> {

                    val screen =
                        screenIntelligence
                            .getScreenState()

                    capabilityRegistry
                        .recordScreenObservation(
                            screen
                        )

                    screen
                }

                "click_screen_element" -> {

                    screenIntelligence
                        .click(
                            target =
                                arguments
                                    .optString(
                                        "target"
                                    ),
                            confirmed =
                                arguments
                                    .optBoolean(
                                        "confirmed",
                                        false
                                    )
                        )
                }

                "input_screen_text" -> {

                    val target =
                        arguments
                            .optString(
                                "target"
