    private fun agentListInstalledApps(
        query: String,
        offset: Int = 0,
        limit: Int = 80,
        namesOnly: Boolean = true
    ): JSONObject {

        val clean =
            query.trim()

        if (
            clean.isBlank()
        ) {
            return appResolver
                .listAsJson(
                    limit =
                        limit.coerceIn(
                            1,
                            150
                        ),
                    offset =
                        offset.coerceAtLeast(
                            0
                        ),
                    namesOnly =
                        namesOnly,
                    forceRefresh =
                        offset <=
                            0
                )
        }

        val resolution =
            appResolver
                .resolve(
                    clean,
                    forceRefresh = true
                )

        return JSONObject()
            .put(
                "success",
                resolution.success
            )
            .put(
                "query",
                clean
            )
            .put(
                "resolution",
                resolution.toJson()
            )
            .put(
                "message",
                if (resolution.success) {
                    "Найдено приложение ${resolution.label}"
                } else {
                    "Надёжное совпадение не найдено"
                }
            )
    }

