    private fun parseLocalTaskTimeOrNull(
        value: String
    ): Long? {

        val clean =
            value.trim()

        if (
            clean.isBlank()
        ) {
            return null
        }

        return try {
            LocalDateTime
                .parse(
                    clean,
                    DateTimeFormatter
                        .ofPattern(
                            "yyyy-MM-dd'T'HH:mm:ss"
                        )
                )
                .atZone(
                    ZoneId.systemDefault()
                )
                .toInstant()
                .toEpochMilli()
        } catch (_: Exception) {
            null
        }
    }

    private fun agentUpdateReminder(
        query: String,
        title: String,
        message: String,
        triggerAtLocal: String,
        recurrence: String,
        enabledMode: String
    ): JSONObject {

        val matches =
            taskStore
                .findByQuery(
                    query,
                    3
                )

        if (
            matches.size !=
            1
        ) {
            val candidates =
                JSONArray()

            matches.forEach { task ->
                candidates.put(
                    JSONObject()
                        .put(
                            "id",
                            task.id
                        )
                        .put(
                            "title",
                            task.title
                        )
                )
            }

            return JSONObject()
                .put(
                    "success",
                    false
                )
                .put(
                    "message",
                    if (matches.isEmpty()) {
                        "Напоминание не найдено"
                    } else {
                        "Найдено несколько похожих напоминаний; уточните"
                    }
                )
                .put(
                    "candidates",
                    candidates
                )
        }

        val old =
            matches.first()

        val parsedTrigger =
            if (
                triggerAtLocal.isBlank()
            ) {
                null
            } else {
                parseLocalTaskTimeOrNull(
                    triggerAtLocal
                )
                    ?: return toolResult(
                        false,
                        "Неверный формат нового времени; нужен YYYY-MM-DDTHH:mm:ss"
                    )
            }

        if (
            parsedTrigger !=
            null &&
            parsedTrigger <=
            System.currentTimeMillis()
        ) {
            return toolResult(
                false,
                "Новое время напоминания уже прошло"
            )
        }

        val enabled =
            when (
                enabledMode
                    .trim()
                    .lowercase(
                        Locale.ROOT
                    )
            ) {
                "true",
                "enable",
                "enabled",
                "включить" ->
                    true
                "false",
                "disable",
                "disabled",
                "отключить" ->
                    false
                else ->
                    null
            }

        val updated =
            taskStore
                .updateTask(
                    id = old.id,
                    title = title.trim()
                        .ifBlank {
                            null
                        },
                    message = message.trim()
                        .ifBlank {
                            null
                        },
                    triggerAtMillis = parsedTrigger,
                    recurrence = recurrence.trim()
                        .ifBlank {
                            null
                        },
                    enabled = enabled
                )
                ?: return toolResult(
                    false,
                    "Не удалось изменить напоминание"
                )

        taskScheduler
            .cancel(
                old
            )

        if (
            updated.enabled &&
            updated.triggerAtMillis >
            System.currentTimeMillis()
        ) {
            val schedule =
                taskScheduler
                    .schedule(
                        updated
                    )

            if (!schedule.success) {
                // Fail closed: restore the old task and schedule rather than
                // silently leaving edited metadata without a real alarm.
                taskStore.updateTask(
                    id = old.id,
                    title = old.title,
                    message = old.message,
                    triggerAtMillis = old.triggerAtMillis,
                    recurrence = old.recurrence,
                    enabled = old.enabled
                )
                if (
                    old.enabled &&
                    old.triggerAtMillis >
                    System.currentTimeMillis()
                ) {
                    taskScheduler.schedule(
                        old
                    )
                }
                return toolResult(
                    false,
                    "Изменение отменено: Android не смог перепланировать напоминание"
                )
            }
        }

        return JSONObject()
            .put(
                "success",
                true
            )
            .put(
                "task_id",
                updated.id
            )
            .put(
                "title",
                updated.title
            )
            .put(
                "enabled",
                updated.enabled
            )
            .put(
                "recurrence",
                updated.recurrence
            )
            .put(
                "trigger_at_millis",
                updated.triggerAtMillis
            )
            .put(
                "message",
                "Напоминание обновлено"
            )
    }

