    private fun resolveInstalledAppTarget(
        requestedName: String
    ): Pair<String, String>? {

        val resolved =
            appResolver
                .resolve(
                    requestedName
                )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (resolved.success) {
                    "app_resolved"
                } else {
                    "app_resolver_miss"
                },
            message =
                if (resolved.success) {
                    "App Resolver v2: ${resolved.label}"
                } else {
                    "App Resolver v2: приложение не разрешено"
                },
            details =
                "requested=${requestedName.take(120)}; " +
                    "package=${resolved.packageName}; " +
                    "confidence=${resolved.confidence}; " +
                    "source=${resolved.source}; " +
                    "reason=${resolved.reason}".take(620)
        )

        if (!resolved.success) {
            return null
        }

        return resolved.packageName to resolved.label
    }

    private fun agentOpenAppSettings(
        requestedName: String,
        section: String
    ): JSONObject {

        val resolved =
            resolveInstalledAppTarget(
                requestedName
            )
                ?: return toolResult(
                    false,
                    "Приложение не найдено: $requestedName"
                )

        val packageName =
            resolved.first

        val label =
            resolved.second

        val normalizedSection =
            canonicalAppDetailSection(
                section
            )
                ?: return toolResult(
                    false,
                    "Неподдерживаемый раздел приложения: $section"
                )

        val sectionDisplayName =
            appDetailSectionDisplayName(
                normalizedSection
            )

        if (
            normalizedSection ==
            "info"
        ) {

            return try {

                val intentDispatchedAt =
                    System.currentTimeMillis()

                startAppInfoIntent(
                    packageName
                )

                val verification =
                    awaitVerifiedAppDetailScreen(
                        appTarget = label,
                        section = "info",
                        timeoutMs = APP_DETAIL_VERIFY_TIMEOUT_MS
                    )

                val intentAttestation =
                    if (verification.optBoolean("success", false)) {
                        JSONObject().put("success", false)
                    } else {
                        verifySettingsIntentAttestation(
                            screen = verification.optJSONObject("screen") ?: JSONObject(),
                            targetPackage = packageName,
                            section = "info",
                            dispatchedAtMs = intentDispatchedAt
                        )
                    }

                if (
                    verification.optBoolean(
                        "success",
                        false
                    ) ||
                    intentAttestation.optBoolean("success", false)
                ) {
                    if (intentAttestation.optBoolean("success", false)) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "settings_intent_attested",
                            message = "App Info подтверждён exact-intent attestation",
                            details = intentAttestation.toString().take(900)
                        )
                    }
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "app_settings_verified",
                        message = "App Info подтверждён",
                        details =
                            "package=$packageName; section=info; path=direct_intent".take(520)
                    )

                    toolResult(
                        true,
                        "Открыта информация о приложении $label"
                    )
                        .put(
                            "verified",
                            true
                        )
                        .put(
                            "package",
                            packageName
                        )
                        .put(
                            "label",
                            label
                        )
                } else {
                    toolResult(
                        false,
                        "Экран информации о приложении $label не подтверждён"
                    )
                        .put(
                            "verified",
                            false
                        )
                }

            } catch (
                error: Exception
            ) {
                toolResult(
                    false,
                    "Не удалось открыть информацию о приложении $label: " +
                        (
                            error.message
                                ?: "неизвестная ошибка"
                            )
                )
            }
        }

        val directIntent =
            buildDirectAppSettingsIntent(
                packageName = packageName,
                section = normalizedSection
            )

        if (
            directIntent !=
            null
        ) {

            try {

                val intentDispatchedAt =
                    System.currentTimeMillis()

                startActivity(
                    directIntent.apply {
                        addFlags(
                            Intent.FLAG_ACTIVITY_NEW_TASK
                        )
                    }
                )

                val directVerification =
                    awaitVerifiedAppDetailScreen(
                        appTarget = label,
                        section = normalizedSection,
                        timeoutMs = APP_DETAIL_VERIFY_TIMEOUT_MS
                    )

                val intentAttestation =
                    if (directVerification.optBoolean("success", false)) {
                        JSONObject().put("success", false)
                    } else {
                        verifySettingsIntentAttestation(
                            screen = directVerification.optJSONObject("screen") ?: JSONObject(),
                            targetPackage = packageName,
                            section = normalizedSection,
                            dispatchedAtMs = intentDispatchedAt
                        )
                    }

                if (
                    directVerification.optBoolean(
                        "success",
                        false
                    ) ||
                    intentAttestation.optBoolean("success", false)
                ) {

                    if (intentAttestation.optBoolean("success", false)) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "settings_intent_attested",
                            message = "Раздел Settings подтверждён exact-intent attestation",
                            details = intentAttestation.toString().take(900)
                        )
                        executionKernel.addEvidence(
                            type = "settings_intent_attestation",
                            source = "settings_verifier",
                            detail = intentAttestation.toString(),
                            confidence = intentAttestation.optInt("confidence", 80)
                        )
                    }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "app_settings_verified",
                        message = "Раздел приложения подтверждён",
                        details =
                            "package=$packageName; section=$normalizedSection; path=direct_intent".take(520)
                    )

                    return toolResult(
                        true,
                        "Открыт раздел «$sectionDisplayName» для приложения $label"
                    )
                        .put(
                            "verified",
                            true
                        )
                        .put(
                            "package",
                            packageName
                        )
                        .put(
                            "label",
                            label
                        )
                        .put(
                            "section",
                            normalizedSection
                        )
                        .put(
                            "path",
                            "direct_intent"
                        )
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_settings_fallback",
                    message = "Прямой Android Intent не подтвердил конечный экран",
                    details =
                        "package=$packageName; section=$normalizedSection; fallback=app_info_click".take(520)
                )

            } catch (
                error: Exception
            ) {

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_settings_fallback",
                    message = "Прямой Android Intent недоступен",
                    details =
                        "package=$packageName; section=$normalizedSection; error=${error.message ?: "unknown"}".take(520)
                )
            }
        }

        // OEM-safe deterministic fallback. Samsung One UI can accept a documented
        // Settings Intent without actually replacing the current detail fragment.
        // In that case open the real App Info page, click the requested row through
        // Accessibility, and only return SUCCESS after the final screen is observed.
        return try {

            val appInfoIntentDispatchedAt =
                System.currentTimeMillis()

            startAppInfoIntent(
                packageName
            )

            var appInfoVerification =
                awaitVerifiedAppDetailScreen(
                    appTarget = label,
                    section = "info",
                    timeoutMs = APP_DETAIL_VERIFY_TIMEOUT_MS
                )

            var appInfoAttestation =
                if (appInfoVerification.optBoolean("success", false)) {
                    JSONObject().put("success", false)
                } else {
                    verifySettingsIntentAttestation(
                        screen = appInfoVerification.optJSONObject("screen") ?: JSONObject(),
                        targetPackage = packageName,
                        section = "info",
                        dispatchedAtMs = appInfoIntentDispatchedAt
                    )
                }

            // v12.8.11 Samsung transition grace: an exact App Info intent can be
            // accepted while Accessibility still reports a transient launcher/system
            // shell at the original 3.2 s boundary. Give only this exact-intent fallback
            // one additional bounded observation window; never infer success from time
            // or dispatch alone, and keep the same strict screen/attestation proof.
            if (
                !appInfoVerification.optBoolean("success", false) &&
                !appInfoAttestation.optBoolean("success", false) &&
                !cancelRequested &&
                !shuttingDown
            ) {
                val graceVerification =
                    awaitVerifiedAppDetailScreen(
appTarget = label,
                        section = "info",
                        timeoutMs = APP_DETAIL_TRANSITION_GRACE_MS
                    )

                val graceAttestation =
                    if (graceVerification.optBoolean("success", false)) {
                        JSONObject().put("success", false)
                    } else {
                        verifySettingsIntentAttestation(
                            screen = graceVerification.optJSONObject("screen") ?: JSONObject(),
                            targetPackage = packageName,
                            section = "info",
                            dispatchedAtMs = appInfoIntentDispatchedAt
                        )
                    }

                if (
                    graceVerification.optBoolean("success", false) ||
                    graceAttestation.optBoolean("success", false)
                ) {
                    appInfoVerification = graceVerification
                    appInfoAttestation = graceAttestation

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "app_settings_transition_recovered",
                        message = "App Info подтверждён после bounded transition grace",
                        details =
                            "package=$packageName; section=$normalizedSection; grace_ms=$APP_DETAIL_TRANSITION_GRACE_MS".take(520)
                    )
                } else {
                    appInfoVerification = graceVerification
                    appInfoAttestation = graceAttestation
                }
            }

            if (
                !appInfoVerification.optBoolean(
                    "success",
                    false
                ) &&
                !appInfoAttestation.optBoolean("success", false)
            ) {

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_settings_verify_failed",
                    message = "Не удалось подтвердить App Info перед fallback",
                    details =
                        (
                            "package=$packageName; section=$normalizedSection; " +
                                appDetailVerificationDiagnosticSummary(
                                    appInfoVerification.optJSONObject("screen") ?: JSONObject()
                                )
                            ).take(1800)
                )

                return toolResult(
                    false,
                    "Не удалось подтвердить экран приложения $label перед переходом в «$sectionDisplayName»"
                )
                    .put(
                        "verified",
                        false
                    )
            }

            if (appInfoAttestation.optBoolean("success", false)) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "settings_intent_attested",
                    message = "Fallback App Info подтверждён exact-intent attestation",
                    details = appInfoAttestation.toString().take(900)
                )
            }

            val subpageResult =
                tryOpenAppInfoSubpageLocally(
                    subpage = normalizedSection,
                    appTarget = label
                )

            if (
                subpageResult.optBoolean(
                    "success",
                    false
                )
            ) {

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_settings_verified",
                    message = "Раздел приложения подтверждён",
                    details =
                        "package=$packageName; section=$normalizedSection; path=app_info_click".take(520)
                )

                toolResult(
                    true,
                    "Открыт раздел «$sectionDisplayName» для приложения $label"
                )
                    .put(
                        "verified",
                        true
                    )
                    .put(
                        "package",
                        packageName
                    )
                    .put(
                        "label",
                        label
                    )
                    .put(
                        "section",
                        normalizedSection
                    )
                    .put(
                        "path",
                        "app_info_click"
                    )

            } else {

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_settings_verify_failed",
                    message = "Конечный экран приложения не подтверждён",
                    details =
                        (
                            "package=$packageName; section=$normalizedSection; " +
                                appDetailVerificationDiagnosticSummary(
                                    subpageResult.optJSONObject("screen") ?:
                                        appInfoVerification.optJSONObject("screen") ?:
                                        JSONObject()
                                )
                            ).take(1800)
                )

                toolResult(
                    false,
                    "Не удалось подтвердить раздел «$sectionDisplayName» для приложения $label"
                )
                    .put(
                        "verified",
                        false
                    )
                    .put(
                        "package",
                        packageName
                    )
                    .put(
                        "label",
                        label
                    )
                    .put(
                        "section",
                        normalizedSection
                    )
            }

        } catch (
            error: Exception
        ) {

            toolResult(
                false,
                "Не удалось открыть параметры приложения $label: " +
                    (
                        error.message
                            ?: "неизвестная ошибка"
                        )
            )
                .put(
                    "verified",
                    false
                )
        }
    }

    private fun canonicalAppDetailSection(
        value: String
    ): String? {

        val normalized =
            value
                .lowercase(
                    Locale.ROOT
                )
                .replace('ё', 'е')
                .trim()

        return when (
            normalized
        ) {

            "permissions",
            "permission",
            "разрешения",
            "разрешение" ->
                "permissions"

            "battery",
            "батарея",
            "аккумулятор" ->
                "battery"

            "storage",
            "хранилище",
            "память" ->
                "storage"

            "mobile_data",
            "mobile data",
            "data_usage",
            "data usage",
            "мобильные данные",
            "использование данных" ->
                "mobile_data"

            "notifications",
            "notification",
            "уведомления",
            "уведомление" ->
                "notifications"

            "open_by_default",
            "open by default",
            "по умолчанию",
            "открытие по умолчанию",
            "открытие ссылок" ->
                "open_by_default"

            "language",
            "languages",
            "язык",
            "языки" ->
                "language"

            "info",
            "app_info",
            "app info",
            "информация",
            "информация о приложении" ->
                "info"

            else ->
                detectAppDetailSection(
                    normalized
                )
        }
    }

    private fun appDetailSectionDisplayName(
        section: String
    ): String {

        return when (
            section
        ) {

            "permissions" ->
                "Разрешения"

            "battery" ->
                "Батарея"

            "storage" ->
                "Хранилище"

            "mobile_data" ->
                "Мобильные данные"

            "notifications" ->
                "Уведомления"

            "open_by_default" ->
                "Использование по умолчанию"

            "language" ->
                "Язык"

            "info" ->
                "Информация о приложении"

            else ->
                section
        }
    }

    private fun buildDirectAppSettingsIntent(
        packageName: String,
        section: String
    ): Intent? {

        return when (
            section
        ) {

            "notifications" ->
                if (
                    Build.VERSION.SDK_INT >=
                    Build.VERSION_CODES.O
                ) {
                    Intent(
                        Settings.ACTION_APP_NOTIFICATION_SETTINGS
                    ).apply {
                        putExtra(
                            Settings.EXTRA_APP_PACKAGE,
                            packageName
                        )
                    }
                } else {
                    null
                }

            "open_by_default" ->
                if (
                    Build.VERSION.SDK_INT >=
                    Build.VERSION_CODES.S
                ) {
                    Intent(
                        Settings.ACTION_APP_OPEN_BY_DEFAULT_SETTINGS,
                        Uri.parse(
                            "package:$packageName"
                        )
                    )
                } else {
                    null
                }

            "language" ->
                if (
                    Build.VERSION.SDK_INT >=
                    Build.VERSION_CODES.TIRAMISU
                ) {
                    Intent(
                        Settings.ACTION_APP_LOCALE_SETTINGS,
                        Uri.parse(
                            "package:$packageName"
                        )
                    )
                } else {
                    null
                }

            else ->
                null
        }
    }

    private fun agentGetDeviceState():
        JSONObject {

        val batteryManager =
            getSystemService(
                Context.BATTERY_SERVICE
            ) as BatteryManager

        val batteryPercent =
            try {
                batteryManager
                    .getIntProperty(
                        BatteryManager
                            .BATTERY_PROPERTY_CAPACITY
                    )
            } catch (_: Exception) {
                -1
            }

        val batteryIntent =
            try {
                registerReceiver(
                    null,
                    IntentFilter(
                        Intent.ACTION_BATTERY_CHANGED
                    )
                )
            } catch (_: Exception) {
                null
            }

        val batteryStatus =
            batteryIntent
                ?.getIntExtra(
                    BatteryManager.EXTRA_STATUS,
                    BatteryManager.BATTERY_STATUS_UNKNOWN
                )
                ?: BatteryManager.BATTERY_STATUS_UNKNOWN

        val charging =
            batteryStatus ==
                BatteryManager.BATTERY_STATUS_CHARGING ||
                batteryStatus ==
                BatteryManager.BATTERY_STATUS_FULL

        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        val currentVolume =
            try {
                audioManager
                    .getStreamVolume(
                        AudioManager.STREAM_MUSIC
                    )
            } catch (_: Exception) {
                -1
            }

        val maxVolume =
            try {
                audioManager
                    .getStreamMaxVolume(
                        AudioManager.STREAM_MUSIC
                    )
            } catch (_: Exception) {
                -1
            }

        val orientation =
            when (
                resources
                    .configuration
                    .orientation
            ) {

                android.content
                    .res
                    .Configuration
                    .ORIENTATION_LANDSCAPE ->
                    "landscape"

                android.content
                    .res
                    .Configuration
                    .ORIENTATION_PORTRAIT ->
                    "portrait"

                else ->
                    "unknown"
            }

        val networkSnapshot =
            readNetworkTruthSnapshot()

        val storageStat =
            try {
                StatFs(
                    Environment
                        .getDataDirectory()
                        .absolutePath
                )
            } catch (_: Exception) {
                null
            }

        val brightnessRaw =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS
                )
            } catch (_: Exception) {
                -1
            }

        val brightnessPercent =
            if (brightnessRaw >= 0) {
                ((brightnessRaw.coerceIn(0, 255) * 100.0) / 255.0)
                    .toInt()
            } else {
                -1
            }

        val screen =
            try {
                screenIntelligence
                    .getScreenState()
            } catch (_: Exception) {
                JSONObject()
                    .put(
                        "success",
                        false
                    )
            }

        return JSONObject()
            .put(
                "success",
                true
            )
            .put(
                "battery_percent",
                batteryPercent
            )
            .put(
                "charging",
                charging
            )
            .put(
                "media_volume",
                currentVolume
            )
            .put(
                "media_volume_max",
                maxVolume
            )
            .put(
                "orientation",
                orientation
            )
            .put(
                "network_observation_available",
                networkSnapshot.observationAvailable
            )
            .put(
                "network_connected",
                networkSnapshot.connected
            )
            .put(
                "network_validated",
                networkSnapshot.validated
            )
            .put(
                "network_transport",
                networkSnapshot.transport
            )
            .put(
                "network_observation_error",
                networkSnapshot.error
            )
            .put(
                "storage_free_bytes",
                storageStat?.availableBytes ?: -1L
            )
            .put(
                "storage_total_bytes",
                storageStat?.totalBytes ?: -1L
            )
            .put(
                "brightness_percent",
                brightnessPercent
            )
            .put(
                "screen",
                screen
            )
    }

    private fun agentChangeVolume(
        action: String
    ): JSONObject {

        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        val direction =
            when (action) {

                "up" ->
                    AudioManager
                        .ADJUST_RAISE

                "down" ->
                    AudioManager
                        .ADJUST_LOWER

                "mute" ->
                    AudioManager
                        .ADJUST_MUTE

                "unmute" ->
                    AudioManager
                        .ADJUST_UNMUTE

                else ->
                    return toolResult(
                        false,
                        "Неизвестная команда громкости: $action"
                    )
            }

        audioManager
            .adjustStreamVolume(
                AudioManager.STREAM_MUSIC,
                direction,
                AudioManager.FLAG_SHOW_UI
            )

        return toolResult(
            true,
            "Громкость изменена: $action"
        )
    }

    private fun agentYouTubeSearch(
        query: String
    ): JSONObject {
        if (query.isBlank()) {
            return toolResult(
                false,
                "Пустой запрос YouTube"
            )
        }

        return executeAppIntegrationAction(
            appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
            actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
            payload = query
        )
    }

    private fun agentGoogleSearch(
        query: String
    ): JSONObject {
        if (query.isBlank()) {
            return toolResult(
                false,
                "Пустой поисковый запрос"
            )
        }

        return executeAppIntegrationAction(
            appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
            actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
            payload = query
        )
    }

    private fun agentMapSearch(
        query: String
    ): JSONObject {

        if (query.isBlank()) {

            return toolResult(
                false,
                "Пустой запрос для карты"
            )
        }

        val uri =
            Uri.parse(
                "geo:0,0?q=" +
                    Uri.encode(query)
            )

        return try {

            try {

                startActivity(
                    Intent(
                        Intent.ACTION_VIEW,
                        uri
                    ).apply {

                        setPackage(
                            "com.google.android.apps.maps"
                        )

                        addFlags(
                            Intent.FLAG_ACTIVITY_NEW_TASK
                        )
                    }
                )

            } catch (
                _: ActivityNotFoundException
            ) {

                startActivity(
                    Intent(
                        Intent.ACTION_VIEW,
                        uri
                    ).apply {

                        addFlags(
                            Intent.FLAG_ACTIVITY_NEW_TASK
                        )
                    }
                )
            }

            toolResult(
                true,
                "Открыт поиск на карте: $query"
            )

        } catch (
            error: Exception
        ) {

            toolResult(
                false,
                "Не удалось открыть карты: " +
                    (
                        error.message
                            ?: "неизвестная ошибка"
                        )
            )
        }
    }

    /**
     * v12.6 completion evidence collector.
     *
     * Only explicitly named OUTPUT-artifact fields are inspected. We do not scan
     * arbitrary reply text or generic input attachment fields, because a model
     * mentioning a filename or echoing an uploaded input must never prove that a
     * new deliverable was created. Metadata is preserved so Completion Contract
     * can verify requested artifact TYPE as well as existence.
     */
    private fun collectCompletionArtifactEvidence(
        payload: JSONObject
    ): List<AyanaCompletionContract.ArtifactEvidence> {
        val result =
            linkedMapOf<
                String,
                AyanaCompletionContract.ArtifactEvidence
            >()

        val singularKeys =
            linkedMapOf(
                "artifact_reference" to "artifact",
                "artifact_ref" to "artifact",
                "artifact_uri" to "artifact",
                "generated_artifact" to "generated_artifact",
                "generated_file" to "file",
                "output_artifact" to "output_artifact",
                "output_file" to "file",
                "created_artifact" to "created_artifact",
                "created_file" to "file"
            )

        val pluralKeys =
            linkedMapOf(
                "artifact_references" to "artifact",
                "generated_artifacts" to "generated_artifact",
                "generated_files" to "file",
                "output_artifacts" to "output_artifact",
                "output_files" to "file",
                "created_artifacts" to "created_artifact",
                "created_files" to "file"
            )

        fun mergeEvidence(
            evidence: AyanaCompletionContract.ArtifactEvidence
        ) {
            val reference =
                evidence.reference
                    .trim()
                    .take(2048)

            if (reference.isBlank()) {
                return
            }

            val incoming =
                evidence.copy(
                    reference = reference,
                    name = evidence.name.trim().take(512),
                    mimeType = evidence.mimeType.trim().take(160),
                    declaredKind = evidence.declaredKind.trim().take(160)
                )

            val previous =
                result[reference]

            result[reference] =
                if (previous == null) {
                    incoming
                } else {
                    AyanaCompletionContract.ArtifactEvidence(
                        reference = reference,
                        name = incoming.name.ifBlank { previous.name },
                        mimeType = incoming.mimeType.ifBlank { previous.mimeType },
                        declaredKind = incoming.declaredKind.ifBlank { previous.declaredKind }
                    )
                }
        }

        fun firstString(
            value: JSONObject,
            keys: List<String>
        ): String {
            for (key in keys) {
                val candidate =
                    value.optString(key)
                        .trim()

                if (candidate.isNotBlank()) {
                    return candidate
                }
            }

            return ""
        }

        fun addValue(
            value: Any?,
            declaredHint: String,
            depth: Int = 0
        ) {
            if (
                value == null ||
                value === JSONObject.NULL ||
                depth > 4 ||
                result.size >= 24
            ) {
                return
            }

            when (value) {
                is String -> {
                    mergeEvidence(
                        AyanaCompletionContract.ArtifactEvidence(
                            reference = value,
                            declaredKind = declaredHint
                        )
                    )
                }

                is JSONArray -> {
                    for (index in 0 until value.length()) {
                        if (result.size >= 24) break

                        addValue(
                            value.opt(index),
                            declaredHint,
                            depth + 1
                        )
                    }
                }

                is JSONObject -> {
                    val reference =
                        firstString(
                            value,
                            listOf(
                                "reference",
                                "ref",
                                "uri",
                                "artifact_uri",
                                "file_uri",
                                "content_uri",
                                "path"
                            )
                        )

                    if (reference.isNotBlank()) {
                        mergeEvidence(
                            AyanaCompletionContract.ArtifactEvidence(
                                reference = reference,
                                name =
                                    firstString(
                                        value,
                                        listOf(
                                            "filename",
                                            "file_name",
                                            "display_name",
                                            "name"
                                        )
                                    ),
                                mimeType =
                                    firstString(
                                        value,
                                        listOf(
                                            "mime_type",
                                            "mime",
                                            "content_type"
                                        )
                                    ),
                                declaredKind =
                                    firstString(
                                        value,
                                        listOf(
                                            "artifact_type",
                                            "file_type",
                                            "declared_kind",
                                            "kind",
                                            "type"
                                        )
                                    )
                                        .ifBlank { declaredHint }
                            )
                        )
                    }

                    // Some execution layers wrap the actual output object/array
                    // one level below an explicitly output-named field. Recurse
                    // only inside that already-trusted output envelope.
                    listOf(
                        "artifact",
                        "file",
                        "output",
                        "result",
                        "data",
                        "items",
                        "files",
                        "artifacts"
).forEach { key ->
                        if (value.has(key)) {
                            addValue(
                                value.opt(key),
                                declaredHint,
                                depth + 1
                            )
                        }
                    }
                }
            }
        }

        singularKeys.forEach { (key, hint) ->
            if (payload.has(key)) {
                addValue(
                    payload.opt(key),
                    hint
                )
            }
        }

        pluralKeys.forEach { (key, hint) ->
            if (payload.has(key)) {
                addValue(
                    payload.opt(key),
                    hint
                )
            }
        }

        return result.values.toList()
    }

    private fun mergeCompletionArtifactEvidence(
        target: MutableMap<
            String,
            AyanaCompletionContract.ArtifactEvidence
        >,
        incoming: AyanaCompletionContract.ArtifactEvidence
    ) {
        val reference =
            incoming.reference
                .trim()

        if (reference.isBlank()) {
            return
        }

        val previous =
            target[reference]

        target[reference] =
            if (previous == null) {
                incoming
            } else {
                AyanaCompletionContract.ArtifactEvidence(
                    reference = reference,
                    name = incoming.name.ifBlank { previous.name },
                    mimeType = incoming.mimeType.ifBlank { previous.mimeType },
                    declaredKind = incoming.declaredKind.ifBlank { previous.declaredKind }
                )
            }
    }

    // =========================================================
    // MARIN TTS
    // =========================================================

    private fun speakAndResume(
        text: String,
        historySuccess: Boolean,
        historyTerminalStatus: String? = null,
        historyTechnical: String = ""
    ) {

        if (text.isBlank()) {
            finishActiveCommandHistory(
                success = historySuccess,
                result = text,
                technical = historyTechnical,
                terminalStatus = historyTerminalStatus
            )

            startFollowUpOrWake()
            return
        }

        val speechPreparation =
            russianSpeechNormalizer
                .prepare(
                    text
                )

        val spokenText =
            speechPreparation.text
                .ifBlank {
                    text
                }

        stopSherpaListening()

        listenMode =
            ListenMode.BUSY

        broadcastStatus(
            "Говорю…",
            STATE_SPEAKING
        )

        updateNotification(
            "AYANA отвечает"
        )

        val token =
            ++audioToken

        // Stop/release any previous output BEFORE publishing the new TTS text.
        // v8.9 did this in the opposite order, so stopCurrentAudio() erased the
        // reference transcript used by the self-echo protection.
        stopCurrentAudio(
            keepToken = true
        )

        activeTtsTextNormalized =
            normalizeRecognitionText(
                spokenText
            )

        if (speechPreparation.changed) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "speech_normalization",
                message = "Русское произношение подготовлено для Marin",
                details =
                    (
                        "rules=${speechPreparation.appliedRules.joinToString(",")}; " +
                            "semantic_chars=${text.length}; spoken_chars=${spokenText.length}"
                        ).take(900)
            )
        }

        bargeInAudioDiagnosticLogged =
            false

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "presentation_phase",
            message = "tts_stream",
            details =
                "executor=tts_executor; semantic_terminal=${executionKernel.current()?.terminalStatus?.name.orEmpty()}"
        )

        enterCommunicationAudioMode()

        // The cancel microphone is started only after the communication audio
        // mode is active, so VOICE_COMMUNICATION + AEC can share one route.
        startCancelListening()

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "tts_request",
            message = "Marin: потоковый запрос голоса отправлен",
            details =
                "voice=$TTS_EXPECTED_VOICE; " +
                    "profile=$TTS_VOICE_PROFILE; " +
                    "speed=$TTS_EXPECTED_SPEED; " +
                    "speech_normalized=${speechPreparation.changed}"
        )

        thread(
            start = true,
            name = "AyanaTTSStream"
        ) {
            streamTtsPcmAndPlay(
                semanticText = text,
                spokenText = spokenText,
                token = token,
                historySuccess = historySuccess,
                historyTerminalStatus = historyTerminalStatus,
                historyTechnical = historyTechnical
            )
        }
    }

    private fun streamTtsPcmAndPlay(
        semanticText: String,
        spokenText: String,
        token: Long,
        historySuccess: Boolean,
        historyTerminalStatus: String? = null,
        historyTechnical: String = ""
    ) {

        var connection:
            HttpsURLConnection? = null

        var track:
            AudioTrack? = null

        var completedNormally =
            false

        // Android HttpsURLConnection can pool a fully consumed response
        // transport. Explicit disconnect on every successful Marin turn
        // defeats that reuse and forces avoidable TLS/connect work. Cancellation,
        // errors and partial streams still disconnect immediately.
        var transportReusable =
            false

        var totalBytes =
            0L

        var firstByteLatencyMs =
            -1L

        val requestStartedAt =
            SystemClock.elapsedRealtime()

        var requestBodySentAt =
            requestStartedAt

        var responseHeadersAt =
            requestStartedAt

        try {
            val url =
                URL(
                    "$WORKER_URL/tts"
                )

            connection =
                url.openConnection()
                    as HttpsURLConnection

            currentTtsConnection =
                connection
            executionKernel.bindConnection(connection)

            connection.requestMethod =
                "POST"

            connection.setRequestProperty(
                "Content-Type",
                "application/json"
            )

            connection.setRequestProperty(
                "Accept",
                "application/octet-stream"
            )

            connection.connectTimeout =
                TTS_CONNECT_TIMEOUT_MS

            connection.readTimeout =
                TTS_READ_TIMEOUT_MS

            connection.doOutput =
                true

            val requestJson =
                JSONObject().apply {
                    put(
                        "text",
                        spokenText
                    )

                    put(
                        "format",
                        "pcm"
                    )

                    put(
                        "voice_profile",
                        TTS_VOICE_PROFILE
                    )
                }

            val requestBytes =
                requestJson
                    .toString()
                    .toByteArray(
                        Charsets.UTF_8
                    )

            // v12.6: the request body size is known before connect. Avoid
            // chunked request framing so the Worker can begin processing as soon
            // as the fixed body is written. The dominant latency remains server/
            // transport response-header wait and is measured below.
            connection.setFixedLengthStreamingMode(
                requestBytes.size
            )

            connection.outputStream
                .use { output ->
                    output.write(
                        requestBytes
                    )
                }

            requestBodySentAt =
                SystemClock.elapsedRealtime()

            val responseCode =
                connection.responseCode

            responseHeadersAt =
                SystemClock.elapsedRealtime()

            if (
                responseCode !in
                200..299
            ) {
                val errorBody =
                    try {
                        connection.errorStream
                            ?.bufferedReader()
                            ?.use {
                                it.readText()
                            }
                            .orEmpty()
                            .take(500)
                    } catch (_: Exception) {
                        ""
                    }

                throw IllegalStateException(
                    "TTS HTTP $responseCode ${errorBody.trim()}"
                        .trim()
                )
            }

            verifyTtsVoiceContract(
                connection
            )

            val minBuffer =
                AudioTrack.getMinBufferSize(
                    TTS_PCM_SAMPLE_RATE_HZ,
                    AudioFormat.CHANNEL_OUT_MONO,
                    AudioFormat.ENCODING_PCM_16BIT
                )

            if (minBuffer <= 0) {
                throw IllegalStateException(
                    "AudioTrack minBuffer=$minBuffer"
                )
            }

            val builtTrack =
                AudioTrack.Builder()
                    .setAudioAttributes(
                        AudioAttributes.Builder()
                            .setUsage(
                                AudioAttributes.USAGE_VOICE_COMMUNICATION
                            )
                            .setContentType(
                                AudioAttributes.CONTENT_TYPE_SPEECH
                            )
                            .build()
                    )
                    .setAudioFormat(
                        AudioFormat.Builder()
                            .setEncoding(
                                AudioFormat.ENCODING_PCM_16BIT
                            )
                            .setSampleRate(
                                TTS_PCM_SAMPLE_RATE_HZ
                            )
                            .setChannelMask(
                                AudioFormat.CHANNEL_OUT_MONO
                            )
                            .build()
                    )
                    .setBufferSizeInBytes(
                        maxOf(
                            minBuffer * 4,
                            TTS_STREAM_BUFFER_BYTES
                        )
                    )
                    .setTransferMode(
                        AudioTrack.MODE_STREAM
                    )
                    .build()

            if (
                builtTrack.state !=
                AudioTrack.STATE_INITIALIZED
            ) {
                builtTrack.release()
                throw IllegalStateException(
                    "AudioTrack not initialized"
                )
            }

            builtTrack.setVolume(
                BARGE_IN_TTS_VOLUME
            )

            track =
                builtTrack

            audioTrack =
                builtTrack

            // PCM16 mono uses 2 bytes per frame. HTTP chunk boundaries are not
            // guaranteed to be frame-aligned, so preserve one trailing byte and
            // prepend it to the next network chunk instead of feeding an odd byte
            // count to AudioTrack.
            val networkBuffer =
                ByteArray(
                    TTS_STREAM_BUFFER_BYTES
                )

            val alignedBuffer =
                ByteArray(
                    TTS_STREAM_BUFFER_BYTES +
                        TTS_PCM_BYTES_PER_FRAME
                )

            var pendingByte: Byte? =
                null

            var firstAudioByte =
                true

            connection.inputStream
                .use { input ->
                    while (
                        token == audioToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        val read =
                            input.read(
                                networkBuffer
                            )

                        if (read < 0) {
                            if (pendingByte != null) {
                                throw IllegalStateException(
                                    "PCM stream ended mid-frame"
                                )
                            }

                            completedNormally =
                                true
                            break
                        }

                        if (read == 0) {
                            continue
                        }

                        var alignedCount =
                            0

                        pendingByte
                            ?.let { carry ->
                                alignedBuffer[0] =
                                    carry

                                alignedCount =
                                    1

                                pendingByte =
                                    null
                            }

                        System.arraycopy(
                            networkBuffer,
                            0,
                            alignedBuffer,
                            alignedCount,
                            read
                        )

                        alignedCount +=
                            read

                        if (
                            alignedCount %
                            TTS_PCM_BYTES_PER_FRAME !=
                            0
                        ) {
                            pendingByte =
                                alignedBuffer[
                                    alignedCount -
                                        1
                                ]

                            alignedCount--
                        }

                        if (alignedCount <= 0) {
                            continue
                        }

                        if (firstAudioByte) {
                            firstAudioByte =
                                false

                            val firstByteMs =
                                SystemClock.elapsedRealtime() -
                                    requestStartedAt

                            firstByteLatencyMs =
                                firstByteMs

                            val requestWriteMs =
                                (requestBodySentAt - requestStartedAt)
                                    .coerceAtLeast(0L)

                            val responseHeaderWaitMs =
                                (responseHeadersAt - requestBodySentAt)
                                    .coerceAtLeast(0L)

                            val firstChunkAfterHeadersMs =
                                (
                                    SystemClock.elapsedRealtime() -
                                        responseHeadersAt
                                    )
                                    .coerceAtLeast(0L)

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "tts_first_byte",
                                message = "Marin: первый PCM-байт получен",
                                details =
                                    "latency_ms=$firstByteMs; " +
                                        "request_write_ms=$requestWriteMs; " +
                                        "response_header_wait_ms=$responseHeaderWaitMs; " +
                                        "first_chunk_after_headers_ms=$firstChunkAfterHeadersMs"
                            )

                            builtTrack.play()

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "tts_play",
                                message = "Marin: потоковое воспроизведение начато"
                            )
                        }

                        var offset =
                            0

                        while (
                            offset < alignedCount &&
                            token == audioToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            val written =
                                builtTrack.write(
                                    alignedBuffer,
                                    offset,
                                    alignedCount - offset,
                                    AudioTrack.WRITE_BLOCKING
                                )

                            if (written < 0) {
                                throw IllegalStateException(
                                    "AudioTrack write=$written"
                                )
                            }

                            if (written == 0) {
                                Thread.yield()
                                continue
                            }

                            offset +=
                                written

                            totalBytes +=
                                written.toLong()
                        }
                    }
                }

            if (
                completedNormally &&
                totalBytes <=
                0L
            ) {
                throw IllegalStateException(
                    "TTS PCM stream was empty"
                )
            }

            if (
                completedNormally &&
                token == audioToken &&
                !cancelRequested &&
                !shuttingDown
            ) {
                waitForAudioTrackDrain(
                    builtTrack,
                    totalBytes,
                    token
                )

                // The response reached EOF and the stream was closed normally.
                // Do not call disconnect(): allow the platform connection pool to
                // reuse the authenticated HTTPS transport for the next Marin turn.
                transportReusable =
                    true
            }

        } catch (error: Exception) {
            if (
                token == audioToken &&
                !cancelRequested &&
                !shuttingDown
            ) {
                val technical =
                    ttsTechnicalError(
                        error
                    )

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "tts_error",
                    message = "Marin: ошибка потокового TTS",
                    details = technical
                )

                capabilityRegistry.recordTtsResult(
                    success = false,
                    firstByteMs = firstByteLatencyMs,
                    error = technical
                )

                mainHandler.post {
                    if (
                        token == audioToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "presentation_error",
                            message = "Marin недоступен после semantic terminal",
                            details = technical
                        )

                        finishActiveCommandHistory(
                            success = historySuccess,
                            result = semanticText,
                            technical = historyTechnical,
                            terminalStatus = historyTerminalStatus
                        )

                        broadcastStatus(
                            if (historySuccess) {
                                semanticText
                            } else {
                                "Голос временно недоступен"
                            },
                            if (historySuccess) {
                                STATE_SUCCESS
                            } else {
                                STATE_ERROR
                            }
                        )

                        mainHandler.postDelayed(
                            {
                                startWakeListening()
                            },
                            700L
                        )
                    }
                }
            }
        } finally {
            if (
                currentTtsConnection ===
                connection
            ) {
                currentTtsConnection =
                    null
            }

            executionKernel.clearConnection(connection)

            if (!transportReusable) {
                try {
                    connection?.disconnect()
                } catch (_: Exception) {
                }
            }

            releaseAudioTrack(
                track
            )

            exitCommunicationAudioMode()
        }

        if (
            completedNormally &&
            token == audioToken &&
            !cancelRequested &&
            !shuttingDown
        ) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "tts_complete",
                message = "Marin: поток полностью воспроизведён",
                details =
                    "pcm_bytes=$totalBytes; " +
                        "https_pool_reusable=$transportReusable"
            )

            capabilityRegistry.recordTtsResult(
                success = true,
                firstByteMs = firstByteLatencyMs,
                error = ""
            )

            mainHandler.post {
                if (
                    token == audioToken &&
                    !cancelRequested &&
                    !shuttingDown
                ) {
                    finishActiveCommandHistory(
                        success = historySuccess,
                        result = semanticText,
                        technical = historyTechnical,
                        terminalStatus = historyTerminalStatus
                    )

                    startFollowUpOrWake()
                }
            }
        }
    }

    private fun waitForAudioTrackDrain(
        track: AudioTrack,
        totalBytes: Long,
        token: Long
    ) {

        val targetFrames =
            totalBytes /
                TTS_PCM_BYTES_PER_FRAME

        val deadline =
            SystemClock.elapsedRealtime() +
                TTS_DRAIN_MAX_WAIT_MS

        while (
            token == audioToken &&
            !cancelRequested &&
            !shuttingDown &&
            SystemClock.elapsedRealtime() <
            deadline
        ) {
            val playedFrames =
                track.playbackHeadPosition
                    .toLong()
                    .and(
                        0xffffffffL
                    )

            if (
                playedFrames >=
                targetFrames
            ) {
                break
            }

            try {
                Thread.sleep(
                    20L
                )
            } catch (_: InterruptedException) {
                break
            }
        }
    }

    private fun ttsTechnicalError(
        error: Exception
    ): String {

        val kind =
            when (error) {
                is SocketTimeoutException ->
                    "SocketTimeoutException"

                else ->
                    error.javaClass.simpleName
            }

        val message =
            error.message
                .orEmpty()
                .replace(
                    "\\n",
                    " "
                )
                .take(320)

        return if (message.isBlank()) {
            "TTS stream failed: $kind"
        } else {
            "TTS stream failed: $kind: $message"
        }
    }

    private fun enterCommunicationAudioMode() {
        try {
            val manager =
                getSystemService(
                    Context.AUDIO_SERVICE
                ) as AudioManager

            if (!communicationAudioModeOwned) {
                previousAudioMode =
                    manager.mode

                communicationAudioModeOwned =
                    true
            }

            if (
                manager.mode !=
                AudioManager.MODE_IN_COMMUNICATION
            ) {
                manager.mode =
                    AudioManager.MODE_IN_COMMUNICATION
            }

        } catch (_: Exception) {
        }
    }

    private fun exitCommunicationAudioMode() {
        if (!communicationAudioModeOwned) {
            return
        }

        try {
            val manager =
                getSystemService(
                    Context.AUDIO_SERVICE
                ) as AudioManager

            val restore =
                previousAudioMode
                    ?: AudioManager.MODE_NORMAL

            manager.mode =
                restore

        } catch (_: Exception) {
        } finally {
            previousAudioMode =
                null

            communicationAudioModeOwned =
                false
        }
    }

    private fun audioSourceName(
        source: Int
    ): String =
        when (source) {
            MediaRecorder.AudioSource.VOICE_COMMUNICATION ->
                "VOICE_COMMUNICATION"

            MediaRecorder.AudioSource.VOICE_RECOGNITION ->
                "VOICE_RECOGNITION"

            MediaRecorder.AudioSource.MIC ->
                "MIC"

            else ->
                "UNKNOWN($source)"
        }

    private fun releaseAudioTrack(
        track: AudioTrack?
    ) {
        if (track == null) {
            return
        }

        if (
            audioTrack ===
            track
        ) {
            audioTrack =
                null
        }

        try {
            if (
                track.playState ==
                AudioTrack.PLAYSTATE_PLAYING
            ) {
                track.pause()
                track.flush()
                track.stop()
            }
        } catch (_: Exception) {
        }

        try {
            track.release()
        } catch (_: Exception) {
        }
    }

    private fun verifyTtsVoiceContract(
        connection: HttpsURLConnection
    ) {
        val voice =
            connection
                .getHeaderField(
                    "X-Ayana-Voice"
                )
                ?.trim()
                ?.lowercase(
                    Locale.ROOT
                )
                .orEmpty()

        val profile =
            connection
                .getHeaderField(
                    "X-Ayana-Voice-Profile"
                )
                ?.trim()
                .orEmpty()

        val speed =
            connection
                .getHeaderField(
                    "X-Ayana-Voice-Speed"
                )
                ?.trim()
                .orEmpty()

        if (
            voice !=
            TTS_EXPECTED_VOICE ||
            profile !=
            TTS_VOICE_PROFILE ||
            speed !=
            TTS_EXPECTED_SPEED
        ) {
            throw IllegalStateException(
                "TTS voice contract mismatch: " +
                    "voice=${voice.ifBlank { "missing" }}; " +
                    "profile=${profile.ifBlank { "missing" }}; " +
                    "speed=${speed.ifBlank { "missing" }}"
            )
        }
    }

    private fun downloadTtsToFile(
        text: String,
        target: File
    ) {

        var connection:
            HttpsURLConnection? = null

        try {

            val url =
                URL(
                    "$WORKER_URL/tts"
                )

            connection =
                url.openConnection()
                    as HttpsURLConnection

            connection.requestMethod =
                "POST"

            connection.setRequestProperty(
                "Content-Type",
                "application/json"
            )

            connection.connectTimeout =
                15000

            connection.readTimeout =
                45000
connection.doOutput =
                true

            val spokenText =
                russianSpeechNormalizer
                    .prepare(
                        text
                    )
                    .text
                    .ifBlank {
                        text
                    }

            val requestJson =
                JSONObject().apply {

                    put(
                        "text",
                        spokenText
                    )

                    // Wake acknowledgement is intentionally cached as MP3,
                    // but it uses the exact same locked Marin voice profile and
                    // speed as every other AYANA spoken response.
                    put(
                        "format",
                        "mp3"
                    )

                    put(
                        "voice_profile",
                        TTS_VOICE_PROFILE
                    )
                }

            connection.outputStream
                .use { output ->

                    output.write(
                        requestJson
                            .toString()
                            .toByteArray(
                                Charsets.UTF_8
                            )
                    )
                }

            val responseCode =
                connection
                    .responseCode

            if (
                responseCode !in
                200..299
            ) {

                throw IllegalStateException(
                    "TTS HTTP $responseCode"
                )
            }

            verifyTtsVoiceContract(
                connection
            )

            connection.inputStream
                .use { input ->

                    target.outputStream()
                        .use { output ->

                            input.copyTo(
                                output
                            )
                        }
                }

        } finally {

            connection
                ?.disconnect()
        }
    }

    private fun playFile(
        file: File,
        deleteAfter: Boolean,
        onFinished: () -> Unit
    ) {

        stopCurrentAudio(
            keepToken = true
        )

        val player =
            MediaPlayer()

        mediaPlayer =
            player

        try {

            // The cached wake acknowledgement must sound through the same speech
            // playback profile as streamed Marin. Different Android audio usage or
            // volume can make the very same generated voice sound like another
            // speaker, so keep those parameters aligned as well.
            player.setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(
                        AudioAttributes.USAGE_VOICE_COMMUNICATION
                    )
                    .setContentType(
                        AudioAttributes.CONTENT_TYPE_SPEECH
                    )
                    .build()
            )

            player.setDataSource(
                file.absolutePath
            )

            player.setOnPreparedListener {
                    prepared ->

                try {

                    prepared.setVolume(
                        BARGE_IN_TTS_VOLUME,
                        BARGE_IN_TTS_VOLUME
                    )

                    prepared.start()

                } catch (_: Exception) {

                    releasePlayer(
                        prepared,
                        file,
                        deleteAfter
                    )

                    onFinished()
                }
            }

            player.setOnCompletionListener {
                    completed ->

                releasePlayer(
                    completed,
                    file,
                    deleteAfter
                )

                onFinished()
            }

            player.setOnErrorListener {
                    failed,
                    _,
                    _ ->

                releasePlayer(
                    failed,
                    file,
                    deleteAfter
                )

                onFinished()

                true
            }

            player.prepareAsync()

        } catch (_: Exception) {

            releasePlayer(
                player,
                file,
                deleteAfter
            )

            onFinished()
        }
    }

    private fun releasePlayer(
        player: MediaPlayer,
        file: File,
        deleteAfter: Boolean
    ) {

        if (
            mediaPlayer === player
        ) {

            mediaPlayer =
                null

            activeTtsTextNormalized =
                ""
        }

        try {
            player.release()
        } catch (_: Exception) {
        }

        if (deleteAfter) {

            file.delete()
        }
    }

    private fun stopCurrentAudio(
        keepToken: Boolean =
            false
    ) {

        if (!keepToken) {
            audioToken++
        }

        val ttsConnection =
            currentTtsConnection

        currentTtsConnection =
            null

        try {
            ttsConnection?.disconnect()
        } catch (_: Exception) {
        }

        val track =
            audioTrack

        audioTrack =
            null

        if (track != null) {
            try {
                if (
                    track.playState ==
                    AudioTrack.PLAYSTATE_PLAYING
                ) {
                    track.pause()
                    track.flush()
                    track.stop()
                }
            } catch (_: Exception) {
            }

            try {
                track.release()
            } catch (_: Exception) {
            }
        }

        val player =
            mediaPlayer

        mediaPlayer =
            null

        activeTtsTextNormalized =
            ""

        if (player != null) {
            try {
                if (player.isPlaying) {
                    player.stop()
                }
            } catch (_: Exception) {
            }

            try {
                player.release()
            } catch (_: Exception) {
            }
        }

        exitCommunicationAudioMode()
    }

    // =========================================================
    // COMMAND HISTORY / DIAGNOSTICS
    // =========================================================

    private fun kernelStatusFor(
        success: Boolean,
        terminalStatus: String?
    ): AyanaExecutionKernel.TerminalStatus =
        when {
            terminalStatus == AyanaCommandHistoryStore.STATUS_BLOCKED ->
                AyanaExecutionKernel.TerminalStatus.BLOCKED

            terminalStatus == AyanaCommandHistoryStore.STATUS_UNSUPPORTED ->
                AyanaExecutionKernel.TerminalStatus.UNSUPPORTED

            success ->
                AyanaExecutionKernel.TerminalStatus.SUCCESS

            else ->
                AyanaExecutionKernel.TerminalStatus.ERROR
        }

    private fun commitExecutionTerminal(
        success: Boolean,
        result: String,
        technical: String = "",
        terminalStatus: String? = null
    ) {
        val id =
            activeCommandHistoryId
                ?: return

        val current =
            executionKernel.current()

        if (
            current != null &&
            current.terminalStatus !=
            AyanaExecutionKernel.TerminalStatus.RUNNING
        ) {
            return
        }

        val kernelStatus =
            kernelStatusFor(
                success = success,
                terminalStatus = terminalStatus
            )

        val kernelReason =
            technical
                .trim()
                .ifBlank {
                    when {
                        terminalStatus == AyanaCommandHistoryStore.STATUS_BLOCKED ->
                            "command_blocked"

                        terminalStatus == AyanaCommandHistoryStore.STATUS_UNSUPPORTED ->
                            "command_unsupported"

                        !success ->
                            "command_failed"

                        else ->
                            "command_completed"
                    }
                }

        executionKernel.complete(
            status = kernelStatus,
            reason = kernelReason.take(600)
        )

        commandHistoryStore.addEvent(
            id,
            state = "execution_terminal",
            message = kernelStatus.name,
            details = executionKernel.diagnosticSummary().take(1000)
        )
    }

    private fun finishActiveCommandHistory(
        success: Boolean,
        result: String,
        technical: String = "",
        terminalStatus: String? = null
    ) {
        val id =
            activeCommandHistoryId
                ?: return

        commitExecutionTerminal(
            success = success,
            result = result,
            technical = technical,
            terminalStatus = terminalStatus
        )

        when (terminalStatus) {
            AyanaCommandHistoryStore.STATUS_BLOCKED ->
                commandHistoryStore.finishBlocked(
                    id = id,
                    result = result,
                    technical = technical
                )

            AyanaCommandHistoryStore.STATUS_UNSUPPORTED ->
                commandHistoryStore.finishUnsupported(
                    id = id,
                    result = result,
                    technical = technical
                )

            else ->
                commandHistoryStore.finish(
                    id = id,
                    success = success,
                    result = result,
                    technical = technical
                )
        }

        activeCommandHistoryId =
            null

        pendingPresentationSuccess =
            false
        pendingPresentationResult =
            ""
        pendingPresentationTechnical =
            ""
        pendingPresentationTerminalStatus =
            null
        pendingCancelSource =
            ""
    }

    private fun finishDeferredCancellationFromExecutor(
        source: String
    ) {
        val id =
            activeCommandHistoryId
                ?: run {
                    cancelRequested =
                        false
                    startWakeListening()
                    return
                }

        executionKernel.complete(
            status =
                AyanaExecutionKernel.TerminalStatus.CANCELLED,
            reason =
                "cancel_source=$source"
        )

        commandHistoryStore.addEvent(
            id,
            state = "execution_terminal",
            message = "CANCELLED",
            details =
                executionKernel
                    .diagnosticSummary()
                    .take(1000)
        )

        commandHistoryStore.finishCancelled(
            id = id,
            result = "Команда остановлена пользователем",
            source = source
        )

        activeCommandHistoryId =
            null

        broadcastStatus(
            "Команда остановлена",
            STATE_CANCELLED
        )

        updateNotification(
            "Команда остановлена • AYANA остаётся активной"
        )

        resumeAfterCancellation(
            attempt = 0
        )
    }

    private fun isCommandCancelled(
        token: Long
    ): Boolean {

        return cancelRequested ||
            executionKernel.isCancelled() ||
            shuttingDown ||
            token !=
            activeCommandToken
    }

    private fun isLocalOrbControlCommand(
        value: String
    ): Boolean {

        val normalized =
            value
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )

        val mentionsOrb =
            normalized.contains(
                "orb"
            ) ||
                normalized.contains(
                    "орб"
                )

        if (
            !mentionsOrb
        ) {
            return false
        }

        return listOf(
            "остав",
            "покаж",
            "включ",
            "верни",
            "поверх",
            "не скры",
            "один знач",
            "одну кноп"
        ).any {
            normalized.contains(
                it
            )
        }
    }

    /**
     * v12.5 compatibility wrappers. The actual grammar lives in
     * AyanaCancelPhraseDetector so SPEAKING and non-SPEAKING paths cannot drift.
     */
    private fun isBargeInCancelPhrase(
        value: String
    ): Boolean =
        cancelPhraseDetector
            .detect(
                value = value,
                speaking = true,
                activeSpokenText = activeTtsTextNormalized
            )
            .matched

    private fun isCancelCommandPhrase(
        value: String
    ): Boolean =
        cancelPhraseDetector
            .detect(
                value = value,
                speaking = false
            )
            .matched

    private fun isShutdownAyanaPhrase(
        value: String
    ): Boolean {

        val normalized =
            normalizeRecognitionText(
                value
            )
                .trim()

        val withoutWake =
            removeLeadingWakeWord(
                normalized
            )

        return withoutWake in
            setOf(
                "отключись",
                "выключись",
                "останови аяну",
                "останови айану",
                "выключи аяну",
                "выключи айану",
                "отключи аяну",
                "отключи айану"
            )
    }

    private fun removeLeadingWakeWord(
        value: String
    ): String {

        var result =
            value.trim()

        for (
            wake in
            WAKE_VARIANTS
        ) {

            if (
                result ==
                wake
            ) {
                return ""
            }

            if (
                result.startsWith(
                    "$wake "
                )
            ) {

                result =
                    result
                        .removePrefix(
                            "$wake "
                        )
                        .trim()

                break
            }
        }

        return result
    }

    private fun cancelCurrentCommand(
        source: String
    ) {

        if (
            shuttingDown ||
            !isRunning
        ) {
            return
        }

        val hadActiveCommand =
            activeCommandHistoryId !=
                null ||
                currentAgentThread?.isAlive ==
                true ||
                currentStatusState in
                setOf(
                    STATE_THINKING,
                    STATE_EXECUTING,
                    STATE_SPEAKING,
                    STATE_COMMAND
                )

        if (!hadActiveCommand) {
            return
        }

        val executionSnapshot =
            executionKernel.current()

        val semanticAlreadyTerminal =
            executionSnapshot != null &&
                executionSnapshot.terminalStatus !=
                AyanaExecutionKernel.TerminalStatus.RUNNING

        // v12.2 terminal ownership: once semantic execution is terminal,
        // spoken STOP owns presentation only.
        if (
            currentStatusState ==
            STATE_SPEAKING &&
            semanticAlreadyTerminal &&
            activeCommandHistoryId !=
            null
        ) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "presentation_cancelled",
                message = "Marin остановлен пользователем после semantic terminal",
                details =
                    "source=$source; semantic_terminal=${executionSnapshot?.terminalStatus?.name.orEmpty()}"
            )

            stopCancelListenerWatchdog()
            stopCurrentAudio()
            stopSherpaListening()

            val semanticSuccess =
                pendingPresentationSuccess
            val semanticResult =
                pendingPresentationResult
                    .ifBlank {
                        "Команда завершена"
                    }
            val semanticTechnical =
                pendingPresentationTechnical
            val semanticTerminalStatus =
                pendingPresentationTerminalStatus

            finishActiveCommandHistory(
                success = semanticSuccess,
                result = semanticResult,
                technical = semanticTechnical,
                terminalStatus = semanticTerminalStatus
            )

            broadcastStatus(
                semanticResult,
                if (semanticSuccess) {
                    STATE_SUCCESS
                } else {
                    STATE_ERROR
                }
            )

            updateNotification(
                "Голос остановлен • результат команды сохранён"
            )

            mainHandler.postDelayed(
                {
                    if (
                        !shuttingDown &&
                        isRunning
                    ) {
                        startWakeListening()
                    }
                },
                180L
            )
            return
        }

        val deferTerminalToSideEffectExecutor =
            executionSnapshot?.terminalStatus ==
                AyanaExecutionKernel.TerminalStatus.RUNNING &&
                (
                    executionSnapshot.executor ==
                        "app_task_removal_executor" ||
                        executionSnapshot.sideEffectState in
                        setOf(
                            AyanaExecutionKernel.SideEffectState.DISPATCHING,
                            AyanaExecutionKernel.SideEffectState.DISPATCHED,
                            AyanaExecutionKernel.SideEffectState.RECONCILING,
                            AyanaExecutionKernel.SideEffectState.VERIFIED_COMMITTED
                        )
                    )

        cancelRequested =
            true
        pendingCancelSource =
            source

        val cancelledExecution =
            if (deferTerminalToSideEffectExecutor) {
                executionKernel.requestCancel(
                    reason = "cancel_source=$source"
                )
            } else {
                executionKernel.cancel(
                    reason = "cancel_source=$source"
                )
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (deferTerminalToSideEffectExecutor) {
                    "execution_cancel_requested"
                } else {
                    "execution_cancelled"
                },
            message =
                if (deferTerminalToSideEffectExecutor) {
                    "STOP принят после side-effect boundary; ожидаю фактический terminal"
                } else {
                    "Execution Session остановлена"
                },
            details =
                "execution_id=${cancelledExecution?.id.orEmpty()}; " +
                    "lane=${cancelledExecution?.lane.orEmpty()}; " +
                    "executor=${cancelledExecution?.executor.orEmpty()}; source=$source"
        )

        stopCancelListenerWatchdog()
        stopCurrentAudio()
        stopSherpaListening()

        if (deferTerminalToSideEffectExecutor) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "side_effect_reconciliation_wait",
                message = "STOP принят; ожидаю фактический результат side-effect executor",
                details =
                    "execution_id=${cancelledExecution?.id.orEmpty()}; " +
                        "side_effect=${cancelledExecution?.sideEffectState?.name.orEmpty()}"
            )

            broadcastStatus(
                "Останавливаю выполнение…",
                STATE_EXECUTING
            )

            updateNotification(
                "Останавливаю действие • проверяю фактический результат"
            )

            return
        }

        // Non-side-effect lanes preserve the old immediate resource cancellation.
        try {
            currentAgentConnection
                ?.disconnect()
        } catch (_: Exception) {
        }

        try {
            currentAgentThread
                ?.interrupt()
        } catch (_: Exception) {
        }

        commandGeneration++

        val durableId =
            currentDurableGoalId

        if (durableId != null) {
            try {
                durableGoalStore
                    .markCancelled(
                        durableId,
                        "Команда остановлена пользователем ($source)"
                    )
            } catch (error: Exception) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "goal_store_error",
                    message = "STOP выполнен, но durable-cancel не записан",
                    details = error.message.orEmpty().take(220)
                )
            } finally {
                currentDurableGoalId =
                    null
            }
        }

        val historyId =
            activeCommandHistoryId

        if (historyId != null) {
            commandHistoryStore.finishCancelled(
                id = historyId,
                result = "Команда остановлена пользователем",
                source = source
            )

            activeCommandHistoryId =
                null
        }

        agentPreviousResponseId =
            null

        broadcastStatus(
            "Команда остановлена",
            STATE_CANCELLED
        )

        updateNotification(
            "Команда остановлена • AYANA остаётся активной"
        )

        resumeAfterCancellation(
            attempt = 0
        )
    }

    private fun resumeAfterCancellation(
        attempt: Int
    ) {

        if (
            shuttingDown ||
            !isRunning
        ) {
            return
        }

        if (
            currentAgentThread?.isAlive ==
            true &&
            attempt <
            CANCEL_THREAD_WAIT_ATTEMPTS
        ) {

            mainHandler.postDelayed(
                {
                    resumeAfterCancellation(
                        attempt +
                            1
                    )
                },
                CANCEL_THREAD_WAIT_STEP_MS
            )

            return
        }

        cancelRequested =
            false
        pendingCancelSource =
            ""

        mainHandler.postDelayed(
            {
                if (
                    !shuttingDown &&
                    isRunning
                ) {
                    startWakeListening()
                }
            },
            180L
        )
    }

    // =========================================================
    // STATUS
    // =========================================================

    private fun broadcastStatus(
        text: String,
        state: String
    ) {

        currentStatusText =
            text

        currentStatusState =
            state

        // Command history is command-scoped. Background wake-listening can
        // legitimately restart while another text/network path is still finishing,
        // but that ambient state must not appear as an event inside the command.
        if (state != STATE_LISTENING) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = state,
                message = text
            )
        }

        // STOPPED must never create/refresh an overlay. This is the critical
        // guard that prevents repeated STOP actions from multiplying Orbs.
        val updateOrb =
            {
                if (
                    state ==
                    STATE_STOPPED ||
                    !isRunning ||
                    shuttingDown
                ) {

                    miniOrbController.hide()

                } else {

                    miniOrbController.refresh(
                        enabled = true,
                        state =
                            state
                    )
                }
            }

        if (
            Looper.myLooper() ==
            Looper.getMainLooper()
        ) {

            updateOrb()

        } else {

            mainHandler.post {
                updateOrb()
            }
        }

        sendBroadcast(
            Intent(
                ACTION_STATUS
            ).apply {

                setPackage(
                    packageName
                )

                putExtra(
                    EXTRA_STATUS_TEXT,
                    text
                )

                putExtra(
                    EXTRA_STATUS_STATE,
state
                )
            }
        )
    }

    // =========================================================
    // STOP / DESTROY
    // =========================================================

    private fun shutdownAyana() {

        if (shuttingDown) {
            return
        }

        shuttingDown =
            true

        isRunning =
            false

        cancelRequested =
            true

        executionKernel.cancel(
            reason = "shutdown"
        )

        commandGeneration++

        listenMode =
            ListenMode.BUSY

        try {
            currentAgentConnection
                ?.disconnect()
        } catch (_: Exception) {
        }

        try {
            currentAgentThread
                ?.interrupt()
        } catch (_: Exception) {
        }

        stopCancelListenerWatchdog()
        backgroundImageIndexer.stop()
        miniOrbController.hide()

        try {
            val durable =
                durableGoalStore
                    .getRecoverable()

            if (durable != null) {
                durableGoalStore
                    .markCancelled(
                        durable.optString(
                            "id"
                        ),
                        "AYANA полностью остановлена пользователем"
                    )
            }
        } catch (_: Exception) {
        }

        currentDurableGoalId =
            null

        val historyId =
            activeCommandHistoryId

        if (
            historyId !=
            null
        ) {

            commandHistoryStore.finishCancelled(
                id =
                    historyId,
                result =
                    "AYANA полностью остановлена пользователем",
                source =
                    "stop_ayana"
            )

            activeCommandHistoryId =
                null
        }

        broadcastStatus(
            "AYANA остановлена",
            STATE_STOPPED
        )

        stopSherpaListening()
        stopCurrentAudio()

        mainHandler
            .removeCallbacksAndMessages(
                null
            )

        val thread =
            recordingThread

        if (
            thread != null &&
            thread !==
            Thread.currentThread()
        ) {

            try {
                thread.join(
                    500L
                )
            } catch (_: Exception) {
            }
        }

        try {
            recognizer
                ?.release()
        } catch (_: Exception) {
        }

        recognizer =
            null

        modelReady =
            false
        capabilityRegistry
            .recordRecognitionReady(
                false
            )

        if (
            Build.VERSION.SDK_INT >=
            24
        ) {

            stopForeground(
                STOP_FOREGROUND_REMOVE
            )

        } else {

            @Suppress("DEPRECATION")
            stopForeground(true)
        }

        stopSelf()
    }

    override fun onDestroy() {

        shuttingDown =
            true

        isRunning =
            false

        cancelRequested =
            true

        commandGeneration++

        listenMode =
            ListenMode.BUSY

        stopCancelListenerWatchdog()
        backgroundImageIndexer.stop()
        stopSherpaListening()
        stopCurrentAudio()

        mainHandler
            .removeCallbacksAndMessages(
                null
            )

        val thread =
            recordingThread

        if (
            thread != null &&
            thread !==
            Thread.currentThread()
        ) {

            try {
                thread.join(
                    500L
                )
            } catch (_: Exception) {
            }
        }

        try {
            recognizer
                ?.release()
        } catch (_: Exception) {
        }

        recognizer =
            null

        modelReady =
            false
        capabilityRegistry
            .recordRecognitionReady(
                false
            )

        miniOrbController
            .hide()

        try {
            durableGoalStore
                .markInterruptedGoals(
                    "service_destroyed"
                )
        } catch (_: Exception) {
        }

        super.onDestroy()
    }

